/// `is_dir()` is a stat — file I/O this crate may never do itself
/// (`docs/DISCIPLINE.md` §3) — so Enter sends [`Cmd::CheckNewSessionCwd`]
/// and leaves the modal open rather than deciding on the spot;
/// [`update_new_session_cwd_checked`] is where the verdict actually lands
/// and the pre-round-trip success path (mint the key, stage the open) now
/// lives. `App::modal_new_session_check_pending` blocks a second Enter
/// while one round trip is already in flight — without it, Enter twice in a
/// row before the first answer lands would kick off two checks (and, since
/// the discriminator from the previous round fixed the double-open bug that
/// used to *corrupt* state, two merely-redundant panes rather than one
/// corrupted one — still wrong, still worth preventing outright).
fn confirm_new_session_modal(app: &mut App) -> Vec<Cmd> {
    let Some(Modal::NewSession(_)) = app.modal() else {
        return Vec::new();
    };
    if app.modal_new_session_check_pending() {
        return Vec::new();
    }
    let Some(cwd) = app.modal_new_session_target() else {
        return Vec::new();
    };
    app.modal_begin_new_session_check();
    vec![Cmd::CheckNewSessionCwd { cwd }]
}

/// The other half of [`confirm_new_session_modal`]'s round trip: the
/// shell's answer to whether the checked cwd is a real directory.
///
/// `App::modal_new_session_check_resolves` is the stale-result guard: the
/// operator can keep typing while the stat is in flight, so `cwd` (what was
/// actually checked) is compared against the modal's *current* target
/// before this verdict is trusted, and the pending-check marker is cleared
/// either way — a verdict that no longer applies is simply dropped, not
/// requeued, leaving the modal open and Enter live again for a fresh check
/// against whatever the operator has typed since.
fn update_new_session_cwd_checked(
    state: &mut EmporiumState,
    app: &mut App,
    cwd: PathBuf,
    is_dir: bool,
) -> Vec<Cmd> {
    if !app.modal_new_session_check_resolves(&cwd) {
        return Vec::new();
    }
    if !is_dir {
        app.modal_set_error(format!("{} is not a directory", cwd.display()));
        return Vec::new();
    }
    // Read before `close_modal` drops the `NewSessionState` this came from.
    let agent = app.modal_new_session_agent();
    app.close_modal();
    let key = state.mint_plain_key(&cwd);
    if agent == AgentKind::Codex {
        state.unresolved_codex.insert(key.clone());
    }
    state.pending_opens.insert(key.clone(), PendingOpen::Solo);
    vec![Cmd::OpenEmbedded {
        key,
        target: SessionToOpen {
            id: String::new(),
            agent,
            title: cwd.display().to_string(),
            cwd,
        },
        brigade: None,
        model: None,
        effort: None,
        permission_mode: None,
        disallowed_tools: None,
        autocompact: None,
        first_prompt: None,
    }]
}

fn confirm_disband_modal(state: &mut EmporiumState, app: &mut App) -> Vec<Cmd> {
    let Some(Modal::ConfirmDisband { brigade_id, .. }) = app.modal() else {
        return Vec::new();
    };
    let brigade_id = *brigade_id;
    app.close_modal();
    // From the confirm, not from the result: a pane that ends while the disband
    // is in flight is not a Worker leaving a brigade that is about to be gone.
    state.disbanding.insert(brigade_id);
    vec![Cmd::Store(StoreIntent::Disband { brigade_id })]
}

/// Open the close dialog for `brigade_id`, or say why not: the brigade is
/// already closing, is being disbanded, or has nothing hosted to close. Shared by
/// the Director's Prefix+`x` and the list's `x`, so both refuse the same way.
fn open_close_brigade(state: &mut EmporiumState, app: &mut App, brigade_id: BrigadeId) -> Vec<Cmd> {
    let name = state.brigade_name(app, brigade_id);
    if state.closing.contains_key(&brigade_id) {
        state.status = Some(format!("{name} is already closing"));
    } else if state.disbanding.contains(&brigade_id) {
        state.status = Some(format!("{name} is being disbanded"));
    } else if state.hosted_panes_of(brigade_id).is_empty() {
        state.status = Some(format!(
            "nothing of {name} is running \u{2014} Enter on its Director's row opens it"
        ));
    } else {
        app.open_confirm_close_brigade_modal(brigade_id, name);
    }
    Vec::new()
}

/// Confirm the close dialog: end every pane the brigade hosts, delete nothing.
///
/// The panes are read from the state now, not from when the dialog opened: one
/// that ended meanwhile is simply not there, and one that began is ended too. All
/// of them are ended through [`kill_pane`] (hung up, then killed if they stay past
/// [`PANE_END_GRACE`]), which records each exit as one banto asked for, so a Worker is not
/// relaunched and not dismissed for having left, and a Director is not read as
/// having wandered off. The brigade, its members and their session ids, its mail
/// and read cursors, request records and a consultation in progress all stay in
/// the store, which this never writes: a Goinkyo in consultation is still a
/// member and resumes with the rest when the Director's row is opened.
///
/// A brigade on the stage empties it (and the focus goes back to the list, since
/// a pane focus on an empty stage strands every key); one that is off stage
/// leaves what is showing and the focus alone. What the panes left queued or
/// half-counted is dropped here rather than when their exits arrive
/// ([`drop_leftovers_of_ended_panes`], which says why). The exits come as
/// ordinary events and are folded into one line by [`settle_closing`], which also
/// gives up after [`CLOSE_GIVE_UP`] if a pane did not end.
fn confirm_close_brigade_modal(state: &mut EmporiumState, app: &mut App, now: Instant) -> Vec<Cmd> {
    let Some(Modal::ConfirmCloseBrigade { brigade_id, .. }) = app.modal() else {
        return Vec::new();
    };
    let brigade_id = *brigade_id;
    app.close_modal();
    let hosted = state.hosted_panes_of(brigade_id);
    if state.closing.contains_key(&brigade_id)
        || state.disbanding.contains(&brigade_id)
        || hosted.is_empty()
    {
        return Vec::new();
    }
    state.closing.insert(brigade_id, now);
    if matches!(&state.stage, Stage::Brigade { id, .. } if *id == brigade_id) {
        state.stage = Stage::Empty;
        state.settle_focus();
    }
    drop_leftovers_of_ended_panes(state, brigade_id, &hosted);
    hosted
        .into_iter()
        .filter_map(|key| kill_pane(state, key))
        .collect()
}

/// End the closing of every brigade that has finished: no pane of it is hosted
/// or being opened any more. Says it once, as the one line the brigade's exits
/// were folded into (`update_pty_exited` says nothing for them). Run at the end
/// of every update, so it holds however the last pane left (an exit, a pane
/// whose output was lost, a spawn that failed).
fn settle_closing(state: &mut EmporiumState, app: &App, now: Instant) {
    if state.closing.is_empty() {
        return;
    }
    let mut ids: Vec<BrigadeId> = state.closing.keys().copied().collect();
    ids.sort_unstable();
    for brigade_id in ids {
        let left = state.hosted_panes_of(brigade_id).len() + state.pending_opens_of(brigade_id);
        let name = state.brigade_name(app, brigade_id);
        if left == 0 {
            state.closing.remove(&brigade_id);
            state.set_status(format!("{name} closed"), now);
        } else if state
            .closing
            .get(&brigade_id)
            .is_some_and(|since| now.saturating_duration_since(*since) >= CLOSE_GIVE_UP)
        {
            // Not killed again, and the panes keep their expected-exit records:
            // if one does end later it is still an exit banto asked for.
            state.closing.remove(&brigade_id);
            let plural = if left == 1 { "" } else { "s" };
            state.set_status(
                format!("{name}: {left} pane{plural} did not end after the close"),
                now,
            );
        }
    }
}

/// `x` on a list row: request the membership of the row, as Enter and `B` do —
/// [`update_membership_resolved`] decides what the row is and what to do.
fn close_key(state: &mut EmporiumState, app: &App) -> Vec<Cmd> {
    let Some(row) = app.selected_row() else {
        return Vec::new();
    };
    state.pending_membership = Some((PendingMembership::CloseKey, row.id.clone()));
    vec![Cmd::Store(StoreIntent::ResolveMembership {
        session_id: row.id.clone(),
    })]
}

/// Confirm the prefix-`x` dialog. For a brigade member other than the Director —
/// a Worker or the Goinkyo, the dialog's `dismisses` is `Some` — confirming
/// **dismisses** it: it leaves the brigade for good (membership, read cursor,
/// mail addressed to it) and its pane ends. There is no "close the pane and keep
/// the member": a Worker is disposable, and a member with no pane has no tile to
/// act on, so keeping one only made invisible members. (A restart is unaffected:
/// staging reopens every member there is.) For a single session, `dismisses` is
/// `None` and confirming only ends the process. A Director's pane never gets
/// here: its Prefix+`x` closes the brigade ([`confirm_close_brigade_modal`]).
///
/// Dismissing needs `(brigade_id, token)` before `StoreIntent::DismissWorker` can
/// be built: a still-awaiting-discovery member's synthetic key already embeds
/// them ([`SessionKey::worker_identity`] — Worker-named, Goinkyo-shaped too, see
/// its own doc), so that path builds the intent right here; a resolved member's
/// real session id does not, so that path stashes
/// [`PendingMembership::DismissWorker`] and spends one `ResolveMembership` round
/// trip instead. Either way `state.pending_dismiss` is set first, so
/// [`update_worker_dismissed`] knows which pane to actually remove once the
/// dismissal (or its round trip) comes back. The passive `Event::PtyExited` fold
/// (see `update_pty_exited`) is what cleans up a pane that was only killed.
/// Confirm the close-the-Plan dialog. A brigade that is being closed or disbanded
/// is ending its panes already, and a Plan closed from under that would race the
/// disband's own close of it, so it is refused with a line instead.
fn confirm_close_planner_modal(state: &mut EmporiumState, app: &mut App) -> Vec<Cmd> {
    let Some(Modal::ConfirmClosePlanner { brigade_id, name }) = app.modal() else {
        return Vec::new();
    };
    let (brigade_id, name) = (*brigade_id, name.clone());
    app.close_modal();
    if state.closing.contains_key(&brigade_id) || state.disbanding.contains(&brigade_id) {
        state.status = Some(format!(
            "{name} is closing \u{2014} its Plan was left as it is"
        ));
        return Vec::new();
    }
    vec![Cmd::Store(StoreIntent::ClosePlanner { brigade_id })]
}

fn confirm_kill_modal(state: &mut EmporiumState, app: &mut App) -> Vec<Cmd> {
    let Some(Modal::ConfirmKill { key, dismisses, .. }) = app.modal() else {
        return Vec::new();
    };
    let key = SessionKey::from_id(key);
    let dismiss = dismisses.is_some();
    app.close_modal();
    if !dismiss {
        return kill_pane(state, key).into_iter().collect();
    }
    state.pending_dismiss = Some(key.clone());
    state.pending_dismiss_member = None;
    match key.worker_identity() {
        Some((brigade_id, token)) => {
            state.pending_dismiss_member = Some((brigade_id, token.clone()));
            vec![Cmd::Store(StoreIntent::DismissWorker { brigade_id, token })]
        }
        None => {
            state.pending_membership =
                Some((PendingMembership::DismissWorker, key.as_str().to_string()));
            vec![Cmd::Store(StoreIntent::ResolveMembership {
                session_id: key.as_str().to_string(),
            })]
        }
    }
}

/// Enter / double-click on the sidebar: request membership resolution
/// first (see the module doc) — [`update_membership_resolved`] does the
/// actual staging/opening once the shell answers.
fn activate_selected(state: &mut EmporiumState, app: &App) -> Vec<Cmd> {
    let Some(row) = app.selected_row() else {
        return Vec::new();
    };
    state.pending_membership = Some((PendingMembership::Activate, row.id.clone()));
    vec![Cmd::Store(StoreIntent::ResolveMembership {
        session_id: row.id.clone(),
    })]
}

/// `B`: same membership-resolution round trip as [`activate_selected`].
fn brigade_key(state: &mut EmporiumState, app: &App) -> Vec<Cmd> {
    let Some(row) = app.selected_row() else {
        return Vec::new();
    };
    state.pending_membership = Some((PendingMembership::BrigadeKey, row.id.clone()));
    vec![Cmd::Store(StoreIntent::ResolveMembership {
        session_id: row.id.clone(),
    })]
}

fn update_membership_resolved(
    state: &mut EmporiumState,
    app: &mut App,
    brigade: &BrigadeConfig,
    session_id: String,
    membership: Option<(BrigadeId, MemberToken, BrigadeRole)>,
    members: Option<Vec<(MemberToken, BrigadeRole, Option<String>)>>,
    layout: Option<StoredLayout>,
) -> Vec<Cmd> {
    // One slot, and an answer belongs to the session that was asked about: Enter
    // on one row and `x` on another before the first answer comes back would
    // otherwise hand the first row's membership to the second's purpose (a close
    // dialog for a brigade the operator never pointed at). An answer for any
    // other session is dropped and the slot kept for its own.
    let Some((_, asked)) = &state.pending_membership else {
        return Vec::new();
    };
    if *asked != session_id {
        return Vec::new();
    }
    let Some((purpose, _)) = state.pending_membership.take() else {
        return Vec::new();
    };
    // Handled before the `row_for_id` guard below (which `DismissWorker`
    // doesn't need `row` for at all): the dismissed pane's key already lives
    // in `pending_dismiss`, and clearing it here on an unexpected answer
    // (not a Worker anymore, or not found) matters regardless of whether
    // this session still has a row.
    if matches!(purpose, PendingMembership::DismissWorker) {
        // A Goinkyo dismisses exactly the way a Worker does — same store
        // operation, same pane cleanup — so it shares this arm rather than
        // landing in the abort one below; only a Director can't be
        // dismissed this way (that's disband's job, `B`). `Some((_, _,
        // BrigadeRole::Director)) | None` spelled out rather than `_`: a
        // role added later has to land in one arm or the other explicitly,
        // not fall silently into whichever one the wildcard used to catch —
        // an unexpected answer here has always meant "abort", never
        // "guess".
        return match membership {
            Some((brigade_id, token, BrigadeRole::Worker | BrigadeRole::Goinkyo)) => {
                state.pending_dismiss_member = Some((brigade_id, token.clone()));
                vec![Cmd::Store(StoreIntent::DismissWorker { brigade_id, token })]
            }
            // An answer that is no member to dismiss: said, never silent — the
            // pane is still there and the operator pressed Enter.
            Some((_, _, BrigadeRole::Director)) => {
                state.pending_dismiss = None;
                state.pending_dismiss_member = None;
                state.status = Some(
                    "the Director cannot be dismissed — disband the brigade (B) to remove it"
                        .to_string(),
                );
                Vec::new()
            }
            // A Planner is not dismissed: its row leaves only with the Plan it
            // belongs to, in the transaction that closes it. Prefix+x on its tile
            // opens that dialog and never reaches here; this is for a dismissal that
            // was asked for some other way.
            Some((_, _, BrigadeRole::Planner)) => {
                state.pending_dismiss = None;
                state.pending_dismiss_member = None;
                state.status = Some(
                    "the Planner leaves with its Plan \u{2014} Prefix+x on its tile closes the Plan"
                        .to_string(),
                );
                Vec::new()
            }
            None => {
                state.pending_dismiss = None;
                state.pending_dismiss_member = None;
                state.status = Some(
                    "could not tell which brigade member this pane is — nothing was dismissed"
                        .to_string(),
                );
                Vec::new()
            }
        };
    }
    let Some(row) = app.row_for_id(&session_id).cloned() else {
        return Vec::new();
    };
    match purpose {
        PendingMembership::Activate => match membership {
            Some((brigade_id, _, BrigadeRole::Director)) => {
                adopt_stored_layout(state, brigade_id, layout.as_ref());
                stage_brigade(
                    state,
                    app,
                    brigade_id,
                    &members.unwrap_or_default(),
                    brigade,
                )
            }
            // Spelled out rather than `_`, same reasoning as the
            // `DismissWorker` branch above: staging the whole brigade is a
            // Director-only action, so a Goinkyo activated directly opens
            // solo, same as a Worker does. Not while its brigade is closing:
            // the pane is on its way out, and showing it would hand the
            // operator a pane that dies under their hands.
            Some((
                brigade_id,
                _,
                BrigadeRole::Worker | BrigadeRole::Goinkyo | BrigadeRole::Planner,
            )) if refuse_while_closing(state, app, brigade_id) => Vec::new(),
            Some((_, _, BrigadeRole::Worker | BrigadeRole::Goinkyo | BrigadeRole::Planner))
            | None => open_solo(state, &row),
        },
        // `x` on a row. A Director's row closes its brigade, whichever of its
        // panes are hosted and wherever (the Director's own may be gone). A
        // Worker's or Goinkyo's row never ends it: that is a dismissal, which
        // leaves the brigade for good and belongs to the pane's own tile, where
        // the operator can see whom they are dismissing. (Such a row is not
        // normally in the list at all: `App::hidden` keeps members out at every
        // reveal level; one shows only in the moment between a member's session
        // appearing and the reload that hides it.) A session that is no member is
        // a single session: its own pane, if it has one, ends as Prefix+`x` on
        // its tile would end it.
        PendingMembership::CloseKey => match membership {
            Some((brigade_id, _, BrigadeRole::Director)) => {
                open_close_brigade(state, app, brigade_id)
            }
            Some((_, _, BrigadeRole::Worker | BrigadeRole::Goinkyo | BrigadeRole::Planner)) => {
                state.status = Some(
                    "that session is a brigade's Worker, Goinkyo or Planner \u{2014} dismiss \
                     (or close) it with Prefix+x on its tile"
                        .to_string(),
                );
                Vec::new()
            }
            None => {
                let key = SessionKey::from_id(&row.id);
                if state.screens.contains_key(&key) {
                    let title = row.sentence_name();
                    app.open_confirm_kill_modal(key.as_str().to_string(), title, None);
                } else if row.agent == AgentKind::Codex && !state.unresolved_codex.is_empty() {
                    // Not "no open pane": a new Codex pane that banto has not
                    // identified may well be this row's, and it has no way to say.
                    state.refuse_for_unidentified_codex();
                } else {
                    state.status = Some(format!("{} has no open pane", row.sentence_name()));
                }
                Vec::new()
            }
        },
        PendingMembership::BrigadeKey => match membership {
            Some((brigade_id, _, BrigadeRole::Director)) => {
                app.open_confirm_disband_modal(brigade_id, row.sentence_name());
                Vec::new()
            }
            Some((_, _, BrigadeRole::Worker)) => {
                state.status = Some("workers can't be promoted to Director directly".to_string());
                Vec::new()
            }
            // Its own arm rather than folded into the Worker one above: a
            // Goinkyo is not a Worker, and reusing that exact message would
            // tell the operator something false about who was refused.
            Some((_, _, BrigadeRole::Goinkyo)) => {
                state.status = Some("a goinkyo can't be promoted to Director directly".to_string());
                Vec::new()
            }
            Some((_, _, BrigadeRole::Planner)) => {
                state.status = Some("a planner can't be promoted to Director directly".to_string());
                Vec::new()
            }
            // Outranks the two gates inside `begin_brigade_formation`
            // (`Select`'s picker, the codex-trust check): reopening the
            // Director's own pane is the most disruptive of the three
            // (running work is lost) and the cheapest to abort (nothing has
            // been picked or written yet), so it has to be asked about
            // first — picking a product and a model only to be told the
            // pane is about to restart anyway would be the wrong order. See
            // `confirm_director_reopen_modal`/`update_pty_exited` for the
            // other half of this round trip.
            None if row.agent == AgentKind::Codex && !state.unresolved_codex.is_empty() => {
                state.refuse_for_unidentified_codex();
                Vec::new()
            }
            None if state
                .lost_output_waiting_for_exit
                .contains(&SessionKey::from_id(&row.id)) =>
            {
                state.status = Some(
                    "waiting for the previous process to exit before forming a brigade".to_string(),
                );
                Vec::new()
            }
            None if state.screens.contains_key(&SessionKey::from_id(&row.id)) => {
                app.open_confirm_director_reopen_modal(row.id.clone(), row.sentence_name());
                Vec::new()
            }
            None => begin_brigade_formation(state, app, brigade, &row),
        },
        // Handled above, before the `row_for_id` guard.
        PendingMembership::DismissWorker => Vec::new(),
    }
}

/// Whether a brigade formed from this Director and these Workers will hold a
/// Codex member, and so needs banto's hook trusted before it forms. The
/// Director is briefed by the same hook as a Worker, so a Codex Director with
/// Claude Workers needs the review as much as the reverse; checking only the
/// Workers' product let such a brigade form with its Director silently
/// unbriefed.
fn forms_a_codex_member(director: AgentKind, workers: AgentKind) -> bool {
    director == AgentKind::Codex || workers == AgentKind::Codex
}

/// The formation decision proper, once nothing needs to reopen first (see
/// `update_membership_resolved`'s `None` branch, and `update_pty_exited` for
/// the resumed-after-reopen path): `Select` interrupts with a picker instead
/// of issuing `FormBrigade` right away — the operator has to choose a
/// product (and, given the product, a model) before there's anything to
/// form, see `confirm_worker_agent_modal` for the other half of that round
/// trip. Otherwise the Worker product resolves immediately, and — if either it
/// or the Director's is Codex ([`forms_a_codex_member`]) — routes through a
/// trust check first, same reasoning, see `update_codex_trust_checked`.
fn begin_brigade_formation(
    state: &mut EmporiumState,
    app: &mut App,
    brigade: &BrigadeConfig,
    row: &SessionRow,
) -> Vec<Cmd> {
    if row.agent == AgentKind::Codex && !state.unresolved_codex.is_empty() {
        state.refuse_for_unidentified_codex();
        return Vec::new();
    }
    if brigade.worker_agent == WorkerAgentSetting::Select {
        state.pending_brigade_formation = Some(PendingBrigadeFormation {
            director_row_id: row.id.clone(),
            director_agent: row.agent,
            name: formation_name(row),
            cwd: row.cwd.clone().unwrap_or_else(|| PathBuf::from(".")),
            worker_count: brigade.worker_count(),
        });
        app.open_worker_agent_modal(
            WorkerPickerFor::FormBrigade,
            state.last_worker_agent.unwrap_or(row.agent),
            WorkerDefaults::of(brigade),
        );
        return Vec::new();
    }
    let worker_agent = resolve_worker_agent(brigade.worker_agent, row.agent);
    let worker_model = brigade
        .worker_model_for(worker_agent)
        .unwrap_or("")
        .to_string();
    let worker_effort = brigade
        .worker_effort_for(worker_agent)
        .unwrap_or("")
        .to_string();
    if forms_a_codex_member(row.agent, worker_agent) {
        state.pending_codex_trust_formation = Some(PendingCodexTrustFormation {
            director_row_id: row.id.clone(),
            director_agent: row.agent,
            name: formation_name(row),
            cwd: row.cwd.clone().unwrap_or_else(|| PathBuf::from(".")),
            worker_count: brigade.worker_count(),
            worker_agent,
            worker_model,
            worker_effort,
        });
        return vec![Cmd::CheckCodexTrust];
    }
    vec![Cmd::Store(StoreIntent::FormBrigade {
        director_row_id: row.id.clone(),
        director_agent: row.agent,
        name: formation_name(row),
        cwd: row.cwd.clone().unwrap_or_else(|| PathBuf::from(".")),
        worker_count: brigade.worker_count(),
        worker_agent,
        worker_model,
        worker_effort,
    })]
}

/// The name a brigade is stored under when it is formed on `row`: the row's
/// title, or an empty string when it has none. An empty name is how "no name"
/// is kept — [`EmporiumState::brigade_name`] counts it as absent and falls
/// through to `brigade N` — whereas the row's id, which this used to freeze
/// when the Director had no title yet, was stored as the brigade's name for
/// good and said to the operator as a UUID.
fn formation_name(row: &SessionRow) -> String {
    row.title().unwrap_or_default().to_string()
}

/// Answers `Cmd::CheckCodexTrust`, always following a
/// [`PendingCodexTrustFormation`] stash (`update_membership_resolved`'s
/// non-`Select` branch, or `confirm_worker_agent_modal` once `Select`'s own
/// picker resolves) — a no-op if it's missing, which shouldn't happen
/// structurally.
///
/// Three outcomes, and only one of them re-issues `FormBrigade`:
/// - **Not launchable at all** (banto's own path has a space — Codex can
///   never fire a hook command from one, `hook_command_is_launchable`'s
///   doc): a trust prompt would only ask the operator to approve a hook
///   that can never run, so it's skipped — a status line names the cause
///   (the same wording `codex_trust_notice` already uses for it) and
///   formation proceeds anyway. Unlike the "not primed" case below, there's
///   no action a pane could offer that would fix this one before forming.
/// - **Primed**: proceeds straight to `FormBrigade`, unchanged from before
///   this check existed.
/// - **Neither**: opens [`Modal::ConfirmCodexTrust`] and stops — formation
///   is abandoned for this press, not resumed once the operator approves or
///   cancels. Resuming it would need to know whether the approval actually
///   took (Codex hashes its own trust record; banto cannot verify a match
///   against it — see `banto_io::codex_trust`'s module doc), and treating an
///   unverifiable "probably fine" as ground truth is exactly the shape of
///   mistake this project has paid for before. The operator presses `B`
///   again once they're done.
fn update_codex_trust_checked(
    state: &mut EmporiumState,
    app: &mut App,
    primed: bool,
    hook_launchable: bool,
    now: Instant,
) -> Vec<Cmd> {
    let Some(formation) = state.pending_codex_trust_formation.take() else {
        return Vec::new();
    };
    if formation.director_agent == AgentKind::Codex && !state.unresolved_codex.is_empty() {
        state.refuse_for_unidentified_codex();
        return Vec::new();
    }
    if state
        .lost_output_waiting_for_exit
        .contains(&SessionKey::from_id(&formation.director_row_id))
    {
        state.set_status(
            "waiting for the previous process to exit before forming a brigade".to_string(),
            now,
        );
        return Vec::new();
    }
    if !hook_launchable {
        state.set_status(
            "codex: banto's own path contains a space, which Codex cannot launch a hook \
             from — this brigade's Codex member(s) start unbriefed"
                .to_string(),
            now,
        );
        return vec![Cmd::Store(StoreIntent::FormBrigade {
            director_row_id: formation.director_row_id,
            director_agent: formation.director_agent,
            name: formation.name,
            cwd: formation.cwd,
            worker_count: formation.worker_count,
            worker_agent: formation.worker_agent,
            worker_model: formation.worker_model,
            worker_effort: formation.worker_effort,
        })];
    }
    if primed {
        return vec![Cmd::Store(StoreIntent::FormBrigade {
            director_row_id: formation.director_row_id,
            director_agent: formation.director_agent,
            name: formation.name,
            cwd: formation.cwd,
            worker_count: formation.worker_count,
            worker_agent: formation.worker_agent,
            worker_model: formation.worker_model,
            worker_effort: formation.worker_effort,
        })];
    }
    app.open_confirm_codex_trust_modal();
    Vec::new()
}

/// Confirm [`Modal::ConfirmCodexTrust`]: mint a fresh key, stage it as the
/// (eventual) solo pane the same way any other fresh open does
/// (`PendingOpen::Solo` — reused as-is, not a new variant, because staging
/// is all this needs: no session row, no discovery), and ask the shell to
/// spawn Codex's trust-review startup under it. See `Cmd::OpenCodexTrustPane`
/// for why this never becomes a tracked session.
fn confirm_codex_trust_modal(state: &mut EmporiumState, app: &mut App) -> Vec<Cmd> {
    if !matches!(app.modal(), Some(Modal::ConfirmCodexTrust)) {
        return Vec::new();
    }
    app.close_modal();
    let key = state.mint_plain_key(std::path::Path::new(".codex-trust"));
    state.pending_opens.insert(key.clone(), PendingOpen::Solo);
    vec![Cmd::OpenCodexTrustPane { key }]
}

/// Confirm [`Modal::ConfirmDirectorReopen`]: kill the Director-to-be's
/// already-open pane and stash `pending_director_reopen` so
/// [`update_pty_exited`] can pick formation back up (via
/// [`begin_brigade_formation`]) once — not before — that pane's process has
/// actually exited. Nothing is written to the store here or by that
/// continuation's first steps; Esc leaves the brigade unformed with no
/// cleanup needed, same as never having pressed `B` at all.
fn confirm_director_reopen_modal(state: &mut EmporiumState, app: &mut App) -> Vec<Cmd> {
    let Some(Modal::ConfirmDirectorReopen {
        director_row_id, ..
    }) = app.modal()
    else {
        return Vec::new();
    };
    let director_row_id = director_row_id.clone();
    if !state.unresolved_codex.is_empty()
        && app
            .row_for_id(&director_row_id)
            .is_none_or(|row| row.agent == AgentKind::Codex)
    {
        state.refuse_for_unidentified_codex();
        app.close_modal();
        return Vec::new();
    }
    if state
        .lost_output_waiting_for_exit
        .contains(&SessionKey::from_id(&director_row_id))
    {
        state.status =
            Some("waiting for the previous process to exit before forming a brigade".to_string());
        app.close_modal();
        return Vec::new();
    }
    app.close_modal();
    let director_key = SessionKey::from_id(&director_row_id);
    state.pending_director_reopen = Some(director_row_id);
    kill_pane(state, director_key).into_iter().collect()
}

/// Stage `row` solo: reuse its screen if already open, else request a spawn.
fn open_solo(state: &mut EmporiumState, row: &SessionRow) -> Vec<Cmd> {
    let key = SessionKey::from_id(&row.id);
    if state.screens.contains_key(&key) {
        state.stage = Stage::Solo(key);
        state.focus = Focus::Pane;
        return Vec::new();
    }
    if state.lost_output_waiting_for_exit.contains(&key) {
        state.status = Some("waiting for the previous process to exit before resuming".to_string());
        return Vec::new();
    }
    if row.agent == AgentKind::Codex && !state.unresolved_codex.is_empty() {
        state.refuse_for_unidentified_codex();
        return Vec::new();
    }
    state.pending_opens.insert(key.clone(), PendingOpen::Solo);
    vec![Cmd::OpenEmbedded {
        key,
        target: SessionToOpen {
            id: row.id.clone(),
            agent: row.agent,
            title: row.sentence_name(),
            cwd: row.cwd.clone().unwrap_or_else(|| PathBuf::from(".")),
        },
        brigade: None,
        model: None,
        effort: None,
        permission_mode: None,
        disallowed_tools: None,
        autocompact: None,
        first_prompt: None,
    }]
}

/// What a role is launched with on *every* launch, fresh or resumed —
/// everything about a member that banto's configuration decides for the role
/// rather than for the session.
///
/// Three things: who may approve a tool call (`permission_mode`) and which
/// tools exist to call (`disallowed_tools`), both Claude-only flags, and the
/// size of the window a session compacts at (`autocompact`), which both
/// products take. A Worker's own operator is no more watching every pane than
/// the Goinkyo's, so a Worker gets the non-default `permission_mode` too.
/// `disallowed_tools` stays Goinkyo-only: it answers "what may this role even
/// attempt", which only needs guarding for a role meant to be called holding
/// nothing of its own — a Worker's whole job is the editing that setting exists
/// to deter (see `BrigadeConfig::goinkyo_disallowed_tools`'s own doc). Closing
/// a consultation's pane mid-conversation and re-staging the brigade brings the
/// Goinkyo right back to an unattended prompt (or an editable working tree) if
/// one comes up, same as a fresh spawn.
///
/// `autocompact` is a **Worker's** alone, whichever product it runs. The
/// Director and the Goinkyo get nothing, whatever their product, and keep the
/// agent's own compaction setting. Like the two above it rides on every
/// launch: it is given as a launch flag, and banto does not count on a resumed
/// session remembering it. What each product is given for it is
/// `BrigadeConfig::worker_autocompact_for`'s to say.
///
/// The model and the reasoning effort are *not* here. They are decided once,
/// when a session is created, and never again: a resumed member passes neither
/// (`Cmd::OpenEmbedded { model: None, effort: None }`), so it keeps whatever the
/// operator last set inside it. A flag-less `codex resume` and `claude --resume`
/// restore the model the session last used, and `-m` on a Codex resume
/// overrides it and rewrites the thread's record at once (read in Codex's source
/// at tag `rust-v0.168.0` and in Claude Code's docs for 2.1.323; not measured by
/// running either). An earlier rule passed the configured model on every launch
/// because a resumed Worker once came up on the operator's own default instead
/// of the brigade's; that was a consequence of a configuration that was the
/// authority on what a member runs, and the operator's decision since is that
/// the session is.
///
/// The Director gets none of it: `BrigadeConfig` has no Director counterpart of
/// any of these three role flags, so each stays whatever the agent's own
/// settings say for it.
#[derive(Default)]
struct RoleLaunch {
    permission_mode: Option<String>,
    disallowed_tools: Option<String>,
    autocompact: Option<String>,
}

impl RoleLaunch {
    fn of(role: BrigadeRole, agent: AgentKind, brigade: &BrigadeConfig) -> Self {
        Self {
            autocompact: (role == BrigadeRole::Worker)
                .then(|| brigade.worker_autocompact_for(agent))
                .flatten(),
            permission_mode: match role {
                BrigadeRole::Worker => brigade.worker_permission_mode(),
                BrigadeRole::Goinkyo => brigade.goinkyo_permission_mode(),
                BrigadeRole::Planner => brigade.planner_permission_mode(),
                BrigadeRole::Director => None,
            }
            .map(str::to_string),
            disallowed_tools: (role == BrigadeRole::Goinkyo)
                .then(|| brigade.goinkyo_disallowed_tools())
                .flatten()
                .map(str::to_string),
        }
    }
}

/// The live panes core holds for the member `(brigade_id, token)`: a screen under
/// a key whose ownership maps name that member — whatever the key is. A member's
/// identity is its brigade and token, never its key: the key is a placeholder
/// until discovery re-keys it to a session id, and is renamed again by a
/// session move.
fn live_panes_of(state: &EmporiumState, brigade_id: BrigadeId, token: &str) -> Vec<SessionKey> {
    let mut keys: Vec<SessionKey> = state
        .screens
        .keys()
        .filter(|key| {
            state.member_brigades.get(*key) == Some(&brigade_id)
                && state.member_tokens.get(*key).map(String::as_str) == Some(token)
        })
        .cloned()
        .collect();
    keys.sort_by(|a, b| a.as_str().cmp(b.as_str()));
    keys
}

/// Whether any hosted pane belongs to the member `(brigade_id, token)`, under
/// whatever key it is held ([`live_panes_of`]). A pane is the member's wherever
/// discovery or a session move has renamed it to, so looking for it only
/// under the placeholder key a creation was made for would miss it.
fn member_has_pane(state: &EmporiumState, brigade_id: BrigadeId, token: &str) -> bool {
    !live_panes_of(state, brigade_id, token).is_empty()
}

/// The member an open issued and not yet answered by `Spawned`/`SpawnFailed` is
/// for, whatever key it was issued under: a brigade member's is named by the
/// ownership maps (written before the open is issued), a Director's by its
/// pending entry. A held creation is such an open — its pending entry is
/// registered when it is held.
fn opening_member<'a>(state: &'a EmporiumState, key: &SessionKey) -> Option<(BrigadeId, &'a str)> {
    match state.pending_opens.get(key)? {
        PendingOpen::Solo => None,
        PendingOpen::BrigadeDirector { brigade_id, .. } => Some((*brigade_id, DIRECTOR_TOKEN)),
        PendingOpen::BrigadeMember { brigade_id, .. } => state
            .member_tokens
            .get(key)
            .map(|token| (*brigade_id, token.as_str())),
    }
}

/// Whether the member is already open or being opened: a hosted pane under any
/// key mapped to it ([`member_has_pane`]), or an open in flight — issued and not
/// answered, or held — under any key ([`opening_member`]). The one question
/// every decision to open a member asks, so that none of them starts a second
/// session for a member that has one or is getting one: the guard in
/// [`open_worker`], the release of a held creation, the Workers a Director's
/// arrival opens, and staging. `except` is a key whose own pending open is not
/// counted: a held creation asking about itself.
fn member_open_or_opening(
    state: &EmporiumState,
    brigade_id: BrigadeId,
    token: &str,
    except: Option<&SessionKey>,
) -> bool {
    member_has_pane(state, brigade_id, token)
        || state.pending_opens.keys().any(|key| {
            Some(key) != except && opening_member(state, key) == Some((brigade_id, token))
        })
}

/// Which of several live panes for one member survives: the one whose key is the
/// session id the roster records for it, else the most recently spawned
/// ([`EmporiumState::spawn_order`], a counter the core keeps, so "recent" is
/// known and not guessed), else — only for a pane the core never saw spawn — the
/// greatest key, which is arbitrary but the same every time.
fn surviving_pane(
    state: &EmporiumState,
    live: &[SessionKey],
    recorded: Option<&SessionKey>,
) -> SessionKey {
    if let Some(recorded) = recorded
        && live.contains(recorded)
    {
        return recorded.clone();
    }
    live.iter()
        .max_by_key(|key| {
            (
                state.spawn_order.get(*key).copied(),
                key.as_str().to_string(),
            )
        })
        .cloned()
        .expect("at least one live pane")
}

/// Say that a brigade cannot be opened yet because it is still closing, and
/// answer whether that was the case. Opening it now would resume sessions whose
/// processes have not finished ending (a double resume), and the exits that are
/// still to come would take the new panes' state with them.
fn refuse_while_closing(state: &mut EmporiumState, app: &App, brigade_id: BrigadeId) -> bool {
    if !state.closing.contains_key(&brigade_id) {
        return false;
    }
    let name = state.brigade_name(app, brigade_id);
    state.status = Some(format!(
        "{name} is still closing \u{2014} try again in a moment"
    ));
    true
}

/// Stage brigade `brigade_id`: `members` is its full roster (token, role,
/// session id if known), already fetched by the shell alongside the
/// membership resolution that led here. A member whose row is already
/// embedded is added immediately; one that resolves to a row but isn't
/// embedded yet gets an `OpenEmbedded` request; a Worker with no resolved
/// session id yet (still awaiting discovery, or its process is gone) is
/// respawned fresh under its same token — disposable, unlike the Director,
/// whose failure to resolve just counts as "missing" (mirrors the
/// pre-migration `stage_brigade`).
fn stage_brigade(
    state: &mut EmporiumState,
    app: &App,
    brigade_id: BrigadeId,
    members: &[(MemberToken, BrigadeRole, Option<String>)],
    brigade: &BrigadeConfig,
) -> Vec<Cmd> {
    if refuse_while_closing(state, app, brigade_id) {
        return Vec::new();
    }
    if members.iter().any(|(_, _, id)| {
        id.as_deref().is_some_and(|id| {
            state
                .lost_output_waiting_for_exit
                .contains(&SessionKey::from_id(id))
        })
    }) {
        state.status =
            Some("waiting for a previous process to exit before staging this brigade".to_string());
        return Vec::new();
    }
    if !state.unresolved_codex.is_empty()
        && members.iter().any(|(token, _, id)| {
            live_panes_of(state, brigade_id, token).is_empty()
                && id
                    .as_deref()
                    .and_then(|id| app.row_for_id(id))
                    .is_some_and(|row| {
                        row.agent == AgentKind::Codex
                            && !state.screens.contains_key(&SessionKey::from_id(&row.id))
                    })
        })
    {
        state.refuse_for_unidentified_codex();
        return Vec::new();
    }
    let director_session_id = members
        .iter()
        .find(|(_, role, _)| *role == BrigadeRole::Director)
        .and_then(|(_, _, sid)| sid.as_deref());
    // Leniently `None` when the store's own Director row has no session id
    // recorded yet — `Stage::Brigade::director`'s own doc explains why that's
    // a legitimate state, not something to work around here.
    let director = director_session_id.map(SessionKey::from_id);
    let director_row = director_session_id.and_then(|sid| app.row_for_id(sid));
    let cwd = director_row
        .and_then(|row| row.cwd.clone())
        .unwrap_or_else(|| PathBuf::from("."));
    // A Director not yet resolved to a row can't say what product it is
    // either — the safe default rather than blocking staging on it, same
    // fallback `add_worker`/`update_brigade_formed` use.
    let director_agent = director_row.map_or(AgentKind::ClaudeCode, |row| row.agent);
    let fresh_worker_agent = resolve_worker_agent(brigade.worker_agent, director_agent);

    // The store's roster is in the order the members joined: the one record of
    // it that survives a restart. It replaces what this run learned, so the
    // order a brigade shows never depends on which pane happened to arrive
    // first or on how long the brigade was off the stage.
    state.member_order.insert(
        brigade_id,
        members.iter().map(|(token, _, _)| token.clone()).collect(),
    );
    let mut panes = Vec::new();
    let mut cmds = Vec::new();
    let mut missing = 0;
    let mut duplicates = 0;
    // Members whose resume is already in flight: not issued again, and they
    // arrive as ordinary spawns.
    let mut opening = 0;
    for (token, role, session_id) in members {
        // First, whatever the member's roster entry or session list say: if core
        // already holds a live pane for this member, that pane is its tile and
        // nothing is opened. Without this a Worker with a recorded session id but
        // no transcript (so no session row) was looked for only under its
        // placeholder key — where discovery had already re-keyed it away from —
        // and a second process was started each time the brigade was staged.
        let live = live_panes_of(state, brigade_id, token);
        if !live.is_empty() {
            let recorded = session_id.as_deref().map(SessionKey::from_id);
            let survivor = surviving_pane(state, &live, recorded.as_ref());
            // Any others are duplicates of one member — closed through the path
            // that marks the exit as asked for, so they are neither relaunched
            // nor counted as the Worker leaving the brigade. The kill is recorded
            // before the unstage that takes the duplicate's membership away, so
            // its exit still names the member; the survivor is never touched.
            for duplicate in live.iter().filter(|key| **key != survivor) {
                cmds.extend(kill_pane(state, duplicate.clone()));
                state.unstage(duplicate);
                duplicates += 1;
            }
            seed_role_guard(state, *role, brigade_id, &survivor);
            // The store should name the pane the operator sees, so the relay and
            // the MCP's liveness address it: a real id that differs from the
            // roster's is recorded (a placeholder key is discovery's to resolve).
            if !survivor.is_synthetic() && recorded.as_ref() != Some(&survivor) {
                cmds.push(Cmd::Store(StoreIntent::SetMemberSession {
                    brigade_id,
                    token: token.clone(),
                    session_id: survivor.as_str().to_string(),
                }));
            }
            panes.push(survivor);
            continue;
        }
        let resolved_row = session_id.as_deref().and_then(|sid| app.row_for_id(sid));
        match resolved_row {
            Some(row) => {
                let key = SessionKey::from_id(&row.id);
                // The same resume already issued and not yet answered: not
                // issued twice. The shell refuses to resume a session that is
                // already running, and its refusal would clear the first's
                // pending entry out from under that open's arrival, which
                // `update_spawned` then appends to this stage.
                if state.pending_opens.contains_key(&key) {
                    opening += 1;
                    continue;
                }
                // The maps are overwritten before the screen under `key` is
                // looked at: a session id is one member's (the shell refuses
                // to resume a session that is already running, and a session
                // joins one brigade), so no other member's pane is under it.
                state.member_tokens.insert(key.clone(), token.clone());
                state.member_brigades.insert(key.clone(), brigade_id);
                // Seeded here, ahead of the resume's own success or failure:
                // this is the one-shot spawn guard `update_goinkyo_awaiting_
                // spawn` checks (and, from here, the record that lets a
                // *later* re-stage tell "this consultation already has a
                // pane, live or in flight" from "the row is new" — see that
                // function's own doc for how it now tells the two apart by
                // whether the key it finds here is synthetic or real). Never
                // seeded for a Worker or Director — `goinkyo_pane` only ever
                // means "the current brigade's Goinkyo", nothing else reads
                // it for any other role.
                seed_role_guard(state, *role, brigade_id, &key);
                if state.screens.contains_key(&key) {
                    panes.push(key);
                } else {
                    state.pending_opens.insert(
                        key.clone(),
                        // Resuming a known id: nothing to discover, and no
                        // first prompt (`Cmd::OpenEmbedded::first_prompt`
                        // belongs to a creation).
                        PendingOpen::BrigadeMember {
                            brigade_id,
                            first_turn: None,
                        },
                    );
                    let launch = RoleLaunch::of(*role, row.agent, brigade);
                    cmds.push(Cmd::OpenEmbedded {
                        key,
                        target: SessionToOpen {
                            id: row.id.clone(),
                            agent: row.agent,
                            title: row.sentence_name(),
                            cwd: row.cwd.clone().unwrap_or_else(|| PathBuf::from(".")),
                        },
                        brigade: Some((brigade_id, token.clone(), *role)),
                        // The session exists: neither a model nor an effort
                        // (`RoleLaunch`'s doc).
                        model: None,
                        effort: None,
                        permission_mode: launch.permission_mode,
                        disallowed_tools: launch.disallowed_tools,
                        autocompact: launch.autocompact,
                        first_prompt: None,
                    });
                }
            }
            None if *role == BrigadeRole::Worker => {
                // A Worker with no id yet is identified only by its synthetic
                // key, so "is it already open?" has to be asked against that
                // key — the `Some(row)` arm's `screens` check above cannot
                // see it. Re-staging a cell whose Worker is alive but still
                // unidentified (Claude writes a session's jsonl at its first
                // *turn*, so discovery stays pending for as long as nobody
                // types into the pane) would otherwise spawn a second child
                // under the same key: the shell's handle map would replace
                // the live one — closing its PTY, killing it on Unix — and
                // the pane would blink back to an empty prompt.
                let key = SessionKey::new_worker(brigade_id, token);
                state.member_tokens.insert(key.clone(), token.clone());
                state.member_brigades.insert(key.clone(), brigade_id);
                if state.screens.contains_key(&key) {
                    panes.push(key);
                } else {
                    // A Worker whose process died before its session was ever
                    // discovered has nothing to resume, so this creates one: it
                    // gets the configured defaults. What a picker said when the
                    // Worker was first added is not kept anywhere, so it cannot
                    // be reapplied here.
                    cmds.extend(open_worker(
                        state,
                        brigade_id,
                        token,
                        &cwd,
                        WorkerChoice {
                            agent: fresh_worker_agent,
                            model: brigade.worker_model_for(fresh_worker_agent).unwrap_or(""),
                            effort: brigade.worker_effort_for(fresh_worker_agent).unwrap_or(""),
                        },
                        RoleLaunch::of(BrigadeRole::Worker, fresh_worker_agent, brigade),
                    ));
                }
            }
            // The stranded case: a Goinkyo whose row has a `session_id` but
            // no resolvable row — unlike an undiscovered Worker (whose
            // `session_id` is still `None` at this point, caught above), a
            // Goinkyo's discovery already ran once and assigned it a real
            // id, but `app.row_for_id` still can't find a row for it because
            // Claude Code writes no `projects/*.jsonl` transcript until the
            // Goinkyo's first turn. That is a fact about Claude. Codex writes a
            // session's `threads` row and rollout at the first persist, which is
            // the first prompt's turn, and banto discovers the session about a second
            // after the rollout is born (1.03-1.17 s in 8 measured runs). A Codex
            // Goinkyo therefore resolves to a row from its discovery and takes
            // the resume arm above, which carries no first prompt; it never
            // reaches this arm. What is left is a window of up to ~40 ms: in 3 of
            // the 8 runs discovery came 25-39 ms before Codex had written the
            // briefing and first-prompt records of that same turn. A restart or a
            // pane death inside it ends the turn before the first-prompt record
            // exists, and the re-stage resumes the thread without one. Nothing
            // handles that, and
            // `a_codex_goinkyo_restaged_before_its_first_turn_is_recorded_is_resumed_without_a_first_prompt`
            // pins it. Left as a plain `missing`, this member
            // is permanently stuck: `session_id` never gets a chance to
            // clear on its own, so `gather_goinkyo_observations`'s
            // `AwaitingSpawn` check (which only fires on `session_id: None`)
            // never sees this row as spawnable again — a member the
            // operator can't restart short of dismissing it outright.
            None if matches!(*role, BrigadeRole::Goinkyo | BrigadeRole::Planner)
                && session_id.is_some() =>
            {
                let key = SessionKey::from_id(session_id.as_deref().unwrap());
                state.member_tokens.insert(key.clone(), token.clone());
                state.member_brigades.insert(key.clone(), brigade_id);
                if state.screens.contains_key(&key) {
                    // The discovery window: `Cmd::RekeyPty` already renamed
                    // this pane's key to the real id (`update_discovery_
                    // result`), so it's alive right now — `resolved_row`
                    // above came back `None` only because `app`'s own row
                    // list hasn't caught up with the not-yet-written
                    // transcript, not because the pane is gone; this Goinkyo
                    // isn't stranded at all, just momentarily unresolved.
                    // Reusing it here, the same way the `Some(row)` arm's
                    // own `screens` check does just above, is what keeps
                    // this from being treated as the true stranded case
                    // below: clearing `session_id` on a live pane would
                    // sever it from the row identifying it mid-consultation
                    // — its own `_mcp` connection resolves who's calling
                    // through `Store::brigade_of_session`, keyed on this
                    // same id, so `send_to_peer`/`check_messages` would stop
                    // working for it the moment the id went missing.
                    //
                    // Also seeded here for the same reason the `Some(row)`
                    // arm's own resume seeds it: after a banto restart,
                    // `goinkyo_pane` starts empty, so reusing an
                    // already-live pane through *this* arm needs to record
                    // it too — not just a resume through the other one — or
                    // the guard stays unset for a Goinkyo this build never
                    // saw spawn.
                    seed_role_guard(state, *role, brigade_id, &key);
                    panes.push(key);
                } else {
                    // Truly stranded, not a timing window: no live pane is
                    // claiming this id, and none ever will — a Claude Goinkyo
                    // that never ran a turn writes no transcript, ever, not just
                    // on this tick. Reset `session_id` so the next tick's
                    // `AwaitingSpawn` restarts the very same consultation
                    // (its request file outlives this — kept until
                    // dismissal, see `StoreIntent::ClearMemberSession`'s own
                    // doc) — the Goinkyo analog of a Worker's disposable,
                    // respawnable design, through this same spawn path
                    // rather than a parallel one.
                    cmds.push(Cmd::Store(StoreIntent::ClearMemberSession {
                        brigade_id,
                        token: token.clone(),
                    }));
                }
            }
            // A Planner with no session id and no pane is the tick's to create
            // (`update_planner_observed`), not this staging's: what staging adds is
            // the way back. A launch that failed or died before it was ever
            // identified left its placeholder key in the guard, which the tick reads
            // as "do not retry". Staging the brigade again is the one thing that
            // lifts that, so a Planner that could not start is tried again exactly
            // when the operator opens the brigade, never in a loop of its own.
            None if *role == BrigadeRole::Planner => {
                let key = SessionKey::new_worker(brigade_id, token);
                if state.planner_pane.get(&brigade_id) == Some(&key)
                    && !state.screens.contains_key(&key)
                    && !state.pending_opens.contains_key(&key)
                {
                    forget_unopened_worker(state, brigade_id, token);
                }
            }
            None => missing += 1,
        }
    }
    if panes.is_empty() && cmds.is_empty() && opening == 0 {
        state.status = Some("no brigade members could be opened".to_string());
        return Vec::new();
    }
    state.stage = Stage::Brigade {
        id: brigade_id,
        director,
        panes,
        focused: 0,
    };
    state.focus = Focus::Pane;
    if missing > 0 {
        state.status = Some(format!("brigade staged ({missing} member(s) not found)"));
    }
    if duplicates > 0 {
        let said = format!(
            "closed {duplicates} duplicate pane{} of one member",
            if duplicates == 1 { "" } else { "s" }
        );
        state.status = Some(match state.status.take() {
            Some(earlier) => format!("{earlier}; {said}"),
            None => said,
        });
    }
    // Known resumes precede fresh creations in one staging batch, so the
    // shell's unresolved-creation guard sees only children that already
    // existed when the batch was decided.
    cmds.sort_by_key(|cmd| !matches!(cmd, Cmd::OpenEmbedded { target, .. } if target.agent == AgentKind::Codex && !target.id.is_empty()));
    cmds
}

fn toggle_pin(app: &mut App) -> Vec<Cmd> {
    let Some((id, pinned)) = app.toggle_pin() else {
        return Vec::new();
    };
    vec![Cmd::Store(StoreIntent::SetPin { id, pinned })]
}

/// `b`: spawn one more fresh Worker into the staged brigade. `cwd` is the
/// Director's own row cwd, resolved from `app` via `Stage::Brigade::director`
/// — no extra round trip needed as long as that's `Some` and the row is
/// already known; `None` (either one) falls back to `"."`, same as an
/// unresolved Director always has.
fn add_worker(state: &mut EmporiumState, app: &mut App, brigade: &BrigadeConfig) -> Vec<Cmd> {
    let Stage::Brigade { id, director, .. } = &state.stage else {
        state.status = Some("no brigade staged — press B to start one".to_string());
        return Vec::new();
    };
    let brigade_id = *id;
    let director_row = director
        .as_ref()
        .and_then(|key| app.row_for_id(key.as_str()));
    let cwd = director_row
        .and_then(|row| row.cwd.clone())
        .unwrap_or_else(|| PathBuf::from("."));
    // A Director not yet resolved to a row can't say what product it is
    // either — the safe default rather than blocking on it, same fallback
    // `stage_brigade`/`update_brigade_formed` use.
    let director_agent = director_row.map_or(AgentKind::ClaudeCode, |row| row.agent);

    // Same interruption `begin_brigade_formation` does for `Select` — see
    // `PendingWorkerAddition`'s own doc for what Esc means here
    // specifically (lighter than formation's: this only cancels adding one
    // more Worker, not an already-running brigade).
    if brigade.worker_agent == WorkerAgentSetting::Select {
        state.pending_worker_addition = Some(PendingWorkerAddition { brigade_id, cwd });
        app.open_worker_agent_modal(
            WorkerPickerFor::AddWorker,
            state.last_worker_agent.unwrap_or(director_agent),
            WorkerDefaults::of(brigade),
        );
        return Vec::new();
    }

    let worker_agent = resolve_worker_agent(brigade.worker_agent, director_agent);
    let worker_model = brigade
        .worker_model_for(worker_agent)
        .unwrap_or("")
        .to_string();
    let worker_effort = brigade
        .worker_effort_for(worker_agent)
        .unwrap_or("")
        .to_string();
    vec![Cmd::Store(StoreIntent::AddWorker {
        brigade_id,
        cwd,
        worker_agent,
        worker_model,
        worker_effort,
    })]
}

/// Lines [`update_mouse`] scrolls a pane's own scrollback per wheel notch —
/// tmux's own long-standing convention, chosen so a habit already
/// muscle-memorized elsewhere carries over here.
const SCROLL_NOTCH_LINES: isize = 3;

/// Dispatch one mouse event: sidebar click/scroll, or — over a pane — focus
/// it (`Down(Left)` always moves focus, regardless of whether it wants
/// mouse), then either forward the event as an SGR report or, for the
/// wheel specifically, consume it into that pane's own scrollback — the
/// choice in both cases keyed on whether the focused pane's child asked
/// for mouse reporting in the one encoding banto speaks (see
/// [`crate::screen::Screen::wants_sgr_mouse`]): a child that never enabled
/// mouse reporting has no idea what to do with an SGR sequence arriving on
/// its stdin, so forwarding unconditionally would just leak noise into
/// whatever it's actually reading — and it has no scrollback of its own to
/// receive the wheel as input either. A child that *does* want mouse gets
/// every event forwarded exactly as before, wheel included: it can already
/// implement its own scrollback (Claude Code does), and forwarding both
/// keeps that working and never fights it over whose scroll position is
/// authoritative.
///
/// The host terminal's own mouse capture used to track this same
/// wants-mouse check, releasing itself over a pane that didn't want
/// reports so the terminal's native text selection could take over. That
/// mechanism is gone: capture is unconditional now (`setup_terminal`)
/// because releasing it had a worse cost than the native selection it
/// bought — a `BANTO_INPUT_LOG` capture showed that once the host terminal
/// itself stops delivering mouse events, banto cannot get them back short
/// of the operator manually re-enabling capture out-of-band, which trapped
/// focus on any pane whose child didn't request mouse reporting (Codex,
/// measured; any other non-mouse child equally). This function's own
/// SGR-forwarding gate above is unaffected by that removal — it was always
/// about what bytes a child understands, never about whether banto's
/// terminal receives the event in the first place.
fn update_mouse(
    state: &mut EmporiumState,
    app: &mut App,
    brigade: &BrigadeConfig,
    mouse: MouseEvent,
    now: Instant,
) -> Vec<Cmd> {
    if matches!(mouse.kind, MouseEventKind::Down(_)) {
        state.pending_quit = None;
    }
    if app.modal().is_some() {
        return Vec::new();
    }
    let _ = brigade;
    // A drag in progress owns every mouse event until it ends: nothing is
    // forwarded to a child, focused or scrolled, however many panes the
    // pointer crosses.
    if state.drag.is_some() {
        return update_drag_mouse(state, mouse);
    }
    if state.move_drag.is_some() {
        return update_move_mouse(state, mouse);
    }
    let pos = Position::new(mouse.column, mouse.row);
    let geometry = state.geometry(Rect::new(0, 0, state.size.0, state.size.1));
    let areas = geometry.areas;

    // A left press on a title-row button does what the button says at once:
    // nothing is forwarded, nothing scrolls, no gesture starts.
    if let MouseEventKind::Down(MouseButton::Left) = mouse.kind
        && let Some(button) = geometry.button_at(mouse.column, mouse.row)
    {
        let (key, kind) = (button.key.clone(), button.kind);
        match kind {
            ButtonKind::Solo => toggle_solo(state, &key),
            ButtonKind::Minimize => toggle_minimize(state, &key),
        }
        refocus_expanded(state, Some(&key));
        return Vec::new();
    }

    // A left press on a boundary picks it up — and does nothing else: no
    // focus change, no report to a child, no scrolling.
    if let MouseEventKind::Down(MouseButton::Left) = mouse.kind
        && let Some(handle) = geometry.handle_at(mouse.column, mouse.row)
    {
        let along = match handle.axis {
            Axis::Vertical => mouse.column,
            Axis::Horizontal => mouse.row,
        };
        state.drag = Some(Drag {
            boundary: handle.boundary.clone(),
            grab_offset: i32::from(handle.position) - i32::from(along),
            preview: handle.position,
            all_collapsed: geometry.all_collapsed,
        });
        return Vec::new();
    }

    if areas.pane.contains(pos) {
        let tiles = &geometry.tiles;
        let hit = tiles.iter().find(|(_, rect)| rect.contains(pos)).cloned();
        // The space under a column of strips holds nothing: a press, a wheel
        // turn or a drag there does nothing at all.
        if hit.is_none() && !tiles.is_empty() {
            return Vec::new();
        }
        // A collapsed tile is not a place to click: its body and border do
        // nothing (no focus, no report to the child, no scrolling). Its label
        // still takes hold of it to move it, without focusing it; its buttons
        // were handled above.
        if let Some((key, _)) = &hit
            && geometry.is_collapsed(key)
        {
            if let MouseEventKind::Down(MouseButton::Left) = mouse.kind
                && geometry.label_at(mouse.column, mouse.row) == Some(key)
                && state.member_tokens.contains_key(key)
            {
                state.move_drag = Some(MoveDrag {
                    key: key.clone(),
                    column: mouse.column,
                    row: mouse.row,
                    dragged: false,
                });
            }
            return Vec::new();
        }
        if let MouseEventKind::Down(MouseButton::Left) = mouse.kind {
            state.focus = Focus::Pane;
            if let Stage::Brigade { panes, focused, .. } = &mut state.stage
                && let Some((key, _)) = &hit
                && let Some(p) = panes.iter().position(|k| k == key)
            {
                *focused = p;
            }
            // The press also takes hold of a stack tile by its title label.
            // The focus it just gave is the same as ever; a tile with no
            // member token has no place in an order preference, so it is not
            // picked up.
            if let Some(key) = geometry.label_at(mouse.column, mouse.row)
                && state.member_tokens.contains_key(key)
            {
                state.move_drag = Some(MoveDrag {
                    key: key.clone(),
                    column: mouse.column,
                    row: mouse.row,
                    dragged: false,
                });
                return Vec::new();
            }
        }
        if state.focus == Focus::Pane
            && let Some((key, rect)) = hit
        {
            if state
                .screens
                .get(&key)
                .is_some_and(crate::screen::Screen::wants_sgr_mouse)
            {
                if let Some(bytes) = mouse_to_sgr(&mouse, pane_content(rect)) {
                    return vec![Cmd::WritePty { key, bytes }];
                }
            } else {
                let notch_delta = match mouse.kind {
                    MouseEventKind::ScrollUp => Some(SCROLL_NOTCH_LINES),
                    MouseEventKind::ScrollDown => Some(-SCROLL_NOTCH_LINES),
                    _ => None,
                };
                if let Some(delta) = notch_delta
                    && let Some(screen) = state.screens.get_mut(&key)
                {
                    screen.scroll(delta);
                }
            }
        }
        return Vec::new();
    }

    let sb = areas.sidebar;
    let sidebar_inner = Rect {
        x: sb.x + 1,
        y: sb.y + 1,
        width: sb.width.saturating_sub(2),
        height: sb.height.saturating_sub(2),
    };
    match mouse.kind {
        MouseEventKind::ScrollUp if sb.contains(pos) => {
            app.scroll(-1);
            Vec::new()
        }
        MouseEventKind::ScrollDown if sb.contains(pos) => {
            app.scroll(1);
            Vec::new()
        }
        MouseEventKind::Down(MouseButton::Left) if sidebar_inner.contains(pos) => {
            state.focus = Focus::Sidebar;
            let viewport_row = (pos.y - sidebar_inner.y) as usize;
            if app.click(viewport_row, now) == Some(ClickOutcome::Activated) {
                activate_selected(state, app)
            } else {
                Vec::new()
            }
        }
        _ => Vec::new(),
    }
}

/// `text` placed with its first cell at (`x`, `y`) and cut to what fits in
/// `area`, by display width; `None` when nothing of it fits.
fn clip_to_screen(text: String, x: u16, y: u16, area: Rect) -> Option<Ghost> {
    if !area.contains(Position::new(x, y)) {
        return None;
    }
    let room = usize::from(area.right() - x);
    let mut clipped = String::new();
    let mut width = 0;
    for ch in text.chars() {
        let cell = unicode_width::UnicodeWidthChar::width(ch).unwrap_or(0);
        if width + cell > room {
            break;
        }
        width += cell;
        clipped.push(ch);
    }
    (!clipped.is_empty()).then_some(Ghost {
        text: clipped,
        x,
        y,
    })
}

/// One mouse event while a tile is being moved by its title label.
///
/// Owned exactly like a boundary drag (see [`update_drag_mouse`]): nothing is
/// forwarded to a child, focused or scrolled however many panes the pointer
/// crosses, a press of any button or a `Moved` cancels, the stack changes
/// only on the release. Where the tile would land is decided by the
/// pointer's row alone — its column may wander over the master or the
/// sidebar.
fn update_move_mouse(state: &mut EmporiumState, mouse: MouseEvent) -> Vec<Cmd> {
    let Some(moving) = state.move_drag.clone() else {
        return Vec::new();
    };
    let slot = state
        .geometry(Rect::new(0, 0, state.size.0, state.size.1))
        .drop_slot(mouse.row);
    match mouse.kind {
        MouseEventKind::Down(_) | MouseEventKind::Moved => state.move_drag = None,
        MouseEventKind::Drag(MouseButton::Left) => match slot {
            Some(_) => {
                state.move_drag = Some(MoveDrag {
                    column: mouse.column,
                    row: mouse.row,
                    dragged: true,
                    ..moving
                })
            }
            None => state.move_drag = None,
        },
        MouseEventKind::Up(MouseButton::Left) => {
            state.move_drag = None;
            if let Some(target) = slot {
                move_tile(state, &moving.key, target);
            }
        }
        _ => {}
    }
    Vec::new()
}

/// Bring a brigade's stored arrangement into state before its stage is built,
/// so the very first geometry — the first PTY sizes — already uses it.
///
/// In-memory wins: a brigade this run already holds a layout for keeps it. Every
/// change is written as it happens, so what memory holds is never older than
/// the store, and a stale read must not undo a change made since.
fn adopt_stored_layout(
    state: &mut EmporiumState,
    brigade_id: BrigadeId,
    stored: Option<&StoredLayout>,
) {
    let Some(stored) = stored else {
        return;
    };
    if state.brigade_layouts.contains_key(&brigade_id) {
        return;
    }
    let layout = BrigadeLayout::from_stored(stored);
    state.persisted_layouts.insert(brigade_id, layout.clone());
    state.brigade_layouts.insert(brigade_id, layout);
}

/// The writes that keep the store matching what the operator has arranged:
/// one `SaveBrigadeLayout` for each brigade whose layout differs from what the
/// store last held, one `SaveSidebarWidth` if the width does, one
/// `SaveBellWhenFocused` if the bell switch does, one `SaveLastWorkerAgent` if
/// the agent last chosen in the Worker picker does. Run at the end
/// of every `update`; since it only compares, a draw-only or tick-only event
/// writes nothing, and neither does a gesture that committed nothing, a
/// refused key, or a "restore all" with nothing to restore.
fn persist_preferences(state: &mut EmporiumState) -> Vec<Cmd> {
    let mut cmds = Vec::new();
    if state.sidebar_width != state.persisted_sidebar_width {
        state.persisted_sidebar_width = state.sidebar_width;
        cmds.push(Cmd::Store(StoreIntent::SaveSidebarWidth {
            width: state.sidebar_width,
        }));
    }
    if state.bell_when_focused != state.persisted_bell_when_focused {
        state.persisted_bell_when_focused = state.bell_when_focused;
        cmds.push(Cmd::Store(StoreIntent::SaveBellWhenFocused {
            on: state.bell_when_focused,
        }));
    }
    if let Some(agent) = state.last_worker_agent
        && state.last_worker_agent != state.persisted_last_worker_agent
    {
        state.persisted_last_worker_agent = state.last_worker_agent;
        cmds.push(Cmd::Store(StoreIntent::SaveLastWorkerAgent { agent }));
    }
    let mut brigades: Vec<BrigadeId> = state.brigade_layouts.keys().copied().collect();
    brigades.sort_unstable();
    for brigade_id in brigades {
        let layout = &state.brigade_layouts[&brigade_id];
        let previous = state.persisted_layouts.get(&brigade_id);
        let unchanged = match previous {
            Some(previous) => previous == layout,
            None => *layout == BrigadeLayout::default(),
        };
        if unchanged {
            continue;
        }
        let snapshot = layout.to_stored(previous);
        state.persisted_layouts.insert(brigade_id, layout.clone());
        cmds.push(Cmd::Store(StoreIntent::SaveBrigadeLayout {
            brigade_id,
            layout: snapshot,
        }));
    }
    cmds
}

/// Move the stack tile `key` to slot `to` (an index into `panes`), the tiles
/// in between shifting by one, by recording the result as the brigade's
/// preferred order: the staged stack tiles in their new order, then any
/// earlier-ranked members that are not staged right now, in their old
/// relative order, so a member that is off-stage keeps its place. The panes
/// themselves are reordered by `apply_stack_order` at the end of the same
/// `update`. Row weights are keyed by token, so a tile takes its height
/// with it and nothing is rewritten here.
fn move_tile(state: &mut EmporiumState, key: &SessionKey, to: usize) {
    let Stage::Brigade { id, panes, .. } = &state.stage else {
        return;
    };
    let Some(from) = panes.iter().position(|pane| pane == key) else {
        return;
    };
    if from == 0 || to == 0 || to >= panes.len() || from == to {
        return;
    }
    let mut stack: Vec<&SessionKey> = panes[1..].iter().collect();
    let moved = stack.remove(from - 1);
    stack.insert(to - 1, moved);
    let staged: Vec<MemberToken> = stack
        .into_iter()
        .filter_map(|pane| state.member_tokens.get(pane).cloned())
        .collect();
    let layout = state.brigade_layouts.entry(*id).or_default();
    let off_stage: Vec<MemberToken> = layout
        .stack_order
        .iter()
        .filter(|token| !staged.contains(token))
        .cloned()
        .collect();
    layout.stack_order = staged.into_iter().chain(off_stage).collect();
}

/// The staged brigade's id and the member token of the stack tile `key`, when
/// `key` is a stack tile that has a token to keep preferences under.
fn stack_tile_member(state: &EmporiumState, key: &SessionKey) -> Option<(BrigadeId, MemberToken)> {
    let Stage::Brigade { id, panes, .. } = &state.stage else {
        return None;
    };
    if !panes.get(1..).unwrap_or_default().contains(key) {
        return None;
    }
    Some((*id, state.member_tokens.get(key)?.clone()))
}

/// Collapse the stack tile `key` to a strip, or open it again.
///
/// While a solo is active this ends it first, and the tile ends up as the
/// click asked: a tile shown collapsed is opened (taken out of `minimized`),
/// the soloed tile itself is collapsed (put into it); the other tiles fall
/// back to their own flags. Without a solo it flips the tile's membership.
fn toggle_minimize(state: &mut EmporiumState, key: &SessionKey) {
    let Some((brigade_id, token)) = stack_tile_member(state, key) else {
        return;
    };
    // A gesture held across a change of what is collapsed was measured
    // against a layout that no longer exists.
    state.cancel_gestures();
    let solo_active = state.soloed_key().is_some();
    let shown_collapsed = match &state.stage {
        Stage::Brigade { panes, .. } => panes
            .get(1..)
            .unwrap_or_default()
            .iter()
            .position(|pane| pane == key)
            .and_then(|at| state.stack_collapsed().get(at).copied())
            .unwrap_or(false),
        _ => false,
    };
    let layout = state.brigade_layouts.entry(brigade_id).or_default();
    if solo_active {
        layout.solo_member = None;
        if shown_collapsed {
            layout.minimized.remove(&token);
        } else {
            layout.minimized.insert(token);
        }
    } else if !layout.minimized.remove(&token) {
        layout.minimized.insert(token);
    }
}

/// The staged brigade's id and the member token of the tile `key`, master or
/// stack, when the brigade has a stack at all (a lone pane has nothing to
/// solo against) and `key` has a token to keep the preference under.
fn soloable_member(state: &EmporiumState, key: &SessionKey) -> Option<(BrigadeId, MemberToken)> {
    let Stage::Brigade { id, panes, .. } = &state.stage else {
        return None;
    };
    if panes.len() < 2 || !panes.contains(key) {
        return None;
    }
    Some((*id, state.member_tokens.get(key)?.clone()))
}

/// Solo the tile `key` (the master or a stack tile), or turn its solo off when
/// it already is the one. Moving the solo from another tile just names the
/// new one. Never touches `minimized`.
fn toggle_solo(state: &mut EmporiumState, key: &SessionKey) {
    let Some((brigade_id, token)) = soloable_member(state, key) else {
        return;
    };
    state.cancel_gestures();
    let layout = state.brigade_layouts.entry(brigade_id).or_default();
    layout.solo_member = if layout.solo_member.as_ref() == Some(&token) {
        None
    } else {
        Some(token)
    };
}

/// Open every collapsed tile and turn the solo off.
fn restore_all(state: &mut EmporiumState) {
    let Stage::Brigade { id, .. } = &state.stage else {
        return;
    };
    let id = *id;
    state.cancel_gestures();
    let layout = state.brigade_layouts.entry(id).or_default();
    layout.solo_member = None;
    layout.minimized.clear();
    refocus_expanded(state, None);
}

/// Prefix + `=`: forget the sizes the operator dragged the staged brigade to —
/// every member's row weight (staged or not, so a member reopened later does not
/// bring an old height back), the master share, and the collapsed stack's width.
///
/// Sizes only: the stack order, what is collapsed or soloed, the names and the
/// join order are arrangement, not size, and stay; so does the sidebar's width,
/// a window-level preference of a different layer. Works from any focus, as
/// `M` does, because it acts on the brigade, not on a tile. The tiles' PTYs are
/// resized, and the one layout save emitted, by the passes at the end of the
/// `update` this runs in — a brigade already at its defaults changes nothing
/// there, and says so here.
fn reset_sizes(state: &mut EmporiumState, now: Instant) {
    let Stage::Brigade { id, .. } = &state.stage else {
        state.set_status("prefix: no brigade layout to reset", now);
        return;
    };
    let id = *id;
    // A drag was measured against sizes that are about to change.
    state.cancel_gestures();
    let layout = state.brigade_layouts.entry(id).or_default();
    let already_default = layout.master_permille == DEFAULT_MASTER_PERMILLE
        && layout.collapsed_stack_width == DEFAULT_COLLAPSED_STACK_WIDTH
        && layout.row_weights.is_empty();
    layout.master_permille = DEFAULT_MASTER_PERMILLE;
    layout.collapsed_stack_width = DEFAULT_COLLAPSED_STACK_WIDTH;
    layout.row_weights.clear();
    state.set_status(
        if already_default {
            "sizes already at their defaults"
        } else {
            "sizes reset"
        },
        now,
    );
}

/// A collapsed tile is not focusable. If the focused pane is collapsed, move
/// the focus to the tile just acted on if that is expanded, else to the
/// nearest expanded stack tile (below first, then above), else to the master.
/// Run after every operation and at the end of every `update`, so nothing
/// that collapses a tile — a solo returning with its pane — has to remember.
fn refocus_expanded(state: &mut EmporiumState, acted: Option<&SessionKey>) {
    let collapsed = state.pane_collapsed();
    let Stage::Brigade { panes, focused, .. } = &mut state.stage else {
        return;
    };
    if !collapsed.get(*focused).copied().unwrap_or(false) {
        return;
    }
    let expanded = |index: &usize| !collapsed.get(*index).copied().unwrap_or(false);
    let acted = acted
        .and_then(|key| panes.iter().position(|pane| pane == key))
        .filter(expanded);
    *focused = acted
        .or_else(|| (*focused + 1..panes.len()).find(expanded))
        .or_else(|| (1..*focused).rev().find(expanded))
        .unwrap_or(0);
}

/// Prefix + `m`: collapse the focused tile, or open it again.
fn collapse_focused_tile(state: &mut EmporiumState) -> Vec<Cmd> {
    let refusal = match (&state.stage, state.focus) {
        (_, Focus::Sidebar) => Some("prefix: focus a tile to collapse it"),
        (Stage::Brigade { focused: 0, .. } | Stage::Solo(_) | Stage::Empty, _) => {
            Some("prefix: the master tile can't be collapsed")
        }
        _ => None,
    };
    let key = state.stage.focused_key().cloned();
    let refusal = refusal.or_else(|| {
        key.as_ref()
            .is_none_or(|key| stack_tile_member(state, key).is_none())
            .then_some("prefix: this tile has no member to collapse")
    });
    if let Some(reason) = refusal {
        state.status = Some(reason.to_string());
        return Vec::new();
    }
    if let Some(key) = key {
        toggle_minimize(state, &key);
        refocus_expanded(state, Some(&key));
    }
    Vec::new()
}

/// Prefix + `z`: solo the focused tile — the master included — or turn its
/// solo off.
fn solo_focused_tile(state: &mut EmporiumState) -> Vec<Cmd> {
    if state.focus == Focus::Sidebar {
        state.status = Some("prefix: focus a tile to solo it".to_string());
        return Vec::new();
    }
    let Some(key) = state.stage.focused_key().cloned() else {
        return Vec::new();
    };
    if soloable_member(state, &key).is_none() {
        let alone = !matches!(&state.stage, Stage::Brigade { panes, .. } if panes.len() >= 2);
        state.status = Some(
            if alone {
                "prefix: no stack to solo"
            } else {
                "prefix: this tile has no member to solo"
            }
            .to_string(),
        );
        return Vec::new();
    }
    toggle_solo(state, &key);
    refocus_expanded(state, Some(&key));
    Vec::new()
}

/// Prefix + Shift+Up / Shift+Down: move the focused stack tile one slot, the
/// focus staying on it. Every refusal says why, the way an out-of-range
/// pane number does.
fn move_focused_tile(state: &mut EmporiumState, direction: Direction) -> Vec<Cmd> {
    let refusal = match (&state.stage, state.focus) {
        (_, Focus::Sidebar) => Some("prefix: focus a tile to move it"),
        (Stage::Brigade { focused: 0, .. } | Stage::Solo(_) | Stage::Empty, _) => {
            Some("prefix: the master tile stays put")
        }
        (Stage::Brigade { focused, .. }, _) if direction == Direction::Up && *focused <= 1 => {
            Some("prefix: already at the top of the stack")
        }
        (Stage::Brigade { focused, panes, .. }, _)
            if direction == Direction::Down && focused + 1 >= panes.len() =>
        {
            Some("prefix: already at the bottom of the stack")
        }
        (Stage::Brigade { focused, panes, .. }, _)
            if panes
                .get(*focused)
                .is_none_or(|key| !state.member_tokens.contains_key(key)) =>
        {
            Some("prefix: this tile has no member to keep an order for")
        }
        _ => None,
    };
    if let Some(reason) = refusal {
        state.status = Some(reason.to_string());
        return Vec::new();
    }
    if let Stage::Brigade { focused, panes, .. } = &state.stage {
        let to = if direction == Direction::Up {
            *focused - 1
        } else {
            *focused + 1
        };
        let key = panes[*focused].clone();
        move_tile(state, &key, to);
    }
    Vec::new()
}

/// The boundary position a pointer at `mouse` previews, clamped to what that
/// boundary may take. `None` when the boundary no longer exists.
fn dragged_position(state: &EmporiumState, drag: &Drag, mouse: &MouseEvent) -> Option<u16> {
    let geometry = state.geometry(Rect::new(0, 0, state.size.0, state.size.1));
    let handle = geometry.handle_for(&drag.boundary)?;
    let along = match handle.axis {
        Axis::Vertical => mouse.column,
        Axis::Horizontal => mouse.row,
    };
    Some(handle.clamp(i32::from(along) + drag.grab_offset))
}

/// One mouse event while a boundary drag is in progress.
///
/// The real geometry does not move during the drag — only `Drag::preview`
/// does — and the layout changes once, on release. Every layout change is a
/// `Cmd::ResizePty` per tile whose size changed, executed immediately and
/// without debounce by the shell, and each makes the child repaint its whole
/// screen; resize under stress is on the embedded-pty spike's own
/// not-yet-verified list (`docs/notes/embedded-pty-spike.md`). One resize
/// per gesture is the path a window resize already exercises; one per
/// dragged cell is the untested one.
///
/// A press of any button, or a `Moved` (which can only mean no button is held
/// any more: the release happened outside the window), ends the gesture
/// without applying it. Everything else that is not the left button's drag or
/// release — the wheel, the other buttons — is swallowed.
fn update_drag_mouse(state: &mut EmporiumState, mouse: MouseEvent) -> Vec<Cmd> {
    let Some(drag) = state.drag.clone() else {
        return Vec::new();
    };
    match mouse.kind {
        MouseEventKind::Down(_) | MouseEventKind::Moved => state.drag = None,
        MouseEventKind::Drag(MouseButton::Left) => match dragged_position(state, &drag, &mouse) {
            Some(preview) => state.drag = Some(Drag { preview, ..drag }),
            None => state.drag = None,
        },
        MouseEventKind::Up(MouseButton::Left) => {
            state.drag = None;
            if let Some(position) = dragged_position(state, &drag, &mouse) {
                commit_drag(state, &drag.boundary, position);
            }
        }
        _ => {}
    }
    Vec::new()
}

/// Apply a finished drag: store the new preference for `boundary`. The tiles
/// whose content size changed are resized by the `resize_staged_tiles` at the
/// end of this same `update`.
///
/// A release where the boundary already was stores nothing: a click on a
/// handle must not turn a proportional layout into frozen row counts.
fn commit_drag(state: &mut EmporiumState, boundary: &Boundary, position: u16) {
    let geometry = state.geometry(Rect::new(0, 0, state.size.0, state.size.1));
    let Some(handle) = geometry.handle_for(boundary) else {
        return;
    };
    if position == handle.position {
        return;
    }
    match boundary {
        // The sidebar starts at column 0, so its width is where the pane
        // area now begins.
        Boundary::Sidebar => state.sidebar_width = position,
        Boundary::Master { brigade } => {
            let pane = geometry.areas.pane;
            let layout = state.brigade_layouts.entry(*brigade).or_default();
            if geometry.all_collapsed {
                // The column of strips has a width of its own: where the
                // boundary sits is how much room the stack gets.
                layout.collapsed_stack_width = pane.x + pane.width - position;
            } else {
                layout.master_permille = master_permille_for(position - pane.x, pane.width);
            }
        }
        Boundary::Stack {
            brigade,
            above,
            below,
        } => {
            // Every *expanded* stack member's weight becomes the height it ends
            // up with, so a later window resize scales the whole expanded
            // stack as dragged rather than only the two tiles that moved.
            // A collapsed member keeps the weight it has: its strip height is
            // not a height it chose.
            let mut heights: Vec<(SessionKey, u16)> = geometry
                .tiles
                .iter()
                .zip(&geometry.collapsed)
                .skip(1)
                .filter(|(_, collapsed)| !**collapsed)
                .map(|((key, rect), _)| (key.clone(), rect.height))
                .collect();
            let moved = heights.iter().position(|(key, _)| key == above);
            if let Some(i) = moved
                && heights.get(i + 1).is_some_and(|(key, _)| key == below)
                && let Some(above_tile) = geometry.tiles.iter().find(|(key, _)| key == above)
            {
                let together = heights[i].1 + heights[i + 1].1;
                let upper = position.saturating_sub(above_tile.1.y);
                heights[i].1 = upper;
                heights[i + 1].1 = together.saturating_sub(upper);
            }
            let layout = state.brigade_layouts.entry(*brigade).or_default();
            for (key, height) in heights {
                if let Some(token) = state.member_tokens.get(&key) {
                    layout.row_weights.insert(token.clone(), height.max(1));
                }
            }
        }
    }
}

/// Drop a drag whose gesture can no longer be completed: a modal opened over
/// it, the boundary it holds is not in the current geometry (the stage
/// changed — a pane closed, another brigade staged), or the tile being moved has
/// no rows left. Run at the end of every `update`, so no event handler has to
/// remember to cancel it.
///
/// Every operation that resizes tiles on purpose (a resize, collapse, solo,
/// reset) ends the gesture itself. What reaches here is a pane ARRIVING while the
/// button is held (a relaunch, an added Worker): each takes at most a row from a
/// tile, so a stack with more tiles than rows can leave the tile in the operator's
/// hand with none after a few of them. A tile with no rows draws nothing, so its
/// ghost and the drop line would point at nothing and the release would still
/// move it. (A resize drag needs no such check: a boundary beside an empty tile is
/// not in the geometry, which cancels it below.)
fn validate_drag(state: &mut EmporiumState, app: &App) {
    if let Some(moving) = &state.move_drag {
        // A tile being moved must still be a stack tile, in a stack that has
        // somewhere to put it, and be on screen.
        let still_movable = matches!(
            &state.stage,
            Stage::Brigade { panes, .. }
                if panes.len() >= 3 && panes[1..].contains(&moving.key)
        );
        let on_screen = still_movable
            && state
                .geometry(Rect::new(0, 0, state.size.0, state.size.1))
                .tiles
                .iter()
                .any(|(key, rect)| *key == moving.key && !crate::layout::is_empty(*rect));
        if app.modal().is_some() || !on_screen {
            state.move_drag = None;
        }
    }
    let Some(drag) = &state.drag else {
        return;
    };
    let geometry = state.geometry(Rect::new(0, 0, state.size.0, state.size.1));
    // The master/stack boundary is the same boundary whether or not the stack
    // is all strips, but it means a different preference in each; a pane
    // arriving or leaving can flip that under a held button.
    let meaning_changed = matches!(drag.boundary, Boundary::Master { .. })
        && drag.all_collapsed != geometry.all_collapsed;
    if app.modal().is_some() || geometry.handle_for(&drag.boundary).is_none() || meaning_changed {
        state.drag = None;
    }
}

/// Encode a mouse event as an SGR mouse report for a child whose grid starts
/// at `content` (screen coords mapped into the grid, 1-based).
fn mouse_to_sgr(mouse: &MouseEvent, content: Rect) -> Option<Vec<u8>> {
    if mouse.column < content.x || mouse.row < content.y {
        return None;
    }
    let cx = mouse.column - content.x;
    let cy = mouse.row - content.y;
    if cx >= content.width || cy >= content.height {
        return None;
    }
    let (cb, release) = match mouse.kind {
        MouseEventKind::Down(b) => (mouse_btn(b), false),
        MouseEventKind::Up(b) => (mouse_btn(b), true),
        MouseEventKind::Drag(b) => (mouse_btn(b) + 32, false),
        MouseEventKind::ScrollUp => (64, false),
        MouseEventKind::ScrollDown => (65, false),
        _ => return None,
    };
    let final_char = if release { 'm' } else { 'M' };
    Some(format!("\x1b[<{};{};{}{}", cb, cx + 1, cy + 1, final_char).into_bytes())
}

fn mouse_btn(button: MouseButton) -> u16 {
    match button {
        MouseButton::Left => 0,
        MouseButton::Middle => 1,
        MouseButton::Right => 2,
    }
}

/// The text up to (not including) the first CR or LF — conventional
/// single-line-field paste behavior. Used by [`update_paste`]'s modal and
/// search branches only: a trailing newline (the usual result of copying
/// one line) becomes a no-op instead of dumping whatever followed it into
/// the query or a stray character into a path. Deliberately changes Unix
/// behavior too (a real `Event::Paste` there previously pushed the
/// remainder straight through, since `push_char`/`modal_push_char` merely
/// skip a control character rather than stopping at it) — so both
/// platforms agree instead of diverging on which one happens to have a
/// working paste-burst source.
fn first_line(text: &str) -> &str {
    let end = text.find(['\r', '\n']).unwrap_or(text.len());
    &text[..end]
}

fn update_paste(state: &mut EmporiumState, app: &mut App, text: String, now: Instant) -> Vec<Cmd> {
    if app.modal().is_some() {
        for c in first_line(&text).chars() {
            app.modal_push_char(c);
        }
        return Vec::new();
    }
    if app.mode() == Mode::Search {
        for c in first_line(&text).chars() {
            app.push_char(c);
        }
        return Vec::new();
    }
    if state.focus == Focus::Pane
        && let Some(key) = state.stage.focused_key().cloned()
        && !state.is_held(&key)
    {
        let normalized = normalize_paste_line_endings(&text);
        let bracketed = state
            .screens
            .get(&key)
            .is_some_and(|screen| screen.screen().bracketed_paste());
        let bytes = if bracketed {
            wrap_bracketed_paste(&normalized)
        } else {
            normalized.into_bytes()
        };
        state.last_given_input.insert(key.clone(), now);
        operator_gave_work(state, &key);
        return vec![Cmd::WritePty { key, bytes }];
    }
    Vec::new()
}

fn update_spawned(
    state: &mut EmporiumState,
    brigade: &BrigadeConfig,
    key: SessionKey,
    agent: Option<AgentKind>,
    now: Instant,
) -> Vec<Cmd> {
    state.relaunching.remove(&key);
    state.launch_agents.remove(&key);
    if let Some(agent) = agent {
        state.launch_agents.insert(key.clone(), agent);
    }
    // A kill that never produced an exit — the child was already gone — would
    // otherwise leave its record behind to suppress the first genuine crash
    // of whatever opens under this key next.
    state.expected_exits.remove(&key);
    // And its hang-up's deadline, which must not end the process that replaces it.
    state.hangups.remove(&key);
    // A new process starts with nothing known about it, whatever the pane that
    // held this key before was last read as.
    state.quiescence.remove(&key);
    // Work given to the process that held this key before is not work given to
    // this one. `was_given_work` compares with `>=`, and one drain of the event
    // loop stamps every event with the same instant: an exit, a key typed into the
    // dying pane or a nudge written to it, and the `Spawned` that answers the
    // relaunch can all share one, in that order. Forgotten here, at the start of
    // the new process, so that only what is given after it counts. Neither reader
    // of these two can be hurt: the quit window reads a new process as unknown
    // until it is sampled, and the quiet stretch counts from the later of the
    // idle samples and the last write, and those samples come after this spawn.
    state.last_given_input.remove(&key);
    state.last_prompted.remove(&key);
    state.process_started.insert(key.clone(), now);
    // A watch from the process that held this key before is not this one's.
    state.first_turn_watch.remove(&key);
    // A turn the previous process ran is not one this process ran, and what was
    // said about that process is not said about this one.
    state.codex_turn_ran.remove(&key);
    state.unbriefed_told.remove(&key);
    state.screens.insert(
        key.clone(),
        crate::screen::Screen::new(crate::screen::SPAWN_ROWS, crate::screen::SPAWN_COLS),
    );
    state.spawn_order.insert(key.clone(), state.next_spawn);
    state.next_spawn += 1;
    let Some(pending) = state.pending_opens.remove(&key) else {
        return Vec::new();
    };
    // Asked for before a close or a disband, reported after it: the brigade has
    // no pane to gain, so this one is ended at once instead of being staged. It
    // was not hosted when the kills were chosen, and landing would make it a pane
    // of a brigade that is closed or gone. A closing brigade ends everything it
    // opens, a Director included. A disbanded one ends only what its token names a
    // Worker or the Goinkyo: a resumed Director opened by `stage_brigade` is the
    // pane that stays, as it does when it was already hosted. A Worker's maps were
    // written when it was asked for (`open_worker`); a closing brigade's Director
    // gets them here, which is what makes its pane count as the brigade's until
    // its exit arrives, so that exit folds into the close like the others.
    if let PendingOpen::BrigadeDirector { brigade_id, .. }
    | PendingOpen::BrigadeMember { brigade_id, .. } = &pending
    {
        let closing = state.closing.contains_key(brigade_id);
        let disbanded_worker = state.disbanding.contains(brigade_id)
            && state
                .member_tokens
                .get(&key)
                .is_some_and(|token| token != DIRECTOR_TOKEN);
        if closing || disbanded_worker {
            if closing && matches!(pending, PendingOpen::BrigadeDirector { .. }) {
                state
                    .member_tokens
                    .insert(key.clone(), DIRECTOR_TOKEN.to_string());
                state.member_brigades.insert(key.clone(), *brigade_id);
            }
            return kill_pane(state, key).into_iter().collect();
        }
    }
    match pending {
        PendingOpen::Solo => {
            state.stage = Stage::Solo(key);
            state.focus = Focus::Pane;
            Vec::new()
        }
        PendingOpen::BrigadeDirector {
            brigade_id,
            worker_tokens,
            cwd,
            worker_agent,
            worker_model,
            worker_effort,
        } => {
            state
                .member_tokens
                .insert(key.clone(), DIRECTOR_TOKEN.to_string());
            state.member_brigades.insert(key.clone(), brigade_id);
            state.stage = Stage::Brigade {
                id: brigade_id,
                director: Some(key.clone()),
                panes: vec![key],
                focused: 0,
            };
            state.focus = Focus::Pane;
            // The brigade can have been disbanded between asking for this
            // Director and its spawn being reported.
            let worker_tokens: Vec<MemberToken> = worker_tokens
                .into_iter()
                .filter(|token| creation_still_wanted(state, brigade_id, token))
                .collect();
            worker_tokens
                .into_iter()
                .flat_map(|token| {
                    open_worker(
                        state,
                        brigade_id,
                        &token,
                        &cwd,
                        WorkerChoice {
                            agent: worker_agent,
                            model: &worker_model,
                            effort: &worker_effort,
                        },
                        RoleLaunch::of(BrigadeRole::Worker, worker_agent, brigade),
                    )
                })
                .collect()
        }
        PendingOpen::BrigadeMember {
            brigade_id,
            first_turn,
        } => {
            if let Stage::Brigade {
                id,
                director,
                panes,
                ..
            } = &mut state.stage
                && *id == brigade_id
                && !panes.contains(&key)
            {
                // Best-effort Director-first ordering (display only — see
                // `Stage::Brigade::panes`'s own doc): if this arrival is
                // the Director's own key, put it back at the front rather
                // than wherever it landed in arrival order. Where everyone
                // else belongs is not decided here: `apply_stack_order`
                // places them at the end of this same `update`.
                if director.as_ref() == Some(&key) {
                    panes.insert(0, key.clone());
                } else {
                    panes.push(key.clone());
                }
            }
            if let Some(agent) = first_turn {
                // The first prompt is on the command line: it was given at
                // this moment, and so counts as work given to this process
                // (`was_given_work`, which compares with `>=` against the
                // `process_started` stamped above). Not stamped for a member
                // that has none, which is still waiting for someone to start it.
                state.last_prompted.insert(key.clone(), now);
                state
                    .first_turn_watch
                    .insert(key, FirstTurnWatch { agent, told: false });
            }
            Vec::new()
        }
    }
}

/// Which product a fresh Worker spawn should use, given `[brigade]
/// worker_agent` and the brigade's own Director's product.
///
/// `Select` is a stand-in for `Inherit` here, not a considered choice of its
/// own: every call site that reaches this function runs well after
/// formation already started — a re-stage, a later `b` add-worker, or the
/// moment right after the Director itself finished spawning — with no
/// synchronous UI moment left to interrupt with a picker. The formation
/// modal that actually asks the operator up front (so every one of these
/// call sites gets an already-decided `AgentKind` before this function ever
/// runs) is separate, not-yet-landed work; until it does, falling back to
/// `Inherit`'s behavior is the least-surprising default.
fn resolve_worker_agent(setting: WorkerAgentSetting, director_agent: AgentKind) -> AgentKind {
    match setting {
        WorkerAgentSetting::Inherit | WorkerAgentSetting::Select => director_agent,
        WorkerAgentSetting::Claude => AgentKind::ClaudeCode,
        WorkerAgentSetting::Codex => AgentKind::Codex,
    }
}

/// What a Worker about to be created is launched with. All three are decided by
/// the caller — from the configuration, or from what the operator confirmed in
/// the picker — and an empty string means "pass nothing".
struct WorkerChoice<'a> {
    agent: AgentKind,
    model: &'a str,
    effort: &'a str,
}

/// Emit the `Cmd::OpenEmbedded` for one auto-spawned Worker, wired to the
/// brigade's MCP channel, tracked as a `BrigadeMember` open.
///
/// This is a *creation*: the Worker has no session id, so it carries its model
/// and its effort, the only launches that do (`RoleLaunch`'s doc says why a
/// resume must not). `choice.agent` is always the caller's own,
/// already-resolved choice (see [`resolve_worker_agent`]) — this function never
/// re-derives it. A Codex Worker is created with a first prompt
/// ([`CODEX_WORKER_FIRST_PROMPT`]) and watched for its turn
/// ([`PendingOpen::BrigadeMember::first_turn`]); a Claude one is not, since its
/// operator gives it its first turn. Only a creation ever carries one: this
/// function's, and a Goinkyo's ([`update_goinkyo_awaiting_spawn`]); a resumed
/// member with a known id (`stage_brigade`'s own `Some(row)` branch) never does.
///
/// A Codex model is the word the operator wrote, which may be a family: it has
/// to meet the installed Codex's catalog before it can be passed
/// (`crate::codex_model`). The open is held back for that
/// ([`EmporiumState::codex_opens_awaiting_catalog`]) and the read is asked for
/// once, by whichever open finds the queue empty; [`update_codex_catalog_read`]
/// releases them all. With no model there is nothing to resolve and the open
/// goes out at once.
fn open_worker(
    state: &mut EmporiumState,
    brigade_id: BrigadeId,
    token: &str,
    cwd: &std::path::Path,
    choice: WorkerChoice<'_>,
    launch: RoleLaunch,
) -> Vec<Cmd> {
    let WorkerChoice {
        agent,
        model,
        effort,
    } = choice;
    let key = SessionKey::new_worker(brigade_id, token);
    // Never a second creation: a member with a pane or an open in flight, under
    // any key, has its session or is getting one.
    if member_open_or_opening(state, brigade_id, token, None) {
        return Vec::new();
    }
    // The ownership maps are written for the placeholder key before its screen
    // is looked at, which is safe because no other member's pane can sit under
    // it: the key is built from the brigade id and the token, a brigade id is
    // never reused (`brigades.id` is AUTOINCREMENT), and a Worker token is never
    // reused within a brigade (`Store::add_worker`'s counter remembers the
    // highest ever issued). The Goinkyo's token is reused by each consultation,
    // but it is the same member, and one consultation at a time
    // (`goinkyo_pane`).
    state.member_tokens.insert(key.clone(), token.to_string());
    state.member_brigades.insert(key.clone(), brigade_id);
    state.pending_opens.insert(
        key.clone(),
        PendingOpen::BrigadeMember {
            brigade_id,
            first_turn: (agent == AgentKind::Codex).then_some(agent),
        },
    );
    let (model, effort) = (
        crate::config::flag_value(model).unwrap_or(""),
        crate::config::flag_value(effort).unwrap_or(""),
    );
    let open = Cmd::OpenEmbedded {
        key,
        target: SessionToOpen {
            id: String::new(),
            agent,
            title: format!("worker {token}"),
            cwd: cwd.to_path_buf(),
        },
        brigade: Some((brigade_id, token.to_string(), BrigadeRole::Worker)),
        model: (!model.is_empty()).then(|| model.to_string()),
        effort: (!effort.is_empty()).then(|| effort.to_string()),
        permission_mode: launch.permission_mode,
        disallowed_tools: launch.disallowed_tools,
        autocompact: launch.autocompact,
        first_prompt: (agent == AgentKind::Codex).then(|| CODEX_WORKER_FIRST_PROMPT.to_string()),
    };
    if agent == AgentKind::Codex && !model.is_empty() {
        return hold_for_catalog(state, open);
    }
    vec![open]
}

/// Hold back a Codex creation whose model may be a family word until the
/// catalog read answers, and ask for that read unless one is already out. Shared
/// by every launch that creates a Codex member with a model: a Worker's
/// ([`open_worker`]) and a Goinkyo's ([`update_goinkyo_awaiting_spawn`]).
fn hold_for_catalog(state: &mut EmporiumState, open: Cmd) -> Vec<Cmd> {
    // Joins the round already waiting, if there is one: its one read serves
    // every creation requested meanwhile, and a round that has creations
    // held is one that will be answered or given up. Otherwise a new round.
    let waiting = state
        .codex_opens_awaiting_catalog
        .last()
        .map(|held| held.round);
    let round = waiting.unwrap_or(state.next_catalog_round);
    if waiting.is_none() {
        // Wraps past the end to 1, never to 0, which names no round.
        state.next_catalog_round = state.next_catalog_round.checked_add(1).unwrap_or(1);
        // The give-up clock starts at the next tick that sees it, not from
        // whatever an earlier round left.
        state.codex_catalog_waiting_since = None;
    }
    state
        .codex_opens_awaiting_catalog
        .push(HeldCreation { round, open });
    if waiting.is_none() {
        vec![Cmd::ReadCodexCatalog { round }]
    } else {
        Vec::new()
    }
}

/// Whether a creation of `token` in `brigade_id`, decided earlier and carried
/// out later, is still wanted when its turn comes: the brigade is not being
/// disbanded (and was not — a disbanded brigade forgets its join order) or
/// closed, the member is still on its roster, and it is not open or being
/// opened under any key ([`member_open_or_opening`], not counting the
/// creation's own pending entry). The roster is the core's own record
/// (`EmporiumState::member_order`): what it is told of — a formation, a join,
/// a staging from the store's roster, a dismissal, a disband — and not a
/// removal made behind its back. Asked where a launch waits on an answer: the
/// catalog read, the Director's spawn that opens the Workers, and the store's
/// answer to adding a Worker. Between the request and the answer the operator
/// can disband the brigade, and an answer that opened a Worker for a brigade
/// that is gone would start an agent nothing owns.
fn creation_still_wanted(state: &EmporiumState, brigade_id: BrigadeId, token: &str) -> bool {
    !state.disbanding.contains(&brigade_id)
        && !state.closing.contains_key(&brigade_id)
        && state
            .member_order
            .get(&brigade_id)
            .is_some_and(|joined| joined.iter().any(|listed| listed == token))
        && !member_open_or_opening(
            state,
            brigade_id,
            token,
            Some(&SessionKey::new_worker(brigade_id, token)),
        )
}

/// Records `key` as the one-shot guard of a Goinkyo's or a Planner's pane, the two
/// roles that have one. Every role is answered here and not through a catch-all:
/// a role added later has to say whether its pane needs a guard.
fn seed_role_guard(
    state: &mut EmporiumState,
    role: BrigadeRole,
    brigade_id: BrigadeId,
    key: &SessionKey,
) {
    match role {
        BrigadeRole::Goinkyo => {
            state.goinkyo_pane.insert(brigade_id, key.clone());
        }
        BrigadeRole::Planner => {
            state.planner_pane.insert(brigade_id, key.clone());
        }
        BrigadeRole::Director | BrigadeRole::Worker => {}
    }
}

/// Undo exactly what [`open_worker`] registered for a creation that will not be
/// carried out: the maps and the pending open under the placeholder key it was
/// made for. (Its first-turn watch and its discovery are only registered once
/// the pane spawns, so there is nothing of either to undo.) Only that key's: a pane of
/// the same member under any other key has maps of its own, which are not
/// touched, and one under this very key is left whole. The store's member row is
/// the store's: a disband deletes it with the brigade, a dismissal with the
/// member, and one left otherwise is a Worker with no session id and no pane,
/// which staging creates afresh.
fn forget_unopened_worker(state: &mut EmporiumState, brigade_id: BrigadeId, token: &str) {
    let key = SessionKey::new_worker(brigade_id, token);
    if state.screens.contains_key(&key) {
        return;
    }
    state.unresolved_codex.remove(&key);
    state.member_tokens.remove(&key);
    state.member_brigades.remove(&key);
    state.pending_opens.remove(&key);
    // A Goinkyo's spawn also left its one-shot guard on this very key
    // (`update_goinkyo_awaiting_spawn`). Left behind for a creation that will
    // never run, it would read as "in flight or failed: do not retry", and no
    // later consultation of the brigade could ever open a Goinkyo. A guard naming
    // a real pane is not this key and is not touched.
    if token == GOINKYO_TOKEN && state.goinkyo_pane.get(&brigade_id) == Some(&key) {
        state.goinkyo_pane.remove(&brigade_id);
    }
    // The Planner's, for the same reason, and the one `stage_brigade` lifts when it
    // is staged again.
    if token == PLANNER_TOKEN && state.planner_pane.get(&brigade_id) == Some(&key) {
        state.planner_pane.remove(&brigade_id);
    }
}

/// The role a held creation's session is opened for, which the notice about its
/// model names. A Worker's, or a Goinkyo's; an open with no brigade is read as a
/// Worker's.
fn held_creation_role(held: &HeldCreation) -> BrigadeRole {
    match &held.open {
        Cmd::OpenEmbedded {
            brigade: Some((_, _, role)),
            ..
        } => *role,
        _ => BrigadeRole::Worker,
    }
}

/// The member a held `Cmd::OpenEmbedded` creates, if it is a brigade member's.
fn held_creation_member(held: &HeldCreation) -> Option<(BrigadeId, &str)> {
    match &held.open {
        Cmd::OpenEmbedded {
            brigade: Some((brigade_id, token, _)),
            ..
        } => Some((*brigade_id, token.as_str())),
        _ => None,
    }
}

/// Drop first-turn watches and held launches for panes ended by a close or disband.
fn drop_leftovers_of_ended_panes(
    state: &mut EmporiumState,
    brigade_id: BrigadeId,
    ended: &[SessionKey],
) {
    state.first_turn_watch.retain(|key, _| !ended.contains(key));
    drop_held_creations_of(state, brigade_id);
    // A closed brigade keeps its members on the roster, so the release's check of
    // the member would still pass: a Worker's reopen held through the close would
    // start a process for a brigade that was shut.
    state
        .held_relaunches
        .retain(|held| held.brigade_id != brigade_id);
}

/// Drop the creation of one member, `token` of `brigade_id`, that is waiting
/// for the catalog, with its bookkeeping, and say whether there was one. For a
/// Goinkyo whose consultation ended while its open was held: the next
/// consultation of the brigade reuses its token and its placeholder key, and the
/// held open belongs to the consultation that is over.
fn drop_held_creation_of_member(
    state: &mut EmporiumState,
    brigade_id: BrigadeId,
    token: &str,
) -> bool {
    let held = std::mem::take(&mut state.codex_opens_awaiting_catalog);
    let mut dropped = false;
    for creation in held {
        match held_creation_member(&creation) {
            Some((id, held_token)) if id == brigade_id && held_token == token => dropped = true,
            _ => state.codex_opens_awaiting_catalog.push(creation),
        }
    }
    if dropped {
        forget_unopened_worker(state, brigade_id, token);
    }
    dropped
}

/// Drop what a disband or a close leaves held: the brigade's creations waiting
/// for the catalog, with their bookkeeping, at once rather than when the answer
/// comes.
fn drop_held_creations_of(state: &mut EmporiumState, brigade_id: BrigadeId) {
    let held = std::mem::take(&mut state.codex_opens_awaiting_catalog);
    for creation in held {
        match held_creation_member(&creation) {
            Some((id, token)) if id == brigade_id => {
                let token = token.to_string();
                forget_unopened_worker(state, brigade_id, &token);
            }
            _ => state.codex_opens_awaiting_catalog.push(creation),
        }
    }
}

/// Answers `Cmd::ReadCodexCatalog`: every Codex Worker waiting on it that is
/// still wanted ([`creation_still_wanted`]) gets its model resolved
/// (`crate::codex_model::resolve`, which has the rules and the wording) and its
/// open goes out; one that is not is dropped with its bookkeeping, silently —
/// whoever made it unwanted (a disband) said so already. A word several Workers
/// share is resolved once and said once. The read is not kept: the next creation
/// asks again. An answer releases only the creations of its own `round`; one for
/// a round with nothing waiting — a late one, after the give-up in `update_tick`
/// or after a disband emptied the round, or one for a round nobody asked for
/// (including 0, what a capture without the field loads as) — changes nothing,
/// so it can never release the creations of a round that asked after it.
fn update_codex_catalog_read(
    state: &mut EmporiumState,
    round: u64,
    result: Result<String, String>,
    now: Instant,
) -> Vec<Cmd> {
    let (waiting, kept): (Vec<HeldCreation>, Vec<HeldCreation>) =
        std::mem::take(&mut state.codex_opens_awaiting_catalog)
            .into_iter()
            .partition(|held| held.round == round);
    state.codex_opens_awaiting_catalog = kept;
    if waiting.is_empty() {
        return Vec::new();
    }
    if state.codex_opens_awaiting_catalog.is_empty() {
        state.codex_catalog_waiting_since = None;
    }
    // Per word and per role: the notice names the role, so a Worker and a Goinkyo
    // asking for the same word are two answers and two lines.
    let mut resolved: Vec<((String, BrigadeRole), crate::codex_model::Resolved)> = Vec::new();
    let mut opens = Vec::with_capacity(waiting.len());
    // One creation per member. [`creation_still_wanted`] does not count the
    // creation's own placeholder key, so two held creations of one member (a
    // Goinkyo's token and key are reused by each consultation) would both pass it
    // and open the member twice. The later is the current one: the earlier was
    // asked for by a consultation that has since been replaced.
    let members: Vec<Option<(BrigadeId, String)>> = waiting
        .iter()
        .map(|held| held_creation_member(held).map(|(id, token)| (id, token.to_string())))
        .collect();
    for (at, creation) in waiting.into_iter().enumerate() {
        if members[at].is_some() && members[at + 1..].contains(&members[at]) {
            continue;
        }
        let mut open = creation.open.clone();
        if let Some((brigade_id, token)) = held_creation_member(&creation) {
            let token = token.to_string();
            if !creation_still_wanted(state, brigade_id, &token) {
                forget_unopened_worker(state, brigade_id, &token);
                continue;
            }
        }
        if let Cmd::OpenEmbedded { model, .. } = &mut open
            && let Some(requested) = model.take()
        {
            let asked = (requested, held_creation_role(&creation));
            let at = match resolved.iter().position(|(asked_of, _)| *asked_of == asked) {
                Some(at) => at,
                None => {
                    let answer = crate::codex_model::resolve(&asked.0, &result, asked.1);
                    resolved.push((asked, answer));
                    resolved.len() - 1
                }
            };
            *model = resolved[at].1.model.clone();
        }
        opens.push(open);
    }
    let notices: Vec<&str> = resolved
        .iter()
        .filter_map(|(_, answer)| answer.notice.as_deref())
        .collect();
    if !notices.is_empty() {
        state.set_status(notices.join("; "), now);
    }
    opens
}

/// Codex Workers held for a catalog read that has not been answered for
/// [`CODEX_CATALOG_GIVE_UP`] are opened as for an unreadable catalog, which says
/// so. What the operator would otherwise see is nothing: a Worker with a store
/// row, no pane and no tile, indefinitely, and — because the next creation asks
/// for a read only when none is held — no Codex Worker could be created again
/// for the rest of the run. The clock starts at the first tick that sees them
/// held.
fn give_up_on_codex_catalog(state: &mut EmporiumState, now: Instant) -> Vec<Cmd> {
    if state.codex_opens_awaiting_catalog.is_empty() {
        state.codex_catalog_waiting_since = None;
        return Vec::new();
    }
    let since = *state.codex_catalog_waiting_since.get_or_insert(now);
    if now.saturating_duration_since(since) < CODEX_CATALOG_GIVE_UP {
        return Vec::new();
    }
    // The round that has been waiting: the oldest held creation's.
    let round = state.codex_opens_awaiting_catalog[0].round;
    update_codex_catalog_read(
        state,
        round,
        Err(format!(
            "no answer after {}s",
            CODEX_CATALOG_GIVE_UP.as_secs()
        )),
        now,
    )
}

fn update_spawn_failed(
    state: &mut EmporiumState,
    app: &App,
    key: SessionKey,
    error: String,
    refusal: SpawnRefusal,
    now: Instant,
) -> Vec<Cmd> {
    state.unresolved_codex.remove(&key);
    state.pending_opens.remove(&key);
    let was_relaunch = state.relaunching.remove(&key);
    if was_relaunch {
        return relaunch_failed(state, app, key, error, refusal, now);
    }
    state.set_status(format!("failed to open: {error}"), now);
    Vec::new()
}

/// A Worker's relaunch that did not open. Turned away because a Codex pane is
/// unidentified (the shell knew of one the core did not), it goes back to being
/// held, to be tried again after an event that can change the shell's trackers.
/// A process that could not be started (`PtyOpen`) is a Worker that exited and
/// cannot be reopened, and it is dealt with as one that exited twice: the empty
/// tile goes and the member leaves its brigade ([`update_pty_exited`]'s `GaveUp`),
/// with the reason in the line the store's answer writes. Left alone it would be a
/// frame with no process behind it and a name on the roster that no one can reach.
/// The other refusals are not that: the banto executable replaced under a running
/// banto (a rebuild while it runs), an MCP configuration that could not be written,
/// the session already running in another pane, a wait. They say what happened and
/// leave the frame and the roster, as any open that fails does, for a restaging to
/// reopen.
fn relaunch_failed(
    state: &mut EmporiumState,
    app: &App,
    key: SessionKey,
    error: String,
    refusal: SpawnRefusal,
    now: Instant,
) -> Vec<Cmd> {
    let (Some(&brigade_id), Some(token)) = (
        state.member_brigades.get(&key),
        state.member_tokens.get(&key).cloned(),
    ) else {
        state.set_status(format!("failed to open: {error}"), now);
        return Vec::new();
    };
    if refusal == SpawnRefusal::CodexIdentifying {
        hold_relaunch(state, &key, brigade_id, token, true);
        return Vec::new();
    }
    if refusal != SpawnRefusal::PtyOpen {
        state.set_status(format!("failed to open: {error}"), now);
        return Vec::new();
    }
    let leaving = departing_worker(state, &key).filter(|_| !app.should_quit());
    state.screens.remove(&key);
    state.launch_agents.remove(&key);
    state.quiescence.remove(&key);
    state.unstage(&key);
    let call = state.member_call(Some(brigade_id), &token);
    state.set_status(
        format!("could not restart {call}: {error} \u{2014} left closed"),
        now,
    );
    match leaving {
        Some((brigade_id, token)) => {
            state
                .relaunch_failures
                .insert((brigade_id, token.clone()), error);
            state.removing_exited.insert((brigade_id, token.clone()));
            vec![Cmd::Store(StoreIntent::DismissExitedWorker {
                brigade_id,
                token,
                repeated: true,
            })]
        }
        None => Vec::new(),
    }
}

/// The one answer to anything turned away because a Codex pane is still being
/// identified, run at the end of every update (so every entrance, and a later
/// caller such as [`relaunch_member`], only raise
/// [`EmporiumState::identification_refused`]): a Codex resume (the list's Enter,
/// the filter in [`update`], the shell's guard), the staging of a brigade with a
/// Codex member that has no pane, `x` on a Codex row with no pane.
///
/// The guard itself is not loosened: a second resume of a session whose pane is
/// merely unnamed would fork its history (invariant 4, `docs/DISCIPLINE.md` §3).
/// What changes is that the refusal points at what it is waiting for. It names
/// the pane, brings it to the stage and focuses it when it can be shown, marks its
/// tile ([`UNIDENTIFIED_MARK`]) until it is identified or gone, and tells the
/// operator how to get on.
fn settle_identification_refusal(state: &mut EmporiumState, app: &App, now: Instant) {
    state
        .refused_for
        .retain(|key| state.unresolved_codex.contains(key));
    if !std::mem::take(&mut state.identification_refused) {
        return;
    }
    let forward = std::mem::take(&mut state.identification_forward);
    let held = state.identification_held.take();
    let cause = state.identification_cause();
    if let Some(key) = &cause {
        state.refused_for.insert(key.clone());
        if forward {
            state.bring_forward(key);
        }
    }
    let mut text = state.identification_wait_text(app, cause.as_ref(), held.as_ref());
    if std::mem::take(&mut state.identification_saved_brigade) {
        text.insert_str(0, "Brigade saved \u{2014} ");
    }
    state.set_status(text, now);
}

impl EmporiumState {
    /// Whether `key`'s tile is a Worker's whose reopen is held, with no process behind it.
    fn is_held(&self, key: &SessionKey) -> bool {
        self.held_relaunches.iter().any(|held| held.key == *key) && !self.screens.contains_key(key)
    }

    /// Turn the operator away because a Codex pane is still being identified.
    /// Every entrance calls this and nothing else, and the end of the update
    /// answers ([`settle_identification_refusal`]), so the words and the stage are
    /// the same for all of them.
    fn refuse_for_unidentified_codex(&mut self) {
        self.identification_refused = true;
        self.identification_forward = true;
    }

    /// [`Self::refuse_for_unidentified_codex`] for an open that was refused after
    /// it was emitted (the filter at the end of [`update`], the shell's guard),
    /// where `refused` is what it was for. A Worker's own relaunch after its exit is
    /// not answered here: no operator asked for it, and answering it would take the
    /// stage from the brigade it is on. It goes back to being held instead
    /// ([`relaunch_failed`]), which tells the operator without moving anything. An
    /// open of a brigade member that the operator did ask for (staging) is answered
    /// like any other.
    fn refuse_reopen_for_unidentified_codex(&mut self, refused: &SessionKey) {
        if !self.relaunching.contains(refused) {
            self.refuse_for_unidentified_codex();
        }
    }

    /// What the status line says while a Worker's reopen is held. The Worker is
    /// called as everywhere else; the way on is the same as for a refusal
    /// ([`Self::identification_wait_text`]), and the line says what happens by
    /// itself.
    fn held_relaunch_text(
        &self,
        app: &App,
        cause: Option<&SessionKey>,
        held: &SessionKey,
    ) -> String {
        let call = match self
            .member_brigades
            .get(held)
            .zip(self.member_tokens.get(held))
        {
            Some((brigade_id, token)) => self.member_call(Some(*brigade_id), token),
            None => held.as_str().to_string(),
        };
        let member_cause = cause.and_then(|key| {
            self.member_brigades
                .get(key)
                .zip(self.member_tokens.get(key))
        });
        match (cause, member_cause) {
            (_, Some((brigade_id, token))) => format!(
                "Restart of {call} is held until {} of brigade {} is identified. If that never happens, remove it with {} x on its tile.",
                self.member_call(Some(*brigade_id), token),
                self.brigade_name(app, *brigade_id),
                self.prefix_label(),
            ),
            (Some(_), None) => format!(
                "Restart of {call} is held: a new Codex pane isn't identified yet. Enter on this tile shows it; close it with {} x (or send its first message) and the restart goes ahead.",
                self.prefix_label(),
            ),
            (None, None) => {
                format!("Restart of {call} is held while a new Codex pane is identified")
            }
        }
    }

    /// The unidentified Codex pane a refusal names. Only a pane with a screen
    /// qualifies (one whose spawn has not landed has nothing to show). Of those,
    /// one already on the stage comes first, so a refusal does not move the
    /// operator away from what they are looking at; otherwise the one that has
    /// waited longest, which is the one opened before whatever they were doing
    /// when they were refused. Closing it and asking again names the next.
    fn identification_cause(&self) -> Option<SessionKey> {
        let hosted = || {
            self.unresolved_codex
                .iter()
                .filter(|key| self.screens.contains_key(*key))
        };
        let staged = |key: &SessionKey| match &self.stage {
            Stage::Solo(shown) => shown == key,
            Stage::Brigade { panes, .. } => panes.contains(key),
            Stage::Empty => false,
        };
        hosted()
            .find(|key| staged(key))
            .or_else(|| hosted().next())
            .cloned()
    }

    /// Show `key`'s pane and give it the keys, when it can be shown: a pane on the
    /// stage is focused (opened first if its tile is collapsed, as addressing a
    /// pane by number does); a lone pane takes the stage. A brigade member that is
    /// not on the stage stays where it is: its brigade comes back from its
    /// Director's row, and the wait says which, because showing one tile of a
    /// brigade is not something staging does.
    fn bring_forward(&mut self, key: &SessionKey) {
        if let Stage::Brigade { panes, .. } = &self.stage
            && let Some(index) = panes.iter().position(|pane| pane == key)
        {
            if index > 0 && self.pane_collapsed().get(index).copied().unwrap_or(false) {
                toggle_minimize(self, key);
            }
            self.focus = Focus::Pane;
            if let Stage::Brigade { focused, .. } = &mut self.stage {
                *focused = index;
            }
        } else if matches!(&self.stage, Stage::Solo(shown) if shown == key) {
            self.focus = Focus::Pane;
        } else if !self.member_brigades.contains_key(key) {
            self.stage = Stage::Solo(key.clone());
            self.focus = Focus::Pane;
        }
    }

    /// What the status line says for a refusal, built here for every entrance.
    /// It cannot say "another session": the pane may be the very one the operator
    /// asked for, which banto cannot tell yet. For a lone pane the way on is to
    /// close it (the prefix chord as the hint line writes it) and ask the row
    /// again, which is always identified because a row's resume carries its id;
    /// the conversation stays in the list. A brigade member is told to wait first:
    /// it is identified by its first turn's hook, which nearly always lands within
    /// seconds. Only then comes the way out for a hook that never lands (an
    /// untrusted directory, a path with a space, a store that cannot be written):
    /// `x` on its tile, which removes a Worker from its brigade for good, as a
    /// Worker is disposable. Said last because it is the costlier choice, and the
    /// line is short enough that the wait comes first when it is cut.
    fn identification_wait_text(
        &self,
        app: &App,
        cause: Option<&SessionKey>,
        held: Option<&SessionKey>,
    ) -> String {
        if let Some(held) = held {
            return self.held_relaunch_text(app, cause, held);
        }
        let Some(key) = cause else {
            return "A new Codex pane is still being identified \u{2014} try that row again in a moment"
                .to_string();
        };
        match self
            .member_brigades
            .get(key)
            .zip(self.member_tokens.get(key))
        {
            Some((brigade_id, token)) => format!(
                "{} of brigade {} isn't identified yet \u{2014} try again in a moment. If it stays that way, remove it with {} x on its tile.",
                self.member_call(Some(*brigade_id), token),
                self.brigade_name(app, *brigade_id),
                self.prefix_label(),
            ),
            None => format!(
                "New Codex pane not identified yet (banto can't tell which session it is). Close it with {} x, then Enter on the row again; or send its first message.",
                self.prefix_label(),
            ),
        }
    }
}

/// What [`relaunch_member`] decided about an exit it recognised.
enum ExitHandling {
    /// Put the member back: the tile stays, this rebuilds what was under it.
    /// Boxed because a `Cmd` is far larger than the other answer, and clippy
    /// is right that an enum should not cost its largest variant everywhere.
    Relaunch(Box<Cmd>),
    /// A member that would have been restarted, except that it was restarted
    /// a moment ago and is evidently not able to stay up. Handled as an
    /// ordinary exit from here, but the operator is told which kind it was.
    GaveUp,
    /// A Codex Worker that would have been restarted, while a Codex pane is
    /// unidentified. Its tile stays, with no screen, and the reopen waits
    /// ([`hold_relaunch`]).
    Held,
}

/// A living Worker's pane ended without banto asking, so put it back.
///
/// The case this exists for: an agent CLI updates itself, its process is
/// replaced, and the pane goes with it. Everything banto persists about the
/// member survives that — the store row, its token, its session id — so what
/// was lost is only the pane, and re-opening the whole brigade is a heavy way
/// to get one back. `Some(Relaunch)` means the tile stays where it is and its
/// screen is rebuilt when the spawn lands (`update_spawned` already tolerates a
/// key that is still staged). `Some(Held)` is the same restart, waiting: a Codex
/// resume is not made while a Codex pane is unidentified ([`hold_relaunch`]).
/// `None` and `Some(GaveUp)` mean it is not coming
/// back: `update_pty_exited` then un-stages the pane and, for a Worker that left
/// on its own, removes the member from its brigade (`unrequested_worker_exit`) —
/// a member with no pane is an invisible one.
///
/// Four things have to hold, and each of them is a way this could resurrect
/// something that was meant to stay dead:
///
/// - **banto did not ask for the exit** ([`kill_pane`]). A kill banto requested —
///   dismissing, disbanding, a Goinkyo's end — is not a process that fell over.
/// - **banto still holds a screen for the pane.** A key whose pane was already
///   dealt with has nothing left to restart.
/// - **It is a Worker.** The Director's own pane has two reopen paths of its
///   own that run before this, and a Goinkyo's absence is answered by
///   `gather_goinkyo_observations` against the store rather than here.
/// - **Its session resolves to a row**, because this restarts a session
///   rather than starting one. A Worker that never spoke has nothing to resume
///   and, with no one to ask, leaves the brigade.
///
/// And it is **not restarted a moment ago** ([`RELAUNCH_COOLDOWN`]): a second
/// death inside it is `GaveUp`, and the Worker leaves too.
fn relaunch_member(
    state: &mut EmporiumState,
    app: &App,
    brigade: &BrigadeConfig,
    key: &SessionKey,
    banto_asked: bool,
    now: Instant,
) -> Option<ExitHandling> {
    if banto_asked {
        return None;
    }
    if !state.screens.contains_key(key) {
        return None;
    }
    let brigade_id = *state.member_brigades.get(key)?;
    let token = state.member_tokens.get(key)?.clone();
    if token == DIRECTOR_TOKEN
        || token == GOINKYO_TOKEN
        || state.goinkyo_pane.values().any(|pane| pane == key)
        // A brigade being closed is ending its panes on purpose; one that
        // exited on its own a moment before is not restarted into that.
        || state.closing.contains_key(&brigade_id)
    {
        return None;
    }
    let row = app.row_for_id(key.as_str())?;
    if state
        .last_relaunch
        .get(key)
        .is_some_and(|at| now.saturating_duration_since(*at) < RELAUNCH_COOLDOWN)
    {
        return Some(ExitHandling::GaveUp);
    }
    // A Codex resume is not made while a Codex pane is unidentified: the pane may
    // be this very session, and a second process on it forks its history
    // (invariant 4). The Worker's tile is emptied as for any relaunch and the
    // reopen waits ([`hold_relaunch`]); the cooldown is stamped when it is made,
    // not now, since nothing was tried.
    let held = row.agent == AgentKind::Codex && !state.unresolved_codex.is_empty();
    if !held {
        state.last_relaunch.insert(key.clone(), now);
    }
    state.screens.remove(key);
    state.launch_agents.remove(key);
    state.quiescence.remove(key);
    if held {
        hold_relaunch(state, key, brigade_id, token, false);
        return Some(ExitHandling::Held);
    }
    Some(ExitHandling::Relaunch(Box::new(relaunch_open(
        state, row, brigade, key, brigade_id, &token, now,
    ))))
}

/// The open that puts a Worker's pane back, and the bookkeeping that goes with
/// making it: the cooldown clock, the pending open, and the mark that tells a
/// failed spawn of it ([`update_spawn_failed`]) from a failed open of anything else.
fn relaunch_open(
    state: &mut EmporiumState,
    row: &SessionRow,
    brigade: &BrigadeConfig,
    key: &SessionKey,
    brigade_id: BrigadeId,
    token: &MemberToken,
    now: Instant,
) -> Cmd {
    state.last_relaunch.insert(key.clone(), now);
    state.relaunching.insert(key.clone());
    let cwd = row.cwd.clone().unwrap_or_else(|| PathBuf::from("."));
    state.pending_opens.insert(
        key.clone(),
        PendingOpen::BrigadeMember {
            brigade_id,
            // Resuming a session that already exists, exactly as a re-stage
            // does: the first prompt only ever belongs to a creation.
            first_turn: None,
        },
    );
    // The Planner comes back the way a Worker does, in place and once per
    // cooldown, but as itself: its own launch settings, and its own words, since
    // the operator did not name it.
    let role = if token == PLANNER_TOKEN {
        BrigadeRole::Planner
    } else {
        BrigadeRole::Worker
    };
    let launch = RoleLaunch::of(role, row.agent, brigade);
    let call = state.member_call(Some(brigade_id), token);
    state.set_status(
        match role {
            BrigadeRole::Planner => "the Planner exited \u{2014} restarting".to_string(),
            BrigadeRole::Director | BrigadeRole::Worker | BrigadeRole::Goinkyo => {
                format!("worker {call} exited \u{2014} restarting")
            }
        },
        now,
    );
    Cmd::OpenEmbedded {
        key: key.clone(),
        target: SessionToOpen {
            id: row.id.clone(),
            agent: row.agent,
            title: row.sentence_name(),
            cwd,
        },
        brigade: Some((brigade_id, token.clone(), role)),
        // A resume (`RoleLaunch`'s doc): the session keeps what it last used.
        model: None,
        effort: None,
        permission_mode: launch.permission_mode,
        disallowed_tools: launch.disallowed_tools,
        autocompact: launch.autocompact,
        first_prompt: None,
    }
}

/// Hold `key`'s reopen until no Codex pane is unidentified, and say so. What banto
/// did on its own moves nothing on the stage: the line names the Worker and the
/// pane it waits for, and that pane's tile is marked. (The operator pressing Enter
/// on the empty tile is the one thing that brings the pane forward, in
/// [`update_key`].)
fn hold_relaunch(
    state: &mut EmporiumState,
    key: &SessionKey,
    brigade_id: BrigadeId,
    token: MemberToken,
    shell_refused: bool,
) {
    state.held_relaunches.push(HeldRelaunch {
        key: key.clone(),
        brigade_id,
        token,
        shell_refused,
    });
    state.identification_refused = true;
    state.identification_held = Some(key.clone());
}

/// Whether `ev` can change which panes the shell tracks for identification: a pane
/// that ended (the shell drops its tracker, `update_event` in the shell) or one
/// that was identified (the tracker is resolved and goes). Nothing else removes a
/// tracker. A tick, a resize or a key press never does, so none of them is a reason
/// to ask the shell the same question again.
fn changes_shell_trackers(ev: &Event) -> bool {
    matches!(
        ev,
        Event::PtyExited { .. } | Event::PtyOutputLost { .. } | Event::DiscoveryResult { .. }
    )
}

/// Make the reopens that were held, once nothing is unidentified: at the end of an
/// update, after the loop that notes which opens leave a Codex pane unidentified,
/// so a pane that this very update opens keeps them waiting. Each is checked
/// again first, since the wait can be long: the key must have no screen and no open
/// under way (or asked for by this update), the member must be the same one, and
/// nobody may be ending it, the brigade or the program. One that fails the check is
/// dropped, nothing else; a brigade staged again later opens its pane-less members
/// as it always does. Which brigade is on the stage is not asked: a Worker of one
/// that is not shown is reopened when nothing waits, so it is when something did.
///
/// A hold the shell refused ([`HeldRelaunch::shell_refused`]) stays where it is
/// unless this event is one that can change the shell's trackers.
fn release_held_relaunches(
    state: &mut EmporiumState,
    app: &App,
    brigade: &BrigadeConfig,
    emitted: &[Cmd],
    tracker_event: bool,
    now: Instant,
) -> Vec<Cmd> {
    let mut opens = Vec::new();
    for held in std::mem::take(&mut state.held_relaunches) {
        if held.shell_refused && !tracker_event {
            state.held_relaunches.push(held);
            continue;
        }
        let HeldRelaunch {
            key,
            brigade_id,
            token,
            ..
        } = held;
        let same_member = state.member_brigades.get(&key) == Some(&brigade_id)
            && state.member_tokens.get(&key) == Some(&token);
        let opened_meanwhile = state.screens.contains_key(&key)
            || state.pending_opens.contains_key(&key)
            || emitted
                .iter()
                .any(|cmd| matches!(cmd, Cmd::OpenEmbedded { key: opened, .. } if *opened == key));
        let ending = state.disbanding.contains(&brigade_id)
            || state.closing.contains_key(&brigade_id)
            || state.pending_dismiss.as_ref() == Some(&key)
            || state
                .pending_dismiss_member
                .as_ref()
                .is_some_and(|(brigade, member)| *brigade == brigade_id && *member == token)
            || state.removing_exited.contains(&(brigade_id, token.clone()));
        if app.should_quit() || !same_member || opened_meanwhile || ending {
            continue;
        }
        let Some(row) = app.row_for_id(key.as_str()) else {
            continue;
        };
        opens.push(relaunch_open(
            state, row, brigade, &key, brigade_id, &token, now,
        ));
    }
    opens
}

/// `D`: take the selected session back out of banto's archive. No confirm,
/// unlike `d`'s: burying is what disorients — a row leaves a list the operator
/// is reading — and that is what the confirm guards. Bringing one back puts a
/// row where the operator was already looking at its archived form, and `d`
/// undoes it again in one key.
fn unarchive_selected(state: &mut EmporiumState, app: &mut App, now: Instant) -> Vec<Cmd> {
    let Some(row) = app.selected_row() else {
        return Vec::new();
    };
    if !row.archived {
        state.set_status(
            "that session is not archived — press `a` until archived sessions show",
            now,
        );
        return Vec::new();
    }
    let id = row.id.clone();
    let title = row.sentence_name();
    vec![Cmd::Store(StoreIntent::Unarchive { id, title })]
}

fn update_pty_exited(
    state: &mut EmporiumState,
    app: &mut App,
    brigade: &BrigadeConfig,
    key: SessionKey,
    reason: Option<PtyExitReason>,
    now: Instant,
) -> Vec<Cmd> {
    let banto_asked = state.expected_exits.remove(&key).is_some();
    state.hangups.remove(&key);
    // Read before the unstage below takes the maps: an exit in a brigade that is
    // being closed is one of the panes the close ended, and says nothing itself.
    let in_closing_brigade = state
        .member_brigades
        .get(&key)
        .is_some_and(|brigade_id| state.closing.contains_key(brigade_id));
    // Decided before anything below touches the member's maps: whether this is a
    // Worker that left on its own, so that if it cannot be relaunched it leaves
    // the brigade instead of lingering in the roster with no tile.
    let leaving = unrequested_worker_exit(state, app, &key, banto_asked);
    let gave_up = match relaunch_member(state, app, brigade, &key, banto_asked, now) {
        Some(ExitHandling::Relaunch(cmd)) => return vec![*cmd],
        Some(ExitHandling::Held) => return Vec::new(),
        Some(ExitHandling::GaveUp) => true,
        None => false,
    };
    state.screens.remove(&key);
    state.launch_agents.remove(&key);
    state.quiescence.remove(&key);
    state.unstage(&key);
    // A Goinkyo pane can close this way without ever being dismissed (its
    // process just dies) — `goinkyo_pane`'s own doc: still discoverable, so a
    // later re-stage resumes it (the member stays; only a Worker that leaves on
    // its own is removed, `unrequested_worker_exit`). Dropping the entry keeps a
    // stale key from being killed or unstaged later, but it is not only hygiene:
    // `NoGoinkyo` asks for its one reload only on the tick that still finds the
    // entry. A Goinkyo whose pane died first and is dismissed afterwards from the
    // Director's own process (`dismiss_goinkyo`) therefore gets no reload from
    // that arm, and its archived session stays in this process's hidden set until
    // the next reload, which any transcript write under the agent homes brings
    // (the watch in `banto_io::watch::live`, debounced 250ms).
    state.goinkyo_pane.retain(|_, pane| *pane != key);
    // The Planner's guard is released the same way for a pane that had been
    // identified, but a placeholder key stays: a Planner that died before it was
    // ever identified, or that failed to start, would otherwise be created again on
    // the next tick, and again, for as long as the cause lasts. Staging the
    // brigade again lifts it (`stage_brigade`).
    state
        .planner_pane
        .retain(|_, pane| *pane != key || pane.is_synthetic());
    // A Director-reopen confirm killed exactly this pane and is waiting for
    // it to actually be gone before reopening it wired — see
    // `confirm_director_reopen_modal`'s doc for why "gone" can't be assumed
    // any earlier than this event. Takes over from the generic "session
    // ended" status below: formation continuing *is* what happens next.
    if state
        .pending_director_reopen
        .as_deref()
        .is_some_and(|id| SessionKey::from_id(id) == key)
    {
        let director_row_id = state.pending_director_reopen.take().unwrap();
        return match app.row_for_id(&director_row_id).cloned() {
            Some(row) => begin_brigade_formation(state, app, brigade, &row),
            None => Vec::new(),
        };
    }
    // The residual-race counterpart above (`PendingDirectorWiring`'s own
    // doc): the brigade already exists in the store, so there is nothing
    // left to decide, only wiring to apply once this pane is confirmed gone.
    if state
        .pending_director_wiring
        .as_ref()
        .is_some_and(|wiring| SessionKey::from_id(&wiring.director_row_id) == key)
    {
        let wiring = state.pending_director_wiring.take().unwrap();
        return open_director_with_wiring(state, app, wiring);
    }
    // One line for the whole brigade, said once its last pane is gone
    // ([`settle_closing`]); not one "session ended" per pane.
    if in_closing_brigade {
        return Vec::new();
    }
    let title = app
        .row_for_id(key.as_str())
        .map(SessionRow::sentence_name)
        .unwrap_or_else(|| key.as_str().to_string());
    let mut status = match reason {
        Some(reason) => format!("session ended: {title} — {}", reason.describe()),
        None => format!("session ended: {title}"),
    };
    if gave_up {
        // The one exit that would otherwise read as an ordinary one while
        // meaning something else entirely: banto tried this member a moment
        // ago and is declining to try again.
        status.push_str(" (restarted once already — left closed)");
    }
    state.set_status(status, now);
    // Not relaunched (the relaunch returned above), so the Worker is not coming
    // back: it leaves the brigade. Its answer replaces the status above.
    match leaving {
        Some((brigade_id, token)) => {
            state.removing_exited.insert((brigade_id, token.clone()));
            vec![Cmd::Store(StoreIntent::DismissExitedWorker {
                brigade_id,
                token,
                repeated: gave_up,
            })]
        }
        None => Vec::new(),
    }
}

/// A pane whose output is lost while its process is not known to have exited.
/// The pane is unusable — banto cannot read it — so the tile goes; but nothing
/// says the member left, so **nothing is removed from the store** (the member,
/// its cursor and its mail stay) and nothing is relaunched.
///
/// The process is asked to end through the asked-for path ([`kill_pane`]);
/// its handle remains until the waiter confirms that it exited.
///
/// Not relaunched in place, on purpose: a reader that fails immediately would
/// loop, restarting a process each time, and a relaunch while the old process
/// might still be alive would resume one session twice (the double-resume the
/// brigade guards against). Once the process exit is confirmed, the next
/// staging can reopen the member; the one-pane rule makes that a single reopen.
///
fn update_pty_output_lost(
    state: &mut EmporiumState,
    app: &mut App,
    _brigade: &BrigadeConfig,
    key: SessionKey,
    now: Instant,
) -> Vec<Cmd> {
    // Said as the operator knows it, before the cleanup drops the member's maps.
    let call = match (
        state.member_brigades.get(&key),
        state.member_tokens.get(&key),
    ) {
        (Some(brigade_id), Some(token)) => state.member_call(Some(*brigade_id), token),
        _ => app
            .row_for_id(key.as_str())
            .map(SessionRow::sentence_name)
            .unwrap_or_else(|| key.as_str().to_string()),
    };
    let is_member = state.member_tokens.contains_key(&key);
    let was_expected = state.expected_exits.contains_key(&key);
    let cmds = if was_expected {
        Vec::new()
    } else {
        kill_pane(state, key.clone()).into_iter().collect()
    };
    state.lost_output_waiting_for_exit.insert(key.clone());
    state.screens.remove(&key);
    state.launch_agents.remove(&key);
    state.quiescence.remove(&key);
    state.unstage(&key);
    state.goinkyo_pane.retain(|_, pane| *pane != key);
    state
        .planner_pane
        .retain(|_, pane| *pane != key || pane.is_synthetic());
    if was_expected {
        return cmds;
    }
    state.set_status(
        if is_member {
            format!("lost the output of {call} \u{2014} pane closed; it stays in the brigade")
        } else {
            format!("lost the output of {call} \u{2014} pane closed")
        },
        now,
    );
    cmds
}

/// Whether a pane that just ended is a Worker that left on its own — the only
/// exit after which, if it is not relaunched, the member is removed from its
/// brigade (no confirmation: nobody is at the keyboard for it). Every condition
/// is a way this could remove a member that was meant to stay or was already
/// going:
///
/// - **its process is known to have exited**: this runs only for
///   `Event::PtyExited`, which the shell sends on the wait thread's report; a pane
///   whose output merely stopped is `Event::PtyOutputLost`, which removes nobody.
/// - **banto did not ask for the exit** (`banto_asked`, [`kill_pane`]): a kill
///   the operator or a teardown requested — disband, dismissal, the Goinkyo's end,
///   a Director reopen — has its own outcome already.
/// - **banto is not quitting** (`App::should_quit`): the loop still drains the
///   iteration's queue after the quit key, and a pane that ends in that queue
///   ends because banto is closing, not because its Worker left. (After the loop
///   every handle is closed without another event being read.)
/// - **the pane is one banto still holds a screen for**, so a second event for
///   the same key finds nothing and no member is removed twice.
/// - **it is a Worker of a brigade**: not the Director, not the Goinkyo (a
///   consultation that ends without being dismissed keeps today's outcome), not a
///   pane with no membership.
/// - **its brigade is not being disbanded, closed or gone**
///   ([`EmporiumState::disbanding`], [`EmporiumState::closing`]).
/// - **no dismissal of this member is already in flight**: the operator's own
///   (`pending_dismiss`), or the one this function starts (`removing_exited`).
fn unrequested_worker_exit(
    state: &EmporiumState,
    app: &App,
    key: &SessionKey,
    banto_asked: bool,
) -> Option<(BrigadeId, MemberToken)> {
    if banto_asked || app.should_quit() || !state.screens.contains_key(key) {
        return None;
    }
    departing_worker(state, key)
}

/// The rest of [`unrequested_worker_exit`]: that `key` is a Worker of a brigade
/// that nobody is ending and whose removal nobody has asked for.
fn departing_worker(state: &EmporiumState, key: &SessionKey) -> Option<(BrigadeId, MemberToken)> {
    let brigade_id = *state.member_brigades.get(key)?;
    let token = state.member_tokens.get(key)?.clone();
    // Not the Planner either: it leaves with its Plan, through the transaction that
    // closes it (`Store::close_plan`), and a process that died is not that.
    if token == DIRECTOR_TOKEN
        || token == GOINKYO_TOKEN
        || token == PLANNER_TOKEN
        || state.goinkyo_pane.values().any(|pane| pane == key)
        || state.planner_pane.values().any(|pane| pane == key)
        || state.disbanding.contains(&brigade_id)
        || state.closing.contains_key(&brigade_id)
        || state.pending_dismiss.as_ref() == Some(key)
        || state
            .pending_dismiss_member
            .as_ref()
            .is_some_and(|(brigade, member)| *brigade == brigade_id && *member == token)
        || state.removing_exited.contains(&(brigade_id, token.clone()))
    {
        return None;
    }
    Some((brigade_id, token))
}

/// Report a write whose target has no live PTY handle, whatever produced it.
fn update_pty_write_dropped(state: &mut EmporiumState, key: SessionKey, now: Instant) -> Vec<Cmd> {
    state.set_status(
        format!(
            "internal: a write to {} found no live pane — this is a bug",
            key.as_str()
        ),
        now,
    );
    Vec::new()
}

fn update_discovery_result(
    state: &mut EmporiumState,
    old_key: SessionKey,
    session_id: String,
    member: Option<(BrigadeId, MemberToken)>,
    now: Instant,
) -> Vec<Cmd> {
    if !state.screens.contains_key(&old_key) {
        return Vec::new();
    }
    let new_key = SessionKey::from_id(&session_id);
    if new_key == old_key {
        return Vec::new();
    }
    // Refuse a discovery that would collapse two panes onto one key rather
    // than merging them: the second pane would draw the first one's screen,
    // be titled after it, have its own child's handle orphaned, and — via
    // the store write below — claim the first one's session id as its own
    // brigade membership. Discovery is supposed to make this unreachable
    // (the shell excludes ids it already hosts), but "supposed to" is not a
    // reason to let a destructive merge through.
    //
    // Refusing here is a dead end, not a deferral: by the time this event
    // reaches `update`, the shell's `poll_discovery` has already dropped
    // `old_key`'s tracker from its list (it `retain`s out every id it
    // resolves, unconditionally, before the event is even dispatched) — so
    // there is nothing left to retry. The degraded outcome is that
    // `old_key`'s pane keeps its synthetic placeholder key forever: no
    // `Cmd::Store(StoreIntent::SetMemberSession)` ever fires for it, so a
    // brigade member hosted there stays unidentified (no store row) for the
    // rest of the run. That is accepted on purpose rather than re-queued,
    // because a permanently-unresolvable tracker re-queued for another
    // attempt would re-run `find_new_sessions` — a full scan of the
    // projects directory, the most expensive I/O `poll_discovery` does —
    // on every poll tick (as often as ~50ms) for as long as the pane stays
    // open. And this branch is meant to be a last-resort backstop, not the
    // common case: the claimed-set guard `poll_discovery` already applies
    // (ids already held by an open pane, sourced from the live handle map)
    // is what is supposed to keep two trackers from ever resolving onto the
    // same id in the first place.
    if state.screens.contains_key(&new_key) {
        state.set_status(
            format!("discovery collision on {session_id} — ignored"),
            now,
        );
        return Vec::new();
    }
    state.unresolved_codex.remove(&old_key);
    let mut cmds = Vec::new();
    if state.rekey_pane_state(&old_key, &new_key) {
        cmds.push(Cmd::RekeyPty {
            from: old_key.clone(),
            to: new_key.clone(),
        });
    }
    // A discovered Codex session is the acknowledgement that its first turn
    // started: its only discovery source is the hook that turn runs. A Claude
    // Goinkyo is discovered from its live file before it has had a turn, so for it
    // discovery says nothing and the watch only follows the key.
    if state
        .first_turn_watch
        .get(&new_key)
        .is_some_and(|watch| watch.agent == AgentKind::Codex)
    {
        state.first_turn_watch.remove(&new_key);
    }
    if let Some((brigade_id, token)) = member {
        state
            .member_tokens
            .entry(new_key.clone())
            .or_insert_with(|| token.clone());
        state
            .member_brigades
            .entry(new_key.clone())
            .or_insert(brigade_id);
        cmds.push(Cmd::Store(StoreIntent::SetMemberSession {
            brigade_id,
            token,
            session_id,
        }));
    }
    cmds
}

/// Whether something already holds the conversation a move would land on: a pane
/// hosted under `new_key`, an open for it in flight, or another member's row
/// (`held_by_row`).
fn conversation_is_held(state: &EmporiumState, new_key: &SessionKey, held_by_row: bool) -> bool {
    held_by_row || state.screens.contains_key(new_key) || state.pending_opens.contains_key(new_key)
}

/// Whether a pane's move to `new_key` is refused because something else holds that
/// conversation, and the refusal is new. `Some(announce)` is a refusal (nothing may
/// be renamed or written), `announce` true the first time for this pane and id.
/// `None`: the conversation is free.
///
/// Held means any of: another pane is hosted under that key, an open for it is in
/// flight (the operator pressed Enter on its row just before the in-pane
/// `/resume`), or another member's store row records it (`held_by_row`, read by the
/// shell) with its pane closed.
///
/// The case is real: an in-pane `/resume` of a session this banto hosts in another
/// pane puts two processes on one conversation, which is the double resume
/// (REQUIREMENTS, invariant 4) done from inside a pane. Renaming onto the other
/// pane would also collapse two panes into one key, which is what
/// `update_discovery_result`'s collision guard refuses for the same reason. A
/// member's row is no safer: `SetMemberSession` moves a session id between rows, so
/// writing a held one would silently unlink the member that has it, and the next
/// re-stage would resume it beside the pane that took it.
fn refuse_move_onto_a_held_key(
    state: &mut EmporiumState,
    old_key: &SessionKey,
    new_key: &SessionKey,
    new_id: &str,
    held_by_row: bool,
) -> Option<bool> {
    if !conversation_is_held(state, new_key, held_by_row) {
        return None;
    }
    let screens = &state.screens;
    state
        .refused_session_moves
        .retain(|(key, _)| screens.contains_key(key));
    Some(
        state
            .refused_session_moves
            .insert((old_key.clone(), new_id.to_string())),
    )
}

/// A live member's own process now reports another session id (see
/// [`Event::MemberSessionForked`]'s doc). The store write and the pane/screen
/// rename go together: the pane is renamed whenever it is still alive, including
/// while another brigade is displayed, and the store row follows. `focused` needs
/// no fixing of its own, since renaming `panes[i]`'s *value* in place never moves
/// what index it lives at. Idempotent under a repeated fact: once `old_id`'s pane
/// has been renamed, `old_id` is no longer a pane and this becomes a store-only
/// write, same as the "not staged" case below.
///
/// If `new_id` is held (see [`refuse_move_onto_a_held_key`]) nothing changes, the
/// store included: writing it would make the member's row claim a conversation
/// something else is running, and the next re-stage would resume it a second time.
/// That holds for a member whose pane is gone too, which is the store-only write
/// below. The refusal is not final: the shell sends the move again while the
/// process stays on the new id, so the rename happens once what held it lets go.
/// It is said once per pane and id.
fn update_member_session_moved(
    state: &mut EmporiumState,
    brigade_id: BrigadeId,
    token: MemberToken,
    (old_id, new_id): (String, String),
    held_by_row: bool,
    now: Instant,
) -> Vec<Cmd> {
    let old_key = SessionKey::from_id(&old_id);
    let new_key = SessionKey::from_id(&new_id);
    let mut cmds = Vec::new();
    if state.screens.contains_key(&old_key) {
        if let Some(announce) =
            refuse_move_onto_a_held_key(state, &old_key, &new_key, &new_id, held_by_row)
        {
            if announce {
                state.set_status(
                    format!(
                        "session moved onto {new_id}, which is already in use — pane not renamed"
                    ),
                    now,
                );
            }
            return cmds;
        }
        state.rekey_pane_state(&old_key, &new_key);
        state
            .member_tokens
            .entry(new_key.clone())
            .or_insert_with(|| token.clone());
        state
            .member_brigades
            .entry(new_key.clone())
            .or_insert(brigade_id);
        cmds.push(Cmd::RekeyPty {
            from: old_key,
            to: new_key,
        });
    } else {
        // No pane to rename, only the row to move, and the row is not free to move
        // onto a conversation something else holds. The pane that took the id
        // under this member's own name (an earlier send of the same move, the
        // rename already applied) is not another holder.
        let own_pane = state.member_tokens.get(&new_key) == Some(&token)
            && state.member_brigades.get(&new_key) == Some(&brigade_id);
        if !own_pane && conversation_is_held(state, &new_key, held_by_row) {
            return cmds;
        }
    }
    cmds.push(Cmd::Store(StoreIntent::SetMemberSession {
        brigade_id,
        token,
        session_id: new_id,
    }));
    cmds
}

/// A hosted pane that is no brigade member now runs another Claude session (see
/// [`Event::PaneSessionMoved`]): the pane takes the new id as its key and nothing is
/// written to the store. Without this a `/clear` in a solo pane leaves it keyed by
/// the conversation it left: its activity reads unknown (no live file names that
/// id), the quit confirmation counts it as "not idle (unknown)", and the next
/// resume of the row opens the conversation before the `/clear`.
///
/// Idempotent under the repeated observation like the member handler: once the pane
/// has the new key, `old_id` is no pane and this does nothing. A member's key (the
/// roster changed under the observation) is left to the member handler.
fn update_pane_session_moved(
    state: &mut EmporiumState,
    (old_id, new_id): (String, String),
    held_by_row: bool,
    now: Instant,
) -> Vec<Cmd> {
    let old_key = SessionKey::from_id(&old_id);
    let new_key = SessionKey::from_id(&new_id);
    if old_key == new_key
        || !state.screens.contains_key(&old_key)
        || state.member_tokens.contains_key(&old_key)
    {
        return Vec::new();
    }
    if let Some(announce) =
        refuse_move_onto_a_held_key(state, &old_key, &new_key, &new_id, held_by_row)
    {
        if announce {
            state.set_status(
                format!("session moved onto {new_id}, which is already in use — pane not renamed"),
                now,
            );
        }
        return Vec::new();
    }
    state.rekey_pane_state(&old_key, &new_key);
    vec![Cmd::RekeyPty {
        from: old_key,
        to: new_key,
    }]
}

/// `Event::BrigadeFormed`'s successful-formation payload, bundled so
/// [`update_brigade_formed`] doesn't tip into clippy's too-many-arguments —
/// these five always travel together anyway, all the way from
/// `StoreIntent::FormBrigade`.
struct FormedBrigade {
    director_row_id: String,
    name: String,
    cwd: PathBuf,
    worker_agent: AgentKind,
    worker_model: String,
    worker_effort: String,
}

fn update_brigade_formed(
    state: &mut EmporiumState,
    app: &mut App,
    formed: FormedBrigade,
    result: Result<(BrigadeId, Vec<MemberToken>), String>,
    now: Instant,
) -> Vec<Cmd> {
    let FormedBrigade {
        director_row_id,
        name,
        cwd,
        worker_agent,
        worker_model,
        worker_effort,
    } = formed;
    let (brigade_id, worker_tokens) = match result {
        Ok(pair) => pair,
        Err(err) => {
            state.set_status(format!("failed to form brigade: {err}"), now);
            return Vec::new();
        }
    };
    if !state.unresolved_codex.is_empty()
        && app
            .row_for_id(&director_row_id)
            .is_none_or(|row| row.agent == AgentKind::Codex)
    {
        // The brigade is saved and stays so, and the line starts by saying it.
        state.refuse_for_unidentified_codex();
        state.identification_saved_brigade = true;
        return Vec::new();
    }
    let director_key = SessionKey::from_id(&director_row_id);
    let worker_count = worker_tokens.len();
    // Joined in the order they were numbered, whichever pane spawns first.
    state.member_order.insert(
        brigade_id,
        std::iter::once(DIRECTOR_TOKEN.to_string())
            .chain(worker_tokens.iter().cloned())
            .collect(),
    );
    // The brigade is named from this moment, not from its first tick: the
    // Director is the row the operator pressed B on, and `name` is its title.
    state.brigade_names.insert(
        brigade_id,
        BrigadeNameFacts {
            brigade_id,
            name: name.clone(),
            director_session: Some(director_row_id.clone()),
            member_names: Vec::new(),
            request: None,
            interrupts: None,
            roster: Vec::new(),
            progress: None,
            plan: None,
        },
    );
    // A brigade formed in this run had no request when it was formed, so one that
    // is stored before the first tick that visits it is a new request, not one a
    // previous run left: only what already stood when this run first saw a brigade
    // is silent ([`apply_request_fact`]).
    state.request_seen.insert(brigade_id, 0);
    let wiring = PendingDirectorWiring {
        director_row_id,
        brigade_id,
        worker_tokens,
        cwd,
        worker_agent,
        worker_model,
        worker_effort,
    };
    let cmds = if state.screens.contains_key(&director_key) {
        // The interactive gate (`begin_brigade_formation`'s caller,
        // `confirm_director_reopen_modal`) is meant to have already closed
        // this pane before `StoreIntent::FormBrigade` was even issued —
        // reaching here with it still open is the residual race worker-3's
        // card called out: something reopened it in the brief window
        // between that confirm and this store round trip landing. The
        // brigade record already exists by this point (this function's own
        // early return above), so there is no clean way left to abort —
        // silently staging the existing pane as-is would reproduce the
        // exact bug this round trip exists to fix (a Director with no
        // MCP/hook wiring), so it is killed and reopened here too, same as
        // the interactive gate, just without asking first.
        state.pending_director_wiring = Some(wiring);
        kill_pane(state, director_key).into_iter().collect()
    } else {
        open_director_with_wiring(state, app, wiring)
    };
    state.set_status(
        format!(
            "brigade formed — {}, {worker_count} worker(s) spawned",
            state.brigade_name(app, brigade_id)
        ),
        now,
    );
    cmds
}

/// How a sentence calls a brigade, given what is known of its name: the
/// Director's title if there is one, else the name stored when it was formed,
/// else its number. Public so the shell, which holds a brigade's stored name
/// but no [`EmporiumState`], says the same thing as [`EmporiumState::brigade_name`]
/// rather than quoting an empty name.
pub fn brigade_label(title: Option<&str>, stored_name: &str, brigade_id: BrigadeId) -> String {
    match title
        .and_then(display_name)
        .or_else(|| display_name(stored_name))
    {
        // An ASCII quote inside the name would end the outer quoting early.
        Some(name) => quote_name(&name),
        None => format!("brigade {brigade_id}"),
    }
}

/// A reduced name as a sentence quotes it: an ASCII `"` inside it becomes `'`,
/// it is cut to [`BRIGADE_NAME_COLUMNS`] display columns, and it goes in quotes.
/// The one rule for a brigade's title and a session's alike.
fn quote_name(name: &str) -> String {
    format!(
        "\"{}\"",
        shorten_to_columns(&name.replace('"', "'"), BRIGADE_NAME_COLUMNS)
    )
}

/// Open the Director wired (MCP config / Codex `-c` overrides — see
/// [`PendingOpen::BrigadeDirector`]'s own doc), for a `director_row_id` whose
/// pane is confirmed *not* open right now — [`update_brigade_formed`]'s
/// direct case, or [`update_pty_exited`] once a kill-and-reopen (either
/// gate) confirms the old pane is actually gone. `Vec::new()` if the row
/// can no longer be found (the session vanished from `app.rows` in the
/// interim) — nothing left to open, but the brigade record itself, and
/// whatever status message the caller already set, stand regardless.
fn open_director_with_wiring(
    state: &mut EmporiumState,
    app: &App,
    wiring: PendingDirectorWiring,
) -> Vec<Cmd> {
    let PendingDirectorWiring {
        director_row_id,
        brigade_id,
        worker_tokens,
        cwd,
        worker_agent,
        worker_model,
        worker_effort,
    } = wiring;
    let director_key = SessionKey::from_id(&director_row_id);
    state.pending_opens.insert(
        director_key.clone(),
        PendingOpen::BrigadeDirector {
            brigade_id,
            worker_tokens,
            cwd: cwd.clone(),
            worker_agent,
            worker_model,
            worker_effort,
        },
    );
    let Some(row) = app.row_for_id(&director_row_id) else {
        return Vec::new();
    };
    vec![Cmd::OpenEmbedded {
        key: director_key,
        target: SessionToOpen {
            id: director_row_id,
            agent: row.agent,
            title: row.sentence_name(),
            cwd,
        },
        brigade: Some((
            brigade_id,
            DIRECTOR_TOKEN.to_string(),
            BrigadeRole::Director,
        )),
        model: None,
        effort: None,
        permission_mode: None,
        disallowed_tools: None,
        autocompact: None,
        first_prompt: None,
    }]
}

/// Note that `token` joined `brigade_id` now, after everyone already listed in
/// its join order. Called where the membership is *created* as the core sees
/// it, so where a member's tile goes never depends on when its pane happens to
/// appear (`apply_stack_order` learns an unlisted token on sight only as a
/// last resort).
fn record_join(state: &mut EmporiumState, brigade_id: BrigadeId, token: &str) {
    let joined = state.member_order.entry(brigade_id).or_default();
    if !joined.iter().any(|listed| listed == token) {
        joined.push(token.to_string());
    }
}

/// `Event::WorkerAdded`'s successful-addition payload, bundled so
/// [`update_worker_added`] doesn't tip into clippy's too-many-arguments —
/// these four always travel together anyway, all the way from
/// `StoreIntent::AddWorker`.
struct AddedWorker {
    brigade_id: BrigadeId,
    cwd: PathBuf,
    worker_agent: AgentKind,
    worker_model: String,
    worker_effort: String,
}

fn update_worker_added(
    state: &mut EmporiumState,
    brigade: &BrigadeConfig,
    added: AddedWorker,
    result: Result<MemberToken, String>,
    now: Instant,
) -> Vec<Cmd> {
    let AddedWorker {
        brigade_id,
        cwd,
        worker_agent,
        worker_model,
        worker_effort,
    } = added;
    match result {
        Ok(token) => {
            state.set_status(
                format!("{} added", state.member_call(Some(brigade_id), &token)),
                now,
            );
            record_join(state, brigade_id, &token);
            // The store's write was already in flight when a close was confirmed
            // (or a disband): a process started now would only be ended when it
            // landed. The member row stays, and a Worker with nothing to resume
            // is created afresh when the brigade is next opened.
            if !creation_still_wanted(state, brigade_id, &token) {
                return Vec::new();
            }
            open_worker(
                state,
                brigade_id,
                &token,
                &cwd,
                WorkerChoice {
                    agent: worker_agent,
                    model: &worker_model,
                    effort: &worker_effort,
                },
                RoleLaunch::of(BrigadeRole::Worker, worker_agent, brigade),
            )
        }
        Err(err) => {
            state.set_status(format!("failed to add worker: {err}"), now);
            Vec::new()
        }
    }
}

/// On success: kill every Worker and Goinkyo pane the brigade has hosted, staged
/// or not ([`EmporiumState::hosted_panes_of`], plus whatever the stage lists for
/// this brigade). Disband closes the whole cell; the Director's pane is the one
/// that stays if it is hosted, and an off-stage Worker left running would be
/// owned by a brigade that no longer exists. The stage is touched only when the
/// disbanded brigade is the one on it: it falls back to `Solo(director)`, or to
/// `Stage::Empty` (and the focus back on the sidebar) when no hosted Director is
/// known. A disband of a brigade that is off stage leaves what is showing, and
/// the focus, alone.
///
/// Who is killed is decided by each pane's own member token, not by knowing the
/// Director first: a pane whose token is a Worker's or the Goinkyo's cannot be
/// the Director, so killing it is never the wrong kill, and a Director whose
/// pane was ended alone earlier leaves its Workers hosted and still ending with
/// the brigade. A pane with no token, and the Director's, are spared. The
/// Director is needed only to say what the stage becomes: its pane is
/// `Stage::Brigade::director` when that is `Some` and still staged, or else the
/// one hosted pane that holds the Director's token in this brigade (none, or two,
/// is not known, and the stage empties). The kills never read that identity, and
/// the stage reads the same one the operator keeps open, so the two cannot
/// disagree about who stays. A pane whose open was still in flight is not hosted
/// yet: it is ended when its spawn is reported (`update_spawned`). The kills flow
/// through the same passive `PtyExited` fold as any other exit, which is also
/// when each pane's maps go; what those panes left queued goes at once
/// ([`drop_leftovers_of_ended_panes`]). The Goinkyo's own `NoGoinkyo` release a
/// tick later then names a pane this already closed, which is a no-op (see
/// [`EmporiumState::goinkyo_pane`]).
///
/// Every success also asks for a reload, whoever was staged: the members'
/// sessions come out of hiding here, and a Goinkyo's was archived in the same
/// write, which only a reload marks on its row.
fn update_disbanded(
    state: &mut EmporiumState,
    app: &mut App,
    brigade_id: BrigadeId,
    result: Result<(HashSet<String>, HashSet<String>), String>,
    now: Instant,
) -> Vec<Cmd> {
    match result {
        Ok((hidden, directors)) => {
            // The brigade's Goinkyo, if it had one, was archived in the write
            // that disbanded it, and its row is un-hidden here: the reload that
            // follows is what marks it, so it is never listed unmarked.
            let _ = app.set_hidden_member_ids(hidden);
            app.set_directors(directors);
            let staged = matches!(&state.stage, Stage::Brigade { id, .. } if *id == brigade_id);
            let (staged_director, staged_panes) = match &state.stage {
                Stage::Brigade {
                    id,
                    director,
                    panes,
                    ..
                } if *id == brigade_id => (
                    director.clone().filter(|d| panes.contains(d)),
                    panes.clone(),
                ),
                _ => (None, Vec::new()),
            };
            let hosted = state.hosted_panes_of(brigade_id);
            let hosted_directors: Vec<&SessionKey> = hosted
                .iter()
                .filter(|key| {
                    state.member_tokens.get(*key).map(String::as_str) == Some(DIRECTOR_TOKEN)
                })
                .collect();
            let known_director = staged_director
                .clone()
                .or_else(|| match hosted_directors[..] {
                    [only] => Some(only.clone()),
                    _ => None,
                });
            // By token, not by knowing the Director: see the doc. A staged pane
            // the maps do not place in this brigade is not this brigade's to end.
            let mut other_keys: Vec<SessionKey> = Vec::new();
            for key in staged_panes.iter().chain(hosted.iter()) {
                let is_member_worker = state.member_brigades.get(key) == Some(&brigade_id)
                    && state
                        .member_tokens
                        .get(key)
                        .is_some_and(|token| token != DIRECTOR_TOKEN);
                if is_member_worker && !other_keys.contains(key) {
                    other_keys.push(key.clone());
                }
            }
            if staged {
                state.stage = match &known_director {
                    Some(key) => Stage::Solo(key.clone()),
                    None => Stage::Empty,
                };
                state.settle_focus();
            }
            state.disbanding.insert(brigade_id);
            drop_leftovers_of_ended_panes(state, brigade_id, &other_keys);
            state.brigade_layouts.remove(&brigade_id);
            state.persisted_layouts.remove(&brigade_id);
            state.brigade_names.remove(&brigade_id);
            state.member_order.remove(&brigade_id);
            state.member_names.retain(|(id, _), _| *id != brigade_id);
            state.stated_names.retain(|(id, _), _| *id != brigade_id);
            state.member_facts.retain(|(id, _), _| *id != brigade_id);
            // The Director's pane stays open on its own and keeps the membership
            // maps it was staged with; the watch the brigade-quiet decision kept
            // for this brigade goes here, with the brigade (nothing observes it
            // any more, so it would be inert anyway).
            state.brigade_quiet.remove(&brigade_id);
            state.attention.remove(&brigade_id);
            state.requests.remove(&brigade_id);
            state.request_seen.remove(&brigade_id);
            state.request_answered.remove(&brigade_id);
            state.request_spent.remove(&brigade_id);
            state.set_status("brigade disbanded".to_string(), now);
            let mut cmds: Vec<Cmd> = other_keys
                .into_iter()
                .filter_map(|key| kill_pane(state, key))
                .collect();
            cmds.push(Cmd::Reload);
            cmds
        }
        Err(err) => {
            // The brigade lives on: its Workers ending are Workers ending again.
            state.disbanding.remove(&brigade_id);
            state.set_status(format!("failed to disband: {err}"), now);
            Vec::new()
        }
    }
}

/// Forget everything the core keeps under a dismissed member's token: what its
/// tile shows, its stated name, its place in the join order, and its layout
/// preferences (the store forgets the row's arrangement with the row, and the
/// solo naming it, so the persisted copy forgets it too: nothing is written for
/// a dismissal).
fn forget_dismissed_member(state: &mut EmporiumState, brigade_id: BrigadeId, token: &str) {
    state.member_facts.remove(&(brigade_id, token.to_string()));
    state.stated_names.remove(&(brigade_id, token.to_string()));
    state
        .held_relaunches
        .retain(|held| !(held.brigade_id == brigade_id && held.token == token));
    if let Some(joined) = state.member_order.get_mut(&brigade_id) {
        joined.retain(|listed| listed != token);
    }
    // Its name is free again for another member.
    state.resolve_member_names(brigade_id);
    for layout in [
        state.brigade_layouts.get_mut(&brigade_id),
        state.persisted_layouts.get_mut(&brigade_id),
    ]
    .into_iter()
    .flatten()
    {
        layout.row_weights.remove(token);
        layout.stack_order.retain(|ranked| ranked != token);
        layout.minimized.remove(token);
        if layout.solo_member.as_deref() == Some(token) {
            layout.solo_member = None;
        }
    }
}

/// The answer to [`StoreIntent::DismissExitedWorker`]. The pane is long gone
/// (`update_pty_exited` unstaged it), so only the member is left to deal with:
/// on success its state is forgotten as for any dismissal and the operator is
/// told it left; a store failure says so and leaves the member where it is, as
/// an operator's dismissal that failed does. A row that was already gone (`false`)
/// is forgotten silently — there is nothing to report.
fn update_exited_worker_dismissed(
    state: &mut EmporiumState,
    app: &mut App,
    brigade_id: BrigadeId,
    token: MemberToken,
    repeated: bool,
    result: Result<(bool, HashSet<String>, HashSet<String>), String>,
    now: Instant,
) -> Vec<Cmd> {
    state.removing_exited.remove(&(brigade_id, token.clone()));
    // Said as the operator knows the member, before its name is forgotten.
    let call = state.member_call(Some(brigade_id), &token);
    // Only for a Worker, which the store never archives, so this does not mark
    // anything itself; but the set it refreshes can release a Goinkyo that
    // `dismiss_goinkyo` ended from the other process (see
    // `Event::MemberSessionRecorded`).
    let mut reload = false;
    match result {
        Ok((removed, hidden, directors)) => {
            let released = app.set_hidden_member_ids(hidden);
            app.set_directors(directors);
            forget_dismissed_member(state, brigade_id, &token);
            reload = released;
            let failure = state.relaunch_failures.remove(&(brigade_id, token.clone()));
            if removed {
                if let Some(error) = failure {
                    state.set_status(
                        format!(
                            "{call} could not be restarted ({error}) \u{2014} removed from the brigade"
                        ),
                        now,
                    );
                } else {
                    let again = if repeated { " again" } else { "" };
                    state.set_status(
                        format!("{call} exited{again} \u{2014} removed from the brigade"),
                        now,
                    );
                }
            }
        }
        Err(err) => state.set_status(
            format!("{call} exited \u{2014} could not be removed from the brigade: {err}"),
            now,
        ),
    }
    reload_if(reload)
}

/// On success: remove just the dismissed Worker's pane — unlike
/// [`update_disbanded`], which clears every Worker at once, this touches
/// only the one the operator picked. `EmporiumState::pending_dismiss`
/// (stashed by [`confirm_kill_modal`] before this round trip was requested)
/// says which pane that is; taken here regardless of outcome so a failed or
/// foreign dismissal never leaves it stale for a later, unrelated
/// `WorkerDismissed`. The Director and any other Workers stay exactly as
/// staged; `Stage::remove` clamps `focused` the same way any other pane
/// removal does. The kill only fires if the pane was actually found staged
/// for this brigade — same "already gone, nothing to kill" tolerance as
/// [`update_disbanded`]. Every success also asks for a reload, staged or not,
/// for the reason [`update_disbanded`] gives: a dismissed Goinkyo's session was
/// archived by the write, and its row comes out of hiding here.
fn update_worker_dismissed(
    state: &mut EmporiumState,
    app: &mut App,
    brigade_id: BrigadeId,
    result: Result<(HashSet<String>, HashSet<String>), String>,
    now: Instant,
) -> Vec<Cmd> {
    let Some(key) = state.pending_dismiss.take() else {
        return Vec::new();
    };
    // Only a result for the brigade the dismissal was captured in may spend
    // the captured member. Another brigade's result touches neither the
    // entry nor that brigade's weights: its token can be spelled the same
    // (`worker-2` exists in every brigade).
    let member = match &state.pending_dismiss_member {
        Some((captured, _)) if *captured == brigade_id => {
            state.pending_dismiss_member.take().map(|(_, token)| token)
        }
        _ => None,
    };
    match result {
        Ok((hidden, directors)) => {
            // A dismissed Goinkyo's session was archived in the write that
            // removed its row, and the row is un-hidden here: the reload this
            // returns is what marks it, so it is never listed unmarked. A
            // Worker's session is not archived, and the same reload is how the
            // list picks it up as the ordinary row it now is.
            let _ = app.set_hidden_member_ids(hidden);
            app.set_directors(directors);
            // Forget everything kept under the dismissed member's token: its
            // layout preferences and what its tile shows. Only a dismissal
            // does this — a pane exiting, being relaunched or leaving the
            // stage keeps the member, and what is kept for it. (A Worker's token
            // is never reused in its brigade, so anything left would only pile up;
            // the Goinkyo's is reused by its next consultation, which would inherit
            // it.)
            if let Some(token) = member {
                forget_dismissed_member(state, brigade_id, &token);
            }
            let staged = matches!(
                &state.stage,
                Stage::Brigade { id, panes, .. } if *id == brigade_id && panes.contains(&key)
            );
            let title = app
                .row_for_id(key.as_str())
                .map(SessionRow::sentence_name)
                .unwrap_or_else(|| key.as_str().to_string());
            state.set_status(format!("{title} dismissed from the brigade"), now);
            if staged {
                let kill = kill_pane(state, key.clone());
                state.unstage(&key);
                kill.into_iter().chain([Cmd::Reload]).collect()
            } else {
                vec![Cmd::Reload]
            }
        }
        Err(err) => {
            state.set_status(format!("failed to dismiss worker: {err}"), now);
            Vec::new()
        }
    }
}

/// `Cmd::Reload` when `yes`, nothing otherwise.
fn reload_if(yes: bool) -> Vec<Cmd> {
    if yes { vec![Cmd::Reload] } else { Vec::new() }
}

/// The widest the quoted first line of a message may be in a status, in
/// display columns, ellipsis included.
const NUDGE_PROMPT_COLUMNS: usize = 60;

/// ` ← worker-3: first line of the message` for the nudge status — the sender
/// (by the name its Director gave it, when it has one) when it is known, the
/// line cut by display width. Empty when the message has no line to quote:
/// never an arrow with nothing after it.
fn nudge_prompt(state: &EmporiumState, brigade_id: BrigadeId, message: &MessageGlance) -> String {
    let Some(line) = display_name(&message.line) else {
        return String::new();
    };
    let line = shorten_to_columns(&line, NUDGE_PROMPT_COLUMNS);
    match &message.from_token {
        // banto's own record (an approval, a close) is no member: no name a Director
        // gave anyone is looked up for it, and it reads as banto's.
        Some(sender) if sender == BANTO_SENDER => format!(" \u{2190} {BANTO_SENDER}: {line}"),
        Some(sender) => format!(
            " \u{2190} {}: {line}",
            state.member_call(Some(brigade_id), sender)
        ),
        None => format!(" \u{2190} {line}"),
    }
}

/// The widest a brigade's name is allowed to be in a one-line status, in
/// display columns, ellipsis included.
const BRIGADE_NAME_COLUMNS: usize = 28;

/// What the tick decides about each `interrupt_worker` request it has not decided
/// yet, once and never again.
///
/// banto types nothing into a pane for an interrupt. A hosted Claude Worker with
/// the relay on carries a gate (a `PreToolUse` hook answered by its own `_mcp`)
/// that refuses its next tool calls until it reads the message, so the decision
/// here is only whether that gate is there to do it: `armed`, or one of the words
/// that say why not. The gate never reads the word, and the Worker's `_mcp`
/// writes `gated` and `capped` over `armed` itself.
///
/// What an armed request resets is the member's relay nudge state: a Worker whose
/// turn ends without a tool call is never refused anything, and the nudge that
/// wakes it must not wait out the cooldown of one sent before the Director's
/// message was written.
fn decide_interrupts(
    state: &mut EmporiumState,
    app: &App,
    config: &BrigadeConfig,
    relay: &[RelayObservation],
    requests: Vec<(BrigadeId, InterruptFact)>,
    now: Instant,
) -> Vec<Cmd> {
    let mut cmds = Vec::new();
    for (brigade_id, fact) in requests {
        if !fact.undecided || state.interrupt_decided.contains_key(&fact.message_id) {
            continue;
        }
        let member = (brigade_id, fact.member.clone());
        let obs = relay
            .iter()
            .find(|obs| obs.brigade_id == brigade_id && obs.token == fact.member);
        let (outcome, why) = judge_interrupt(state, config, brigade_id, &fact, obs);
        if outcome == InterruptOutcome::Armed {
            if let Some(relay_state) = state.relay_states.get_mut(&member) {
                relay_state.nudge = NudgeState::default();
            }
            let who = state.members_phrase(app, &[(Some(brigade_id), fact.member.clone())]);
            let prompt = interrupt_prompt(state, brigade_id, &fact.line);
            // "Got", not "was interrupted": nothing is interrupted until the gate has
            // refused a call, and a request seen again after a restart may be past
            // the point where it refuses anything.
            state.set_status(format!("relay: {who} got an interrupt{prompt}"), now);
        }
        state.interrupt_decided.insert(fact.message_id, brigade_id);
        cmds.push(Cmd::Store(StoreIntent::RecordInterruptOutcome {
            brigade_id,
            token: fact.member,
            message_id: fact.message_id,
            outcome,
            why,
        }));
    }
    cmds
}

/// The decision for one request, from the facts alone. See [`decide_interrupts`].
///
/// The first line that applies wins, in this order, and the order is the
/// contract (the values overlap, and a different order answers the same facts
/// differently):
///
/// 1. `read`: the Worker already has the message, whatever else is true now.
/// 2. `no-pane`: the brigade is closing, no pane is hosted for the member yet or
///    any more, or the pane has a hang-up queued.
/// 3. `relay-manual`: a Worker launched under a manual relay has no gate.
/// 4. `codex`: no gate for Codex; its message goes as ordinary mail.
/// 5. `no-pane` again, for a pane whose product is not known yet.
/// 6. `armed`: a Claude pane with the relay on.
fn judge_interrupt(
    state: &EmporiumState,
    config: &BrigadeConfig,
    brigade_id: BrigadeId,
    fact: &InterruptFact,
    obs: Option<&RelayObservation>,
) -> (InterruptOutcome, Option<InterruptWhy>) {
    use InterruptOutcome as Out;
    use InterruptWhy as Why;
    if fact.read {
        return (Out::Read, None);
    }
    if state.closing.contains_key(&brigade_id) {
        return (Out::NoPane, Some(Why::Closing));
    }
    let Some(obs) = obs else {
        // No observation: either the pane is open and has no session yet (the
        // observation needs one), or nothing hosts the member.
        let starting = state.member_tokens.iter().any(|(key, token)| {
            *token == fact.member && state.member_brigades.get(key) == Some(&brigade_id)
        });
        let why = if starting {
            Why::Starting
        } else {
            Why::NotRunning
        };
        return (Out::NoPane, Some(why));
    };
    if state.hangups.contains_key(&obs.key) {
        return (Out::NoPane, Some(Why::Ending));
    }
    if config.relay == RelayMode::Manual {
        return (Out::RelayManual, None);
    }
    match obs.agent {
        Some(AgentKind::Codex) => (Out::Codex, None),
        Some(AgentKind::ClaudeCode) => (Out::Armed, None),
        None => (Out::NoPane, Some(Why::Starting)),
    }
}

/// ` ← director: first line` for an interrupt notice, from the interrupt's own
/// first line. Not the member's newest message, which a later ordinary message of
/// the Director's would have replaced.
fn interrupt_prompt(state: &EmporiumState, brigade_id: BrigadeId, line: &str) -> String {
    let message = MessageGlance {
        created_at_ms: 0,
        line: line.to_string(),
        from_token: Some(DIRECTOR_TOKEN.to_string()),
    };
    nudge_prompt(state, brigade_id, &message)
}

/// One unread interrupt whose Worker is working, old enough to be told about.
struct UnreadInterrupt {
    message_id: i64,
    brigade_id: BrigadeId,
    member: MemberToken,
    age_ms: i64,
    word: Option<InterruptOutcome>,
    line: String,
}

/// What the unread notice remembers of an interrupt it has shown.
#[derive(Debug, Clone)]
struct ShownInterrupt {
    brigade_id: BrigadeId,
    member: MemberToken,
    last_shown: Instant,
}

/// What this tick's lists say about unread interrupts: the ones that the notice
/// applies to now, and, as a side effect, the `read` line owed for each one that
/// was shown and has since been read.
///
/// An interrupt applies when its Worker's pane was observed this tick as not idle
/// (`Some(false)`; an unknown reading says nothing) and the message is at least
/// [`UNREAD_INTERRUPT_NOTICE_AFTER_MS`] old. Whatever its word: the word says
/// what banto did for it, not whether the Worker is still going. A brigade whose
/// list could not be read is not in `lists`, and nothing is ended for it.
///
/// A shown interrupt that left its list was read when its Worker is still on the
/// roster; one whose Worker was dismissed is dropped without a word. Either way
/// the id is forgotten.
fn track_unread_interrupts(
    state: &mut EmporiumState,
    app: &App,
    relay: &[RelayObservation],
    lists: &[(BrigadeId, Vec<InterruptFact>, Vec<MemberToken>)],
) -> Vec<UnreadInterrupt> {
    let mut applies = Vec::new();
    for (brigade_id, facts, roster) in lists {
        let mut left: Vec<i64> = state
            .unread_interrupts_shown
            .iter()
            .filter(|(id, shown)| {
                shown.brigade_id == *brigade_id
                    && !facts.iter().any(|f| f.message_id == **id && !f.read)
            })
            .map(|(id, _)| *id)
            .collect();
        left.sort_unstable();
        for id in left {
            let Some(shown) = state.unread_interrupts_shown.remove(&id) else {
                continue;
            };
            if roster.contains(&shown.member) {
                let who = state.members_phrase(app, &[(Some(*brigade_id), shown.member.clone())]);
                state
                    .interrupt_read_notices
                    .push_back(format!("relay: {who} read the interrupt"));
            }
        }
        for fact in facts {
            let working = relay.iter().any(|obs| {
                obs.brigade_id == *brigade_id
                    && obs.token == fact.member
                    && obs.is_idle_this_tick == Some(false)
            });
            if !fact.read && working && fact.age_ms >= UNREAD_INTERRUPT_NOTICE_AFTER_MS {
                applies.push(UnreadInterrupt {
                    message_id: fact.message_id,
                    brigade_id: *brigade_id,
                    member: fact.member.clone(),
                    age_ms: fact.age_ms,
                    word: fact.word,
                    line: fact.line.clone(),
                });
            }
        }
    }
    applies
}

/// `45s`, `2m`, `1h 5m`: the age as the notice tells it. Truncated, never rounded
/// up, so it never claims a wait longer than the one measured.
fn unread_age(ms: i64) -> String {
    let seconds = ms.max(0) / 1000;
    match seconds {
        0..60 => format!("{seconds}s"),
        60..3600 => format!("{}m", seconds / 60),
        _ => match seconds % 3600 / 60 {
            0 => format!("{}h", seconds / 3600),
            minutes => format!("{}h {minutes}m", seconds / 3600),
        },
    }
}

/// The notice that an interrupt sits unread while its Worker works, as a status
/// line: one interrupt per showing, a different one each time while several
/// apply (the one never shown first, then the one shown longest ago, oldest
/// message first among equals). The age is as of the tick that shows it, so it
/// advances with every showing.
///
/// The tail says what is true of this word and claims nothing more: `armed` and
/// no word say the Worker has called no tool, which holds because the gate would
/// have refused one (and would have written `gated`); a pane that was not there
/// when the request was decided says nothing about tools. No key is named: the
/// operator's own keys are their business.
fn say_unread_interrupt(
    state: &mut EmporiumState,
    app: &App,
    applies: &[UnreadInterrupt],
    now: Instant,
) {
    if !state
        .unread_interrupt_reminder
        .due(!applies.is_empty(), state.status.is_none(), now)
    {
        return;
    }
    let Some(pick) = applies.iter().min_by_key(|unread| {
        let last_shown = state
            .unread_interrupts_shown
            .get(&unread.message_id)
            .map(|shown| shown.last_shown);
        (
            last_shown,
            std::cmp::Reverse(unread.age_ms),
            unread.message_id,
        )
    }) else {
        return;
    };
    use InterruptOutcome as Out;
    let tail = match pick.word {
        None | Some(Out::Armed) => ", no tool call since",
        Some(Out::Gated) => ", a tool call was refused",
        Some(Out::Capped) => ", went on past the refusals",
        Some(Out::Codex) => ", a Codex turn cannot be interrupted",
        Some(Out::RelayManual) => ", relay is manual",
        Some(Out::NoPane | Out::Read) => "",
    };
    let who = state.members_phrase(app, &[(Some(pick.brigade_id), pick.member.clone())]);
    let prompt = interrupt_prompt(state, pick.brigade_id, &pick.line);
    let age = unread_age(pick.age_ms);
    state.unread_interrupts_shown.insert(
        pick.message_id,
        ShownInterrupt {
            brigade_id: pick.brigade_id,
            member: pick.member.clone(),
            last_shown: now,
        },
    );
    state.set_status(
        format!("relay: {who}: interrupt unread for {age}{tail}{prompt}"),
        now,
    );
}

fn update_tick(
    state: &mut EmporiumState,
    app: &App,
    brigade: &BrigadeConfig,
    relay: Vec<RelayObservation>,
    brigades: Vec<BrigadeNameFacts>,
    now: Instant,
) -> Vec<Cmd> {
    let mut cmds = Vec::new();

    // A refused session move is latched per pane so that it is said once; the
    // latch goes with its pane, not only when another refusal comes along.
    let screens = &state.screens;
    state
        .refused_session_moves
        .retain(|(key, _)| screens.contains_key(key));

    cmds.extend(give_up_on_codex_catalog(state, now));

    match state.sweep_due {
        None => state.sweep_due = Some(now + DATA_DIR_FIRST_SWEEP_DELAY),
        Some(due) if now >= due => {
            state.sweep_due = Some(now + DATA_DIR_SWEEP_INTERVAL);
            cmds.push(Cmd::SweepDataDir);
        }
        Some(_) => {}
    }

    // First, so the statuses below name each brigade by what this very tick
    // read. A brigade the tick does not list keeps its last facts (a failed
    // gather reads nothing and must not blank every name).
    let mut interrupt_requests: Vec<(BrigadeId, InterruptFact)> = Vec::new();
    // The lists that were read, for the unread notice: `None` is a list that could
    // not be, which says nothing about any interrupt.
    let mut interrupt_lists: Vec<(BrigadeId, Vec<InterruptFact>, Vec<MemberToken>)> = Vec::new();
    for mut facts in brigades {
        // The member names are the roster's truth as of this read: they replace
        // what events have stated for the brigade and are resolved as a roster
        // (first joiner keeps a duplicated name). Nothing is written back.
        let names = std::mem::take(&mut facts.member_names);
        state.replace_member_names(facts.brigade_id, names);
        let request = facts.request.take();
        let brigade_id = facts.brigade_id;
        // A request the store no longer lists has its outcome recorded (or its
        // member gone): what this run remembered of it can go. A list that could
        // not be read says nothing about any request, so nothing is forgotten.
        let interrupts = std::mem::take(&mut facts.interrupts);
        if let Some(listed) = &interrupts {
            state.interrupt_decided.retain(|id, owner| {
                *owner != brigade_id || listed.iter().any(|f| f.message_id == *id)
            });
        }
        let roster = std::mem::take(&mut facts.roster);
        if let Some(listed) = &interrupts {
            interrupt_lists.push((brigade_id, listed.clone(), roster));
        }
        interrupt_requests.extend(
            interrupts
                .into_iter()
                .flatten()
                .map(|fact| (brigade_id, fact)),
        );
        state.brigade_names.insert(brigade_id, facts);
        cmds.extend(apply_request_fact(
            state, app, brigade, brigade_id, request, now,
        ));
    }

    // What each observed member's collapsed tile shows. A member the shell did
    // not re-read (`glance: None`) keeps what it had; an agent the shell
    // could not resolve this tick does not erase one it could before.
    // What the bell may know this tick: exactly what was observed in it.
    let observed = TickObservations::from_relay(&relay, state);
    // What a member's live file said is only what THIS tick saw: a member the
    // tick did not observe (a roster that could not be read, a member without a
    // session yet) has no word until one is seen, rather than the last one.
    for facts in state.member_facts.values_mut() {
        facts.live = None;
    }
    for observation in &relay {
        let facts = state
            .member_facts
            .entry((observation.brigade_id, observation.token.clone()))
            .or_default();
        facts.live = observation.live;
        if observation.agent.is_some() {
            facts.agent = observation.agent;
        }
        if let Some(MemberGlance { inbound, sent }) = &observation.glance {
            facts.inbound = inbound.clone();
            facts.sent = sent.clone();
        }
    }

    // Members banto started with a first prompt: confirmed, or told about, from
    // what this tick observed.
    update_first_turn_watch(state, app, &relay, now);

    // Before the relay below: the nudge state a new interrupt resets is the one
    // the relay then reads.
    cmds.extend(decide_interrupts(
        state,
        app,
        brigade,
        &relay,
        interrupt_requests,
        now,
    ));

    // Before the relay below consumes the observations, and whether or not the
    // relay is on: what the unread interrupts say comes from what this tick saw.
    let unread_interrupts = track_unread_interrupts(state, app, &relay, &interrupt_lists);

    // Before the relay below consumes the observations: a notice about a member
    // that was never briefed does not depend on the relay being on.
    say_unbriefed_codex_members(state, app, &relay, now);

    // Before the relay below, and whether or not the relay is on: a wake whose
    // answer never came is given up on by the clock, not by an observation.
    age_member_wakes(state, now);
    if brigade.relay == RelayMode::Auto {
        for obs in relay {
            // A pane of a brigade being closed is not woken or read.
            if state.closing.contains_key(&obs.brigade_id) {
                continue;
            }
            // Codex wakes use its queue.
            if obs.agent == Some(AgentKind::Codex) {
                wake_codex_member(state, app, &obs, now, &mut cmds);
                continue;
            }
            let member = (obs.brigade_id, obs.token.clone());
            let idle_this_tick = if state.first_turn_watch.contains_key(&obs.key) {
                Some(false)
            } else {
                obs.is_idle_this_tick
            };
            if !obs.has_unseen {
                state.member_wakes.remove(&member);
            } else if let Some(wake) = state.member_wakes.get_mut(&member) {
                match wake.phase {
                    WakePhase::Issued { .. }
                    | WakePhase::Held {
                        cause: HoldCause::ClaudeNotTaken,
                        ..
                    } if !obs.wake_pending => wake.phase = WakePhase::Free,
                    _ => {}
                }
            }
            let free = state
                .member_wakes
                .get(&member)
                .is_none_or(|wake| matches!(wake.phase, WakePhase::Free));
            let previous_nudge = state
                .relay_states
                .get(&member)
                .map_or_else(NudgeState::default, |s| s.nudge);
            let nudge = tick_relay_decision(
                &mut state.relay_states,
                obs.brigade_id,
                &obs.token,
                now,
                idle_this_tick,
                free,
                obs.has_unseen,
            );
            if nudge {
                state.relay_states.get_mut(&member).unwrap().nudge = previous_nudge;
                state.member_wakes.entry(member.clone()).or_default().phase = WakePhase::Issuing {
                    key: obs.key.clone(),
                };
                cmds.push(Cmd::Store(StoreIntent::IssueWake {
                    brigade_id: obs.brigade_id,
                    token: obs.token.clone(),
                }));
                let member =
                    state.members_phrase(app, &[(Some(obs.brigade_id), obs.token.clone())]);
                // What prompted it: the newest message to this member, as
                // applied from this very tick's observation above.
                let prompt = state
                    .member_facts
                    .get(&(obs.brigade_id, obs.token.clone()))
                    .and_then(|facts| facts.inbound.as_ref())
                    .map(|inbound| nudge_prompt(state, obs.brigade_id, inbound))
                    .unwrap_or_default();
                state.set_status(format!("relay: nudged {member}{prompt}"), now);
            }
        }
    }

    if let Some(set_at) = state.status_set_at
        && now.saturating_duration_since(set_at) >= STATUS_TIMEOUT
    {
        state.status = None;
        state.status_set_at = None;
    }

    // After the expiry above, so a notice that just ran out is followed by the
    // next one on this very tick; before the reminders below, which wait for a
    // free line, so a one-time notice is not queued behind a recurring one.
    show_next_startup_notice(state, now);
    if state.status.is_none()
        && let Some(notice) = state.interrupt_read_notices.pop_front()
    {
        state.set_status(notice, now);
    }

    say_unread_interrupt(state, app, &unread_interrupts, now);

    say_member_holds(state, app, now);

    if let Some(armed_at) = state.prefix_armed
        && now.saturating_duration_since(armed_at) >= PREFIX_ARM_TIMEOUT
    {
        state.prefix_armed = None;
    }

    // A brigade is not called quiet in the second its relay wakes a member.
    cmds.extend(update_brigade_quiet(
        state,
        app,
        now,
        brigade.relay == RelayMode::Auto,
        &observed,
    ));

    cmds
}

/// One tick of a Codex member's wake: judge the one that is out, and send a
/// new one when the member is due.
///
/// A wake goes through the member's queue (`Cmd::QueueCodexMessage`) and is
/// judged only by what the member does, read from the observation's own idle
/// reading, never from the one the Claude path adjusts for a line banto has in
/// flight: banto reading its own not-idle as the member's would call every wake
/// received.
///
/// - Received: inside the window the member reads not idle (a turn of the
///   operator's does too: what is queued runs after it), or the unread mail is
///   gone.
/// - Not received: still idle when the window ends. The member is held, once and
///   without a resend, because sending again is exactly how a message is
///   delivered twice; only the member doing something releases it.
///
/// A second wake for mail the first did not clear waits a window of unbroken
/// idle as well as the cooldown and the attempt cap the relay always had, and
/// the first needs the usual two idle ticks. No part of a Codex pane is read
/// and no key sent; the first-turn watch also applies to Claude wakes.
fn wake_codex_member(
    state: &mut EmporiumState,
    app: &App,
    obs: &RelayObservation,
    now: Instant,
    cmds: &mut Vec<Cmd>,
) {
    let member = (obs.brigade_id, obs.token.clone());
    if !obs.has_unseen {
        state.member_wakes.remove(&member);
        state.relay_states.remove(&member);
        return;
    }
    let reading = obs.is_idle_this_tick;
    let attempts = state
        .relay_states
        .get(&member)
        .map_or(0, |relay| relay.nudge.attempts);
    // Idle counts neither toward a wake nor toward judging one not taken up while
    // the process is still loading what an earlier wake queued (a pane reopened
    // inside a window is judged by the new process, not by the clock that ran
    // out meanwhile), or while the first prompt banto gave the member is not yet
    // a turn: the member reads idle through both and is about to be busy.
    let not_counted = !state.past_codex_wake_guard(&obs.key, now)
        || state.first_turn_watch.contains_key(&obs.key);
    let counted_idle = if not_counted { Some(false) } else { reading };
    let wake = state.member_wakes.entry(member.clone()).or_default();
    wake.idle_since = match reading {
        Some(true) => Some(wake.idle_since.unwrap_or(now)),
        _ => None,
    };
    match wake.phase {
        WakePhase::Watching { since } => {
            if reading == Some(false) {
                wake.phase = WakePhase::Free;
            } else if !not_counted && now.saturating_duration_since(since) >= CODEX_WAKE_WINDOW {
                // Held for want of evidence, not for evidence of idleness: a
                // reading that cannot be taken (`None`) shows no turn either, and
                // the window is the whole of what a message is given.
                wake.phase = WakePhase::Held {
                    since: now,
                    cause: HoldCause::NotTakenUp,
                    told: false,
                };
            }
        }
        // Strictly after: a hold that began on this very tick has not been seen
        // past.
        WakePhase::Held { since, .. } if reading == Some(false) && since < now => {
            wake.phase = WakePhase::Free;
        }
        _ => {}
    }
    let free = matches!(wake.phase, WakePhase::Free);
    let window_idle = wake
        .idle_since
        .is_some_and(|at| now.saturating_duration_since(at) >= CODEX_WAKE_WINDOW);
    let may_wake = free && (attempts == 0 || window_idle) && !obs.key.is_synthetic();
    if !tick_codex_wake_decision(
        &mut state.relay_states,
        obs.brigade_id,
        &obs.token,
        now,
        counted_idle,
        may_wake,
    ) {
        return;
    }
    let session_id = obs.key.as_str().to_string();
    state.last_prompted.insert(obs.key.clone(), now);
    if let Some(wake) = state.member_wakes.get_mut(&member) {
        wake.phase = WakePhase::Asking {
            session_id: session_id.clone(),
            since: now,
        };
    }
    cmds.push(Cmd::QueueCodexMessage {
        key: obs.key.clone(),
        session_id,
        message: RELAY_NUDGE_LINE.to_string(),
    });
    let who = state.members_phrase(app, &[(Some(obs.brigade_id), obs.token.clone())]);
    // What prompted it: the newest message to this member, as applied from this
    // very tick's observation.
    let prompt = state
        .member_facts
        .get(&member)
        .and_then(|facts| facts.inbound.as_ref())
        .map(|inbound| nudge_prompt(state, obs.brigade_id, inbound))
        .unwrap_or_default();
    state.set_status(format!("relay: nudged {who}{prompt}"), now);
}

/// [`tick_relay_decision`] for a member woken through its queue: the same idle
/// streak, cooldown and attempt cap, and `may_wake` for what only the wake's own state knows. The streak is counted whether or not a wake may go out.
fn tick_codex_wake_decision(
    states: &mut HashMap<(BrigadeId, MemberToken), RelayState>,
    brigade_id: BrigadeId,
    token: &MemberToken,
    now: Instant,
    idle: Option<bool>,
    may_wake: bool,
) -> bool {
    let state = states.entry((brigade_id, token.clone())).or_default();
    state.idle_streak = if idle == Some(true) {
        state.idle_streak + 1
    } else {
        0
    };
    let wake = may_wake && should_nudge(now, state.idle_streak, true, &state.nudge);
    if wake {
        state.nudge.last_nudge = Some(now);
        state.nudge.attempts += 1;
    }
    wake
}

/// Hold wakes that have waited too long, even without a member observation.
fn age_member_wakes(state: &mut EmporiumState, now: Instant) {
    for wake in state.member_wakes.values_mut() {
        if let WakePhase::Issued { since } = wake.phase
            && now.saturating_duration_since(since) >= Duration::from_secs(10)
        {
            wake.phase = WakePhase::Held {
                since: now,
                cause: HoldCause::ClaudeNotTaken,
                told: false,
            };
        }
        if let WakePhase::Asking { since, .. } = wake.phase
            && now.saturating_duration_since(since) >= CODEX_QUEUE_ANSWER_GIVE_UP
        {
            wake.phase = WakePhase::Held {
                since: now,
                cause: HoldCause::NoAnswer,
                told: false,
            };
        }
    }
}

/// What `codex queue` came to for the member whose wake `session_id` names.
///
/// Only a non-zero exit is a wake known not to have been queued (measured: a
/// refused queue queues nothing), so only that one is free to go out again, under
/// the cooldown and the cap. A timeout kill and output banto does not recognise
/// may have queued it, and a missing `codex` cannot be helped by trying again:
/// those are held, and the operator is told. An answer for a member that has no
/// wake out (it was unstaged, or the wake was given up on) is ignored.
fn update_codex_message_queued(
    state: &mut EmporiumState,
    app: &App,
    session_id: &str,
    result: crate::codex_queue::CodexQueueResult,
    now: Instant,
) -> Vec<Cmd> {
    use crate::codex_queue::CodexQueueResult;
    let Some(member) = state.member_wakes.iter().find_map(|(member, wake)| {
        matches!(&wake.phase, WakePhase::Asking { session_id: asked, .. } if asked == session_id)
            .then(|| member.clone())
    }) else {
        return Vec::new();
    };
    let held = |cause| WakePhase::Held {
        since: now,
        cause,
        told: false,
    };
    let phase = match result {
        CodexQueueResult::Queued { .. } => WakePhase::Watching { since: now },
        CodexQueueResult::Failed {
            exit_code: Some(code),
            summary,
        } => {
            let who = state.members_phrase(app, &[(Some(member.0), member.1.clone())]);
            state.set_status(
                format!("relay: `codex queue` for {who} failed (exit {code}): {summary}"),
                now,
            );
            WakePhase::Free
        }
        CodexQueueResult::Failed {
            exit_code: None, ..
        } => held(HoldCause::TimedOut),
        CodexQueueResult::NotLaunched { reason } => held(HoldCause::NotLaunched(reason)),
        CodexQueueResult::UnexpectedOutput { .. } => held(HoldCause::Unrecognised),
    };
    if let Some(wake) = state.member_wakes.get_mut(&member) {
        wake.phase = phase;
    }
    Vec::new()
}

/// Where a member stands in its brigade's roster, which the store orders
/// `director`, then the Workers by number: the rank to say things in, since the
/// wakes live in a map with no order of its own. Compared as text `worker-10`
/// would come before `worker-2`.
fn roster_rank(member: &(BrigadeId, MemberToken)) -> (BrigadeId, u8, u64, MemberToken) {
    let (brigade_id, token) = member;
    let (class, number) = if token == DIRECTOR_TOKEN {
        (0, 0)
    } else if let Some(number) = token
        .strip_prefix("worker-")
        .and_then(|digits| digits.parse().ok())
    {
        (1, number)
    } else {
        (2, 0)
    };
    (*brigade_id, class, number, token.clone())
}

/// Tell the operator, once and into a free status line, about a member whose
/// wake is held. One member a tick, in roster order; a member left due stays
/// due until the line is free.
///
/// The text states what was seen and no cause: a wake that was accepted and not
/// taken up can have several causes, and the operator is the one who can look.
fn say_member_holds(state: &mut EmporiumState, app: &App, now: Instant) {
    if state.status.is_some() {
        return;
    }
    let Some((member, cause)) = state
        .member_wakes
        .iter()
        .filter_map(|(member, wake)| match &wake.phase {
            WakePhase::Held {
                told: false, cause, ..
            } => Some((member.clone(), cause.clone())),
            _ => None,
        })
        .min_by_key(|(member, _)| roster_rank(member))
    else {
        return;
    };
    let who = state.members_phrase(app, &[(Some(member.0), member.1.clone())]);
    let look = "look at its pane, answer what it shows, or type it a word";
    let text = match cause {
        HoldCause::ClaudeNotTaken => {
            format!("relay: {who} did not take the wake — tell it to check its messages")
        }
        HoldCause::NotTakenUp => format!("relay: woke {who} but nothing happened \u{2014} {look}"),
        HoldCause::TimedOut => format!(
            "relay: `codex queue` for {who} timed out, so the wake may or may not be queued \u{2014} {look}"
        ),
        HoldCause::NoAnswer => {
            format!("relay: no answer came for the wake of {who} \u{2014} {look}")
        }
        HoldCause::NotLaunched(reason) => format!(
            "relay: could not run `codex queue` for {who} ({reason}); nothing was sent \u{2014} {look}"
        ),
        HoldCause::Unrecognised => format!(
            "relay: `codex queue` for {who} printed something banto does not recognise, so the wake may or may not be queued \u{2014} {look}"
        ),
    };
    state.set_status(text, now);
    if let Some(WakePhase::Held { told, .. }) = state
        .member_wakes
        .get_mut(&member)
        .map(|wake| &mut wake.phase)
    {
        *told = true;
    }
}

/// Say, once per launch, that a hosted Codex member ran a turn and was never
/// briefed.
///
/// A Codex member is briefed by banto's own `SessionStart` hook, which Codex
/// runs only if it trusts the hook, and which fires at the member's first typed
/// turn rather than at launch (`docs/REQUIREMENTS.md`, "Delivered once, not on
/// every resume"). A hook Codex does not run fails without a word anywhere, and
/// trust can be lost without the operator doing anything: it is keyed by the
/// executable's path, and banto can run from two. So the one place the failure
/// shows is the row the hook would have written: a briefing recorded no later
/// than the launch ([`RelayObservation::briefed_since_launch`]) once a turn is
/// known to have run.
///
/// A turn is known by the pane's own report, latched in
/// [`EmporiumState::codex_turn_ran`]. An interrupted turn can end in neither
/// `done` nor `error`, so the notice may come late, never early. It is decided
/// from a latch an earlier tick set: the tick that sees `done` has a roster read
/// that may be older than the hook's write, and a turn short enough to end in
/// the same second the hook ran would otherwise be called unbriefed.
///
/// Said only when the status line is free, and marked said only then, so a busy
/// line delays it instead of losing it. Every member that qualifies in the tick
/// is named in the one message.
fn say_unbriefed_codex_members(
    state: &mut EmporiumState,
    app: &App,
    relay: &[RelayObservation],
    now: Instant,
) {
    let mut latch = Vec::new();
    let mut unbriefed: Vec<(SessionKey, Option<BrigadeId>, MemberToken)> = Vec::new();
    for observation in relay {
        if observation.agent != Some(AgentKind::Codex) {
            continue;
        }
        let Some(screen) = state.screens.get(&observation.key) else {
            continue;
        };
        if matches!(
            screen.reported_state(),
            Some(ReportedState::Done | ReportedState::Error)
        ) {
            latch.push(observation.key.clone());
        }
        if state.codex_turn_ran.contains(&observation.key)
            && observation.briefed_since_launch == Some(false)
            && !state.unbriefed_told.contains(&observation.key)
        {
            unbriefed.push((
                observation.key.clone(),
                Some(observation.brigade_id),
                observation.token.clone(),
            ));
        }
    }
    state.codex_turn_ran.extend(latch);
    if unbriefed.is_empty() || state.status.is_some() {
        return;
    }
    let members: Vec<(Option<BrigadeId>, MemberToken)> = unbriefed
        .iter()
        .map(|(_, brigade_id, token)| (*brigade_id, token.clone()))
        .collect();
    let phrase = state.members_phrase(app, &members);
    state
        .unbriefed_told
        .extend(unbriefed.into_iter().map(|(key, ..)| key));
    state.set_status(
        format!(
            "codex: no briefing reached {phrase} — banto's hook did not run, most likely because Codex does not trust it (Codex trusts one banto.exe path at a time)"
        ),
        now,
    );
}

/// Follow the members banto gave a first prompt ([`FirstTurnWatch`]): drop the
/// ones whose first turn is confirmed, and say once, after
/// [`FIRST_TURN_NOTICE_AFTER`], that one did not start. Writes nothing into any
/// pane: the prompt is on the command line, so there is no line to retry, only a
/// member to report.
///
/// A Claude Goinkyo is confirmed here, by its session row having a first user
/// message or by this tick's live file reading `busy`; not by merely not being
/// idle, which a `waiting` is as well. A Codex pane is confirmed in
/// [`update_discovery_result`].
///
/// The notice says what the pane let banto see, and is held back while a Codex
/// pane reports `working` (see the comment below). A Codex pane whose own report
/// has shown `done` or `error` ([`EmporiumState::codex_turn_ran`]) took a turn
/// and was not identified, and banto's hook not having run is the likely reason:
/// a Codex Worker's only discovery source is that hook. Latched here for a pane
/// in the watch because [`say_unbriefed_codex_members`] latches only the members
/// the relay observes, which are those with a session. Anything else is a member
/// that did nothing with its prompt, most likely stopped at a dialog that prints
/// nothing while it waits.
fn update_first_turn_watch(
    state: &mut EmporiumState,
    app: &App,
    relay: &[RelayObservation],
    now: Instant,
) {
    let mut confirmed = Vec::new();
    let mut ran = Vec::new();
    for (key, watch) in &state.first_turn_watch {
        match watch.agent {
            AgentKind::ClaudeCode => {
                let spoken_to = app.row_for_id(key.as_str()).is_some_and(|row| {
                    row.preview.as_deref().is_some_and(|p| !p.trim().is_empty())
                });
                let busy = relay
                    .iter()
                    .any(|obs| &obs.key == key && obs.live.is_some_and(|live| live.status_busy));
                if spoken_to || busy {
                    confirmed.push(key.clone());
                }
            }
            AgentKind::Codex => {
                if state.screens.get(key).is_some_and(|screen| {
                    matches!(
                        screen.reported_state(),
                        Some(ReportedState::Done | ReportedState::Error)
                    )
                }) {
                    ran.push(key.clone());
                }
            }
        }
    }
    for key in confirmed {
        state.first_turn_watch.remove(&key);
    }
    state.codex_turn_ran.extend(ran);

    let mut due: Vec<(Instant, SessionKey, bool)> = Vec::new();
    for (key, watch) in &state.first_turn_watch {
        let Some(started) = state.process_started.get(key) else {
            continue;
        };
        if now.saturating_duration_since(*started) < FIRST_TURN_NOTICE_AFTER || watch.told {
            continue;
        }
        let turn_ran = state.codex_turn_ran.contains(key);
        // A turn is under way: say nothing yet, and keep the notice for when
        // it ends, which will be the one that fits (`done` or `error` is
        // latched above, and a pane still unidentified then is told so).
        // Codex prints no report at all while a first-run dialog waits, and
        // reports `working` as its first turn starts, 1-2 s after launch
        // (measured with a positional prompt), so a `working` after
        // [`FIRST_TURN_NOTICE_AFTER`] is not a pane stopped at a dialog. That
        // is the only thing `working` is read for: it never ends the watch,
        // because it is reported while Codex starts up too.
        if !turn_ran
            && watch.agent == AgentKind::Codex
            && state
                .screens
                .get(key)
                .is_some_and(|screen| screen.reported_state() == Some(ReportedState::Working))
        {
            continue;
        }
        due.push((*started, key.clone(), turn_ran));
    }
    // The watch is a HashMap, whose order changes from run to run, and a tick
    // says one notice. The member launched first is told about first, the key
    // breaking a tie, so the order is the same on every run.
    due.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.as_str().cmp(b.1.as_str())));
    // One line each, so that a status already on the line is not overwritten by
    // a second notice of the same tick: the one left over stays due.
    for (_, key, turn_ran) in due {
        if state.status.is_some() {
            break;
        }
        let name = state.pane_label(app, &key);
        let text = if turn_ran {
            format!(
                "{name}: took its first turn but was not identified — banto's hook did not run, most likely because Codex does not trust it"
            )
        } else {
            format!(
                "{name}: its first prompt started no turn {}s after launch — answer what the pane shows, or type its first line yourself",
                FIRST_TURN_NOTICE_AFTER.as_secs()
            )
        };
        if let Some(watch) = state.first_turn_watch.get_mut(&key) {
            watch.told = true;
        }
        state.set_status(text, now);
    }
}

/// Lets go of everything banto holds for `brigade_id`'s Planner once its Plan is
/// closed: the roster entry, its facts, the one-shot guard, and the pane, ended
/// wherever it is. The reload is asked for when anything was held, because closing
/// the Plan archived the Planner's session and the hidden set is read once.
fn release_planner(state: &mut EmporiumState, brigade_id: BrigadeId) -> Vec<Cmd> {
    let was_member = state
        .member_order
        .get_mut(&brigade_id)
        .is_some_and(|joined| {
            let before = joined.len();
            joined.retain(|listed| listed != PLANNER_TOKEN);
            joined.len() != before
        });
    state
        .member_facts
        .remove(&(brigade_id, PLANNER_TOKEN.to_string()));
    let Some(key) = state.planner_pane.remove(&brigade_id) else {
        return if was_member {
            vec![Cmd::Reload]
        } else {
            Vec::new()
        };
    };
    // Unstaging applies only to a pane that is on stage; ending it applies either
    // way, as for the Goinkyo's (`update_goinkyo_awaiting_spawn`).
    let staged = matches!(
        &state.stage,
        Stage::Brigade { id, panes, .. } if *id == brigade_id && panes.contains(&key)
    );
    let kill = kill_pane(state, key.clone());
    if staged {
        state.unstage(&key);
    }
    kill.into_iter().chain([Cmd::Reload]).collect()
}

/// Answers [`Event::PlannerClosed`]. An operator's close ends the pane at once
/// (the next tick's `NoPlanner` would, a second later) and says what happened. A
/// disband's pane was ended by [`update_disbanded`] already, so only a failed export
/// is worth a line.
fn update_planner_closed(
    state: &mut EmporiumState,
    brigade_id: BrigadeId,
    result: Result<Option<PlanCloseReport>, String>,
    now: Instant,
) -> Vec<Cmd> {
    match result {
        Err(error) => {
            state.set_status(format!("could not close the Plan: {error}"), now);
            Vec::new()
        }
        Ok(None) => {
            state.set_status("the brigade has no open Plan to close", now);
            Vec::new()
        }
        Ok(Some(report)) => {
            let cmds = match report.cause {
                PlanCloseCause::Operator => release_planner(state, brigade_id),
                PlanCloseCause::Disband => Vec::new(),
            };
            if let Some(line) = report.status_line() {
                let line = match (report.cause, state.status.take()) {
                    (PlanCloseCause::Disband, Some(earlier)) => format!("{earlier}; {line}"),
                    _ => line,
                };
                state.set_status(line, now);
            }
            cmds
        }
    }
}

/// Answers `Event::PlannerObserved`: start the Planner the observation names, at
/// most once until the brigade is staged again, and release whatever is left of
/// one whose row is gone.
///
/// It is [`update_goinkyo_awaiting_spawn`]'s shape, and its guard
/// ([`EmporiumState::planner_pane`]) is read the same way: a synthetic key is a
/// launch in flight or one that failed, so it is not retried; a real key beside a
/// row with no session id is a pane of a Plan that ended and was replaced, which is
/// torn down rather than adopted. Three things differ, all because a Planner
/// outlives its panes. There is no Codex path, since the Planner is Claude's alone.
/// The `NoPlanner` arm is how the UI learns of a Plan closed by another process (the
/// Director's `close_planner` or `release_plan`), and it also reloads when the
/// roster still listed the Planner, because closing the Plan archived its session
/// and the hidden set is read once. And nothing here removes the row: a Planner
/// that cannot start keeps its row and its Plan, and says so through
/// `brigade_status`, because the Plan is the operator's and a failed process must
/// not be what ends it.
fn update_planner_observed(
    state: &mut EmporiumState,
    brigade: &BrigadeConfig,
    observation: PlannerObservation,
) -> Vec<Cmd> {
    let candidate = match observation {
        PlannerObservation::NoPlanner { brigade_id } => {
            return release_planner(state, brigade_id);
        }
        // A brigade being closed is not running: its Planner starts, like any
        // member without a session, when the brigade is opened again.
        PlannerObservation::AwaitingSpawn(candidate)
            if state.closing.contains_key(&candidate.brigade_id) =>
        {
            return Vec::new();
        }
        PlannerObservation::AwaitingSpawn(candidate) => candidate,
    };
    if candidate.roster.is_empty() {
        record_join(state, candidate.brigade_id, PLANNER_TOKEN);
    } else {
        state
            .member_order
            .insert(candidate.brigade_id, candidate.roster.clone());
    }
    if let Some(existing) = state.planner_pane.get(&candidate.brigade_id).cloned() {
        if existing.is_synthetic() {
            return Vec::new();
        }
        // The Goinkyo's reasoning holds word for word: a real key beside a row
        // with no session id is a pane from a Plan that ended without the
        // `NoPlanner` that would have released it (closed and opened again inside
        // one tick, or a restart that seeded the guard first), and a late
        // discovery would adopt it into the new Plan's row.
        state.planner_pane.remove(&candidate.brigade_id);
        let staged = matches!(
            &state.stage,
            Stage::Brigade { id, panes, .. }
                if *id == candidate.brigade_id && panes.contains(&existing)
        );
        let kill = kill_pane(state, existing.clone());
        if staged {
            state.unstage(&existing);
        }
        return kill.into_iter().chain([Cmd::Reload]).collect();
    }
    state
        .member_facts
        .remove(&(candidate.brigade_id, PLANNER_TOKEN.to_string()));
    let key = SessionKey::new_worker(candidate.brigade_id, PLANNER_TOKEN);
    if state.screens.contains_key(&key) || state.pending_opens.contains_key(&key) {
        return Vec::new();
    }
    state.planner_pane.insert(candidate.brigade_id, key.clone());
    state
        .member_tokens
        .insert(key.clone(), PLANNER_TOKEN.to_string());
    state
        .member_brigades
        .insert(key.clone(), candidate.brigade_id);
    state.pending_opens.insert(
        key.clone(),
        PendingOpen::BrigadeMember {
            brigade_id: candidate.brigade_id,
            first_turn: Some(AgentKind::ClaudeCode),
        },
    );
    vec![Cmd::OpenEmbedded {
        key,
        target: SessionToOpen {
            id: String::new(),
            agent: AgentKind::ClaudeCode,
            title: PLANNER_TOKEN.to_string(),
            cwd: candidate.cwd,
        },
        brigade: Some((
            candidate.brigade_id,
            PLANNER_TOKEN.to_string(),
            BrigadeRole::Planner,
        )),
        model: brigade.planner_model().map(str::to_string),
        effort: brigade.planner_effort().map(str::to_string),
        permission_mode: brigade.planner_permission_mode().map(str::to_string),
        disallowed_tools: None,
        autocompact: None,
        first_prompt: Some(PLANNER_FIRST_PROMPT.to_string()),
    }]
}

/// Answers `Event::GoinkyoAwaitingSpawn`: spawn the Goinkyo `observation`
/// names, at most once per consultation, for a brigade on stage or not; once
/// a consultation is observed to have ended, release the guard and close
/// whatever pane it left.
///
/// The one-shot guard is [`EmporiumState::goinkyo_pane`], not
/// [`EmporiumState::pending_opens`] (which this still populates, the same
/// way [`open_worker`] does, so [`update_spawned`] knows to append the new
/// pane to the staged brigade once it lands): `pending_opens` is cleared by
/// [`update_spawn_failed`] the moment a spawn fails, which leaves exactly
/// the same trace a Goinkyo that was never even attempted has — no session
/// id, no pane, either way. Without an entry that survives past that
/// removal, this — reachable roughly once a second for as long as the
/// condition holds — could not tell "just failed" from "never tried", and
/// would fire again next tick. Success needs no matching care: once the
/// Goinkyo actually has a pane, shell-side gathering stops reporting a
/// candidate for it at all, so nothing is left here to re-fire on
/// regardless of the guard.
///
/// The Goinkyo is started with a first prompt on its command line
/// ([`GOINKYO_FIRST_PROMPT`]), whichever product it is (the product is the row's,
/// see [`GoinkyoSpawnCandidate::agent`]): unlike a Worker, whose first turn the
/// operator gives, nobody sits at the Goinkyo's own keyboard, and a session
/// with nothing said to it does nothing with its briefing. What becomes of that
/// first turn is [`FirstTurnWatch`]'s to follow, riding on this same one-shot
/// guard rather than a marker of its own.
///
/// The `AwaitingSpawn` arm reads more than presence out of the guard: a
/// *synthetic* key there means a spawn for the current consultation is in
/// flight or already failed (the ordinary attempt-once case, above); a
/// *real* one means `goinkyo_pane` is still naming a pane from a
/// consultation that already ended without `NoGoinkyo` ever firing to
/// release it (`dismiss_goinkyo` immediately followed by a fresh
/// `consult_goinkyo`, or a banto restart before the resumed guard — see
/// `stage_brigade`'s own doc — ever got the chance to). Left alone, that
/// stale pane's own eventual discovery would silently write its session id
/// into whichever row now holds the `goinkyo` token, adopting it as the new
/// consultation's member with no generation check to catch the mismatch —
/// so this tears it down the same way `NoGoinkyo` does, rather than
/// spawning the new one on top of it.
fn update_goinkyo_awaiting_spawn(
    state: &mut EmporiumState,
    brigade: &BrigadeConfig,
    observation: GoinkyoObservation,
) -> Vec<Cmd> {
    let candidate = match observation {
        GoinkyoObservation::Unchanged => return Vec::new(),
        // The row disappearing out from under a still-staged brigade is
        // what actually means a consultation was dismissed. A disbanded
        // brigade reads the same way (`GoinkyoObservation`'s own doc), one
        // tick after `update_disbanded` closed its Workers' and Goinkyo's panes:
        // the kill below is then a repeat of one already issued.
        // Releasing the guard here rather than on success/failure is what lets
        // a *later* consultation on the same brigade spawn again, without
        // needing to know anything about the one before it — and closing
        // whatever pane the removed entry names is the other half of
        // `goinkyo_pane`'s own doc: nothing else knows which staged pane was
        // the Goinkyo's once its row is gone.
        GoinkyoObservation::NoGoinkyo { brigade_id } => {
            // Whether or not a pane is left to close, the consultation is over:
            // the next one joins the brigade afresh, after whoever joined
            // meanwhile.
            if let Some(joined) = state.member_order.get_mut(&brigade_id) {
                joined.retain(|listed| listed != GOINKYO_TOKEN);
            }
            forget_goinkyo_facts(state, brigade_id);
            // An open still held for the catalog is the ended consultation's:
            // there is no process to end, and the next consultation asks for its
            // own (a late answer for the round it was in finds nothing waiting).
            drop_held_creation_of_member(state, brigade_id, GOINKYO_TOKEN);
            let Some(key) = state.goinkyo_pane.remove(&brigade_id) else {
                return Vec::new();
            };
            // Unstaging only applies to a pane that is on stage; ending it
            // applies either way. A pane whose brigade is off stage is still
            // a running process — panes are pumped whether staged or not —
            // and this entry was the last thing that knew which process it
            // was. `Cmd::HangUpPty` naming a key with no handle is a no-op, so
            // a pane that already closed on its own costs nothing here.
            let staged = matches!(
                &state.stage,
                Stage::Brigade { id, panes, .. } if *id == brigade_id && panes.contains(&key)
            );
            let kill = kill_pane(state, key.clone());
            if staged {
                state.unstage(&key);
            }
            // The consultation's end as the Director's own process wrote it
            // (`dismiss_goinkyo`): that write archived the session and removed
            // the row, but nothing here refreshed the hidden set, so the session
            // stays hidden at every reveal level until some unrelated reload.
            // Asked for here, past the pane's removal, because this arm runs on
            // every tick for any brigade with no Goinkyo; only the tick that finds
            // a pane to release gets this far, which is once per consultation. A
            // consultation whose pane died first has no entry left (see
            // `update_pty_exited`) and gets no reload from here.
            return kill.into_iter().chain([Cmd::Reload]).collect();
        }
        // A brigade being closed has no Goinkyo to start: its Director's pane is
        // ending, and a Goinkyo started now would be a process of a brigade that
        // is not running. It is started, like any other member without a session,
        // when the brigade is opened again.
        GoinkyoObservation::AwaitingSpawn(candidate)
            if state.closing.contains_key(&candidate.brigade_id) =>
        {
            return Vec::new();
        }
        GoinkyoObservation::AwaitingSpawn(candidate) => candidate,
    };
    // The Goinkyo's row exists, so it has joined: the store's roster is the
    // truth about where (it replaces what this run learned), and without one
    // (an old capture) it joins at the end, which is where it is when nothing
    // else joined in the gap.
    if candidate.roster.is_empty() {
        record_join(state, candidate.brigade_id, GOINKYO_TOKEN);
    } else {
        state
            .member_order
            .insert(candidate.brigade_id, candidate.roster.clone());
    }
    if let Some(existing) = state.goinkyo_pane.get(&candidate.brigade_id).cloned() {
        if existing.is_synthetic() {
            // A spawn for the current consultation is already in flight, or
            // already failed and left this as its trace (see this
            // function's own doc on "just failed" vs "never tried") —
            // either way the attempt-once guarantee holds: don't retry.
            return Vec::new();
        }
        // A *real* key here, while this observation is `AwaitingSpawn` (the
        // row it's looking at right now has no session id), can only mean
        // one thing: `goinkyo_pane` still names a pane from a consultation
        // that already ended. Discovery and a session move both always write a
        // real id back to a row (`update_discovery_result`/`update_member_
        // session_moved`), and a live consultation's own row always keeps
        // its session id (`gather_goinkyo_looks` never reports
        // `AwaitingSpawn` for one) — so a real key paired with a
        // session-id-less row cannot arise from the same, still-open
        // consultation; the row behind that key was deleted and a new one
        // took its place.
        //
        // That holds only because the shell reads the row once every event
        // queued ahead of the observation has been handled (`next_event` in
        // `emporium.rs`). The event that rekeys the pane is the one whose
        // `SetMemberSession` writes the row, and an observation read between
        // the two shows exactly this pair for a Goinkyo that has just been
        // identified: two were hung up that way within a few milliseconds of
        // their discovery, when the read happened ahead of the queue. Nothing
        // here can tell the two apart.
        //
        // Two ways the real swap happens without `NoGoinkyo` ever
        // firing to release the guard first: `dismiss_goinkyo` immediately
        // followed by a fresh `consult_goinkyo`, close enough together that
        // the ~1Hz tick never observes the row-less moment in between; or a
        // banto restart, after which `stage_brigade`'s own resume of an
        // already-discovered Goinkyo is what seeds this entry (`stage_
        // brigade`'s own doc) — not `update_goinkyo_awaiting_spawn` — so a
        // dismiss right after *that* restart, before any fresh spawn ever
        // ran, hits the exact same "no entry to release" gap `NoGoinkyo`'s
        // own `let Some(key) = ... else { return }` already tolerates.
        // Left alone, the stale pane keeps running — invisibly adopted as
        // the new consultation's own member the moment its now-delayed
        // discovery finally writes a session id into whichever row still
        // holds the `goinkyo` token, since nothing here checks that it's
        // still the *same* request. Same teardown `NoGoinkyo` performs, so
        // the *next* tick starts the new consultation clean instead of
        // layering it onto a still-running process from the old one.
        state.goinkyo_pane.remove(&candidate.brigade_id);
        // Ended wherever it is, as `NoGoinkyo` does: a pane off stage is a
        // running process too, and returning without ending it would let the
        // next tick spawn a second Goinkyo beside it.
        let staged = matches!(
            &state.stage,
            Stage::Brigade { id, panes, .. }
                if *id == candidate.brigade_id && panes.contains(&existing)
        );
        let kill = kill_pane(state, existing.clone());
        if staged {
            state.unstage(&existing);
        }
        // An ended consultation, as in `NoGoinkyo`, and released only once (the
        // entry is gone): its session was archived and is still hidden here.
        return kill.into_iter().chain([Cmd::Reload]).collect();
    }
    // A new consultation starts with nothing of the last one's: its end may not
    // have been seen (dismissed and summoned again inside one tick).
    forget_goinkyo_facts(state, candidate.brigade_id);
    let key = SessionKey::new_worker(candidate.brigade_id, GOINKYO_TOKEN);
    // Belt-and-suspenders alongside `goinkyo_pane` above: the guard is what
    // actually distinguishes "just failed" from "never tried" (see this
    // function's own doc), but a pane or an in-flight open already existing
    // for this key — the same evidence `open_worker` checks through
    // `member_open_or_opening` — is a second, independent reason not to spawn again,
    // cheap to check now that this crate can build the key at all (the
    // shell-side gatherer cannot: `SessionKey::new_worker` is private to
    // this crate, which is exactly why this check lives here and not
    // there).
    if state.screens.contains_key(&key) || state.pending_opens.contains_key(&key) {
        return Vec::new();
    }
    state.goinkyo_pane.insert(candidate.brigade_id, key.clone());
    // Both ownership maps, as `open_worker` writes them, before the open is
    // issued: until discovery re-keys the pane they are all that says whose it
    // is, and the quiet watch, `live_panes_of` and the brigade marks each
    // look a pane up through the pair. With only the token, a Goinkyo spawned
    // for a brigade that is not on stage was invisible to all three.
    state
        .member_tokens
        .insert(key.clone(), GOINKYO_TOKEN.to_string());
    state
        .member_brigades
        .insert(key.clone(), candidate.brigade_id);
    // The product is what the row says: `consult_goinkyo` resolved it and
    // refused the consultation if that product could not work, so a config edit
    // since then must not send the spawn somewhere the refusal never looked. Only
    // a row with no product resolves it here, from the setting and the Director.
    let agent = candidate.agent.unwrap_or_else(|| {
        resolve_goinkyo_agent(
            brigade.goinkyo_agent,
            candidate.director_agent.unwrap_or(AgentKind::ClaudeCode),
        )
    });
    state.pending_opens.insert(
        key.clone(),
        PendingOpen::BrigadeMember {
            brigade_id: candidate.brigade_id,
            first_turn: Some(agent),
        },
    );
    // `permission_mode` and `disallowed_tools` are Claude flags: a Codex launch
    // has no field for either. The model and the effort are the product's own
    // words, so each product reads its own key and never the other's.
    let claude_only = |value: Option<&str>| {
        value
            .filter(|_| agent == AgentKind::ClaudeCode)
            .map(str::to_string)
    };
    let model = brigade.goinkyo_model_for(agent).map(str::to_string);
    let held = agent == AgentKind::Codex && model.is_some();
    let open = Cmd::OpenEmbedded {
        key,
        target: SessionToOpen {
            id: String::new(),
            agent,
            title: "goinkyo".to_string(),
            cwd: candidate.cwd,
        },
        brigade: Some((
            candidate.brigade_id,
            GOINKYO_TOKEN.to_string(),
            BrigadeRole::Goinkyo,
        )),
        model,
        effort: brigade.goinkyo_effort_for(agent).map(str::to_string),
        permission_mode: claude_only(brigade.goinkyo_permission_mode()),
        disallowed_tools: claude_only(brigade.goinkyo_disallowed_tools()),
        autocompact: None,
        first_prompt: Some(GOINKYO_FIRST_PROMPT.to_string()),
    };
    // A Codex model may be a family word, which has to meet the catalog before it
    // can be passed (`open_worker`'s doc). Held like a Worker's: the same queue,
    // the same round, the same answer. The one-shot guard and the placeholder
    // key's maps were written above, so nothing opens a second one meanwhile.
    if held {
        return hold_for_catalog(state, open);
    }
    vec![open]
}

