    #[test]
    fn tick_relay_decision_resets_on_drain_so_the_next_batch_starts_fresh() {
        let mut states = HashMap::new();
        let brigade_id = 1;
        let token = "worker-1".to_string();
        let now = test_instant();

        tick_relay_decision(&mut states, brigade_id, &token, now, Some(true), true, true);
        assert!(tick_relay_decision(
            &mut states,
            brigade_id,
            &token,
            now,
            Some(true),
            true,
            true,
        ));
        assert_eq!(
            states
                .get(&(brigade_id, token.clone()))
                .unwrap()
                .nudge
                .attempts,
            1
        );

        assert!(!tick_relay_decision(
            &mut states,
            brigade_id,
            &token,
            now,
            Some(true),
            true,
            false,
        ));
        assert!(!states.contains_key(&(brigade_id, token.clone())));

        assert!(!tick_relay_decision(
            &mut states,
            brigade_id,
            &token,
            now,
            Some(true),
            true,
            true,
        ));
        assert_eq!(
            states
                .get(&(brigade_id, token.clone()))
                .unwrap()
                .idle_streak,
            1
        );
        assert_eq!(
            states
                .get(&(brigade_id, token.clone()))
                .unwrap()
                .nudge
                .attempts,
            0
        );
    }

    #[test]
    fn tick_relay_decision_stops_after_the_attempt_cap_even_past_cooldown() {
        let mut states = HashMap::new();
        let brigade_id = 1;
        let token = "worker-1".to_string();
        let mut now = test_instant();

        tick_relay_decision(&mut states, brigade_id, &token, now, Some(true), true, true);
        for _ in 0..RELAY_MAX_ATTEMPTS {
            now += RELAY_NUDGE_COOLDOWN + Duration::from_secs(1);
            assert!(tick_relay_decision(
                &mut states,
                brigade_id,
                &token,
                now,
                Some(true),
                true,
                true,
            ));
        }
        assert_eq!(
            states
                .get(&(brigade_id, token.clone()))
                .unwrap()
                .nudge
                .attempts,
            RELAY_MAX_ATTEMPTS
        );

        now += RELAY_NUDGE_COOLDOWN + Duration::from_secs(1);
        assert!(!tick_relay_decision(
            &mut states,
            brigade_id,
            &token,
            now,
            Some(true),
            true,
            true,
        ));
    }

