    #[test]
    fn tick_issues_a_wake_without_writing_to_the_pty() {
        let mut state = EmporiumState::new(PrefixKey::default());
        let director = SessionKey::from_id("dir");
        let worker = SessionKey::from_id("w1");
        state.screens.insert(director.clone(), Screen::new(24, 80));
        state.screens.insert(worker.clone(), Screen::new(24, 80));
        state.stage = Stage::Brigade {
            id: 1,
            director: None,
            panes: vec![director, worker.clone()],
            focused: 0,
        };
        let mut app = app_with(vec![]);
        let brigade = brigade_config();
        let mut now = test_instant();

        let observation = || RelayObservation {
            live: None,
            glance: None,
            brigade_id: 1,
            token: "worker-1".to_string(),
            key: worker.clone(),
            wake_pending: false,
            has_unseen: true,
            is_idle_this_tick: Some(true),
            agent: None,
            briefed_since_launch: None,
        };
        // Isolates the WritePty cmds from any incidental ResizePty (the
        // fresh 24x80 `Screen`s almost certainly don't match the pane
        // geometry computed from `EmporiumState::new()`'s default `size` —
        // not what this test is about).
        let writes = |cmds: &[Cmd]| -> Vec<(SessionKey, Vec<u8>)> {
            cmds.iter()
                .filter_map(|cmd| match cmd {
                    Cmd::WritePty { key, bytes } => Some((key.clone(), bytes.clone())),
                    _ => None,
                })
                .collect()
        };

        // First tick: idle streak only reaches 1 — not eligible yet.
        let cmds = update(
            &mut state,
            &mut app,
            &brigade,
            Event::Tick {
                relay: vec![observation()],
                brigades: Vec::new(),
            },
            now,
        );
        assert!(writes(&cmds).is_empty());

        // Second consecutive idle tick: issue the wake, without a PTY write.
        now += Duration::from_secs(1);
        let cmds = update(
            &mut state,
            &mut app,
            &brigade,
            Event::Tick {
                relay: vec![observation()],
                brigades: Vec::new(),
            },
            now,
        );
        assert!(writes(&cmds).is_empty());
        assert!(cmds.iter().any(|cmd| matches!(cmd, Cmd::Store(StoreIntent::IssueWake { brigade_id: 1, token }) if token == "worker-1")));
        assert!(
            state
                .status
                .as_deref()
                .unwrap()
                .contains("nudged worker-1 of brigade 1")
        );

        // No delayed Enter is queued.
        now += Duration::from_millis(50);
        let cmds = update(
            &mut state,
            &mut app,
            &brigade,
            Event::Tick {
                relay: vec![],
                brigades: Vec::new(),
            },
            now,
        );
        assert!(writes(&cmds).is_empty());

        now += Duration::from_millis(300);
        let cmds = update(
            &mut state,
            &mut app,
            &brigade,
            Event::Tick {
                relay: vec![],
                brigades: Vec::new(),
            },
            now,
        );
        assert!(writes(&cmds).is_empty());
    }

    // --- first prompts and their watch: open_worker / update_spawned / update_tick --

    /// The whole text of each first-turn notice, written out rather than built
    /// from the source's own pieces, so a stray run of spaces or a changed word in
    /// the status line fails a test. For `worker-1` of a brigade the app holds no
    /// title for.
    const NOTICE_NO_TURN: &str = "worker-1 of brigade 1: its first prompt started no turn 15s after launch — answer what the pane shows, or type its first line yourself";
    const NOTICE_UNIDENTIFIED: &str = "worker-1 of brigade 1: took its first turn but was not identified — banto's hook did not run, most likely because Codex does not trust it";

    /// A Codex Worker created by `open_worker` and spawned as the shell reports
    /// it, at the returned instant. The screen is blank: each test paints what it
    /// is about.
    fn spawned_codex_worker() -> (EmporiumState, App, BrigadeConfig, SessionKey, Instant) {
        let mut state = EmporiumState::new(PrefixKey::default());
        let mut app = app_with(vec![]);
        let brigade = brigade_config();
        open_worker(
            &mut state,
            1,
            "worker-1",
            std::path::Path::new("/work"),
            WorkerChoice {
                agent: AgentKind::Codex,
                model: "",
                effort: "",
            },
            RoleLaunch::default(),
        );
        let key = SessionKey::new_worker(1, "worker-1");
        let t0 = test_instant();
        update(
            &mut state,
            &mut app,
            &brigade,
            Event::Spawned {
                key: key.clone(),
                agent: None,
            },
            t0,
        );
        (state, app, brigade, key, t0)
    }

    /// One relay tick with nothing observed, at `at`.
    fn quiet_tick(
        state: &mut EmporiumState,
        app: &mut App,
        brigade: &BrigadeConfig,
        at: Instant,
    ) -> Vec<Cmd> {
        goinkyo_tick_observing(state, app, brigade, Vec::new(), at)
    }

    /// A Claude Goinkyo created and spawned the way `update_goinkyo_awaiting_spawn`
    /// and the shell do, at the returned instant, with no live-file observation.
    fn spawned_claude_goinkyo() -> (EmporiumState, App, BrigadeConfig, SessionKey, Instant) {
        let mut state = EmporiumState::new(PrefixKey::default());
        let mut app = app_with(vec![]);
        let brigade = BrigadeConfig {
            goinkyo_agent: GoinkyoAgentSetting::Claude,
            ..brigade_config()
        };
        let cmds = update(
            &mut state,
            &mut app,
            &brigade,
            awaiting_spawn(1),
            test_instant(),
        );
        let [Cmd::OpenEmbedded { key, .. }] = cmds.as_slice() else {
            panic!("expected exactly one OpenEmbedded, got {cmds:?}");
        };
        let key = key.clone();
        let t0 = test_instant();
        update(
            &mut state,
            &mut app,
            &brigade,
            Event::Spawned {
                key: key.clone(),
                agent: None,
            },
            t0,
        );
        (state, app, brigade, key, t0)
    }

