    /// State a member's name the way an event does, and resolve the roster.
    fn set_name(state: &mut EmporiumState, brigade: BrigadeId, token: &str, name: Option<&str>) {
        state.state_member_name(brigade, token, name);
        state.resolve_member_names(brigade);
    }

    /// What a status calls the members of two brigades once some are named.
    #[test]
    fn a_status_calls_a_named_member_by_its_name_alone_and_an_unnamed_one_by_its_token() {
        let mut state = state_with_facts(vec![
            name_facts(1, "Alpha", None),
            name_facts(2, "Beta", None),
        ]);
        set_name(&mut state, 1, "worker-1", Some("impl"));
        set_name(&mut state, 2, "worker-1", Some("docs"));
        let app = app_with(vec![]);
        let m = |id: Option<BrigadeId>, token: &str| (id, token.to_string());

        assert_eq!(state.member_call(Some(1), "worker-1"), "\"impl\"");
        assert_eq!(state.member_call(Some(1), "worker-2"), "worker-2");
        // The same token is another member in another brigade; a member with no
        // brigade known has only its token.
        assert_eq!(state.member_call(Some(2), "worker-1"), "\"docs\"");
        assert_eq!(state.member_call(None, "worker-1"), "worker-1");
        assert_eq!(
            state.members_phrase(
                &app,
                &[
                    m(Some(1), "worker-1"),
                    m(Some(1), "worker-2"),
                    m(Some(2), "worker-1")
                ]
            ),
            "\"impl\", worker-2 of \"Alpha\" and \"docs\" of \"Beta\""
        );
        assert_eq!(
            state.members_phrase(&app, &[m(None, "worker-1")]),
            "member worker-1"
        );

        // A pane's status names its member the same way.
        let key = SessionKey::from_id("w1");
        state
            .member_tokens
            .insert(key.clone(), "worker-1".to_string());
        state.member_brigades.insert(key.clone(), 1);
        assert_eq!(state.pane_label(&app, &key), "\"impl\" of \"Alpha\"");
        set_name(&mut state, 1, "worker-1", None);
        assert_eq!(state.pane_label(&app, &key), "worker-1 of \"Alpha\"");
    }

    #[test]
    fn the_nudge_status_names_the_nudged_member_and_the_sender_by_their_names() {
        let (mut state, _, brigade, director, start) = reading_fixture();
        state
            .brigade_names
            .insert(1, name_facts(1, "Frozen", Some("a-dir")));
        let mut app = app_with(vec![titled("a-dir", Some("Fix the relay draft guard"))]);
        let tick = |state: &mut EmporiumState, app: &mut App, at: Duration| {
            update(
                state,
                app,
                &brigade,
                Event::Tick {
                    relay: vec![RelayObservation {
                        brigade_id: 1,
                        token: "director".to_string(),
                        key: director.clone(),
                        wake_pending: false,
                        has_unseen: true,
                        is_idle_this_tick: Some(true),
                        agent: CLAUDE,
                        live: None,
                        glance: Some(said_by(Some("worker-3"), "stage 2 is done")),
                        briefed_since_launch: None,
                    }],
                    // The roster's names, as the gather sends them: the sender's,
                    // and the nudged member's (a stand-in for a Worker: the core
                    // does not care which member it is).
                    brigades: vec![BrigadeNameFacts {
                        member_names: vec![
                            ("director".to_string(), "lead".to_string()),
                            ("worker-3".to_string(), "impl".to_string()),
                        ],
                        ..name_facts(1, "Frozen", Some("a-dir"))
                    }],
                },
                start + at,
            );
        };
        tick(&mut state, &mut app, Duration::ZERO);
        tick(&mut state, &mut app, Duration::from_secs(1));
        assert_eq!(
            state.status.as_deref(),
            Some(
                "relay: nudged \"lead\" of \"Fix the relay draft guard\" \u{2190} \"impl\": stage 2 is done"
            )
        );

        // Unnamed on both ends: tokens, as before.
        assert_eq!(
            nudge_status_with(Some(said_by(Some("worker-3"), "stage 2 is done"))),
            "relay: nudged director of \"Fix the relay draft guard\" \u{2190} worker-3: stage 2 is done"
        );
    }

    #[test]
    fn members_are_grouped_by_brigade_so_each_name_is_said_once() {
        let mut state = state_with_facts(vec![
            name_facts(1, "Alpha", None),
            name_facts(2, "Beta", None),
            name_facts(3, "Gamma", None),
        ]);
        state.brigade_names.get_mut(&3).unwrap().name = "Gamma".to_string();
        let app = app_with(vec![]);
        let m = |id: Option<BrigadeId>, token: &str| (id, token.to_string());

        // One member.
        assert_eq!(
            state.members_phrase(&app, &[m(Some(2), "worker-2")]),
            "worker-2 of \"Beta\""
        );
        // The Director is a member like any other.
        assert_eq!(
            state.members_phrase(&app, &[m(Some(1), "director")]),
            "director of \"Alpha\""
        );
        // Several of one brigade: in the order given.
        assert_eq!(
            state.members_phrase(&app, &[m(Some(1), "worker-3"), m(Some(1), "worker-1")]),
            "worker-3, worker-1 of \"Alpha\""
        );
        // Two brigades: grouped by first appearance, members in order.
        assert_eq!(
            state.members_phrase(
                &app,
                &[
                    m(Some(2), "worker-2"),
                    m(Some(1), "worker-1"),
                    m(Some(2), "worker-4")
                ]
            ),
            "worker-2, worker-4 of \"Beta\" and worker-1 of \"Alpha\""
        );
        // Three: separated by ';' since a group's own members use commas.
        assert_eq!(
            state.members_phrase(
                &app,
                &[
                    m(Some(1), "worker-1"),
                    m(Some(1), "worker-2"),
                    m(Some(2), "worker-1"),
                    m(Some(3), "director")
                ]
            ),
            "worker-1, worker-2 of \"Alpha\"; worker-1 of \"Beta\" and director of \"Gamma\""
        );
        // No brigade known for a pane: it stands alone, as before.
        assert_eq!(
            state.members_phrase(&app, &[m(None, "worker-1")]),
            "member worker-1"
        );
        // Nothing known about a brigade: its number, said once.
        let bare = state_with_facts(vec![]);
        assert_eq!(
            bare.members_phrase(&app, &[m(Some(8), "worker-1"), m(Some(8), "worker-2")]),
            "worker-1, worker-2 of brigade 8"
        );
    }

    /// A tick for the fixture's Director carrying `glance`.
    fn tick_with_glance(
        state: &mut EmporiumState,
        app: &mut App,
        brigade: &BrigadeConfig,
        key: &SessionKey,
        glance: Option<MemberGlance>,
        now: Instant,
    ) {
        update(
            state,
            app,
            brigade,
            Event::Tick {
                relay: vec![RelayObservation {
                    live: None,
                    glance,
                    brigade_id: 1,
                    token: "director".to_string(),
                    key: key.clone(),
                    wake_pending: false,
                    has_unseen: true,
                    is_idle_this_tick: Some(true),
                    agent: CLAUDE,
                    briefed_since_launch: None,
                }],
                brigades: Vec::new(),
            },
            now,
        );
    }

    fn said_by(sender: Option<&str>, line: &str) -> MemberGlance {
        MemberGlance {
            inbound: Some(MessageGlance {
                created_at_ms: 1,
                line: line.to_string(),
                from_token: sender.map(str::to_string),
            }),
            sent: None,
        }
    }

    /// The status the second of two idle ticks leaves, when that second
    /// tick's observation carries `glance`.
    fn nudge_status_with(glance: Option<MemberGlance>) -> String {
        let (mut state, _, brigade, director, start) = reading_fixture();
        state
            .brigade_names
            .insert(1, name_facts(1, "Frozen", Some("a-dir")));
        let mut app = app_with(vec![titled("a-dir", Some("Fix the relay draft guard"))]);
        tick_with_glance(&mut state, &mut app, &brigade, &director, None, start);
        tick_with_glance(
            &mut state,
            &mut app,
            &brigade,
            &director,
            glance,
            start + Duration::from_secs(1),
        );
        state.status.clone().unwrap_or_default()
    }

    #[test]
    fn the_nudge_status_quotes_the_sender_and_first_line_of_the_message_that_prompted_it() {
        let status = nudge_status_with(Some(said_by(
            Some("worker-3"),
            "stage 2 is done in the working tree",
        )));
        assert_eq!(
            status,
            "relay: nudged director of \"Fix the relay draft guard\" \u{2190} worker-3: stage 2 is done in the working tree"
        );
    }

    #[test]
    fn the_glance_of_the_very_tick_that_nudges_is_the_one_quoted() {
        // The member's facts are filled at the top of `update_tick`, before the
        // nudge decision: the first tick (idle streak 1) carried an older
        // message, the second (the nudging one) a newer, and the status quotes
        // the newer.
        let (mut state, _, brigade, director, start) = reading_fixture();
        let mut app = app_with(vec![]);
        tick_with_glance(
            &mut state,
            &mut app,
            &brigade,
            &director,
            Some(said_by(Some("worker-1"), "the old one")),
            start,
        );
        tick_with_glance(
            &mut state,
            &mut app,
            &brigade,
            &director,
            Some(said_by(Some("worker-2"), "the one that just arrived")),
            start + Duration::from_secs(1),
        );
        let status = state.status.clone().unwrap_or_default();
        assert!(
            status.starts_with("relay: nudged director of brigade 1"),
            "{status}"
        );
        assert!(
            status.ends_with("\u{2190} worker-2: the one that just arrived"),
            "{status}"
        );
        // A tick that re-reads nothing (`glance: None`) quotes what the core held.
        let (mut state, _, brigade, director, start) = reading_fixture();
        let mut app = app_with(vec![]);
        tick_with_glance(
            &mut state,
            &mut app,
            &brigade,
            &director,
            Some(said_by(Some("worker-1"), "kept")),
            start,
        );
        tick_with_glance(
            &mut state,
            &mut app,
            &brigade,
            &director,
            None,
            start + Duration::from_secs(1),
        );
        assert!(
            state
                .status
                .clone()
                .unwrap_or_default()
                .ends_with("\u{2190} worker-1: kept")
        );
    }

