    #[test]
    fn a_recorded_tick_whose_stage_has_no_write_time_still_parses_as_written_long_ago() {
        let mut facts = name_facts(3, "A title", Some("dir"));
        facts.progress = Some(ProgressGlance {
            seq: 2,
            stage: "review".to_string(),
            updated_at_ms: 1_700_000_000_000,
        });
        let tick = Event::Tick {
            relay: vec![],
            brigades: vec![facts],
        };
        let mut json: serde_json::Value = serde_json::to_value(&tick).unwrap();
        let glance = &mut json["Tick"]["brigades"][0]["progress"];
        assert!(
            glance
                .as_object_mut()
                .unwrap()
                .remove("updated_at_ms")
                .is_some()
        );
        let Event::Tick { brigades, .. } = serde_json::from_value(json).unwrap() else {
            panic!("a tick");
        };
        let glance = brigades[0].progress.as_ref().unwrap();
        assert_eq!(
            (glance.seq, glance.stage.as_str(), glance.updated_at_ms),
            (2, "review", 0)
        );
    }

    #[test]
    fn only_a_directors_pane_reads_its_brigades_stage_wherever_it_stands_in_the_stack() {
        let mut state = state_with_facts(vec![name_facts(1, "cell", Some("dir"))]);
        state.brigade_names.get_mut(&1).unwrap().progress = Some(ProgressGlance {
            seq: 1,
            stage: "review".to_string(),
            updated_at_ms: 7,
        });
        let host = |state: &mut EmporiumState, id: &str, token: &str, brigade: BrigadeId| {
            let key = SessionKey::from_id(id);
            state.member_tokens.insert(key.clone(), token.to_string());
            state.member_brigades.insert(key.clone(), brigade);
            key
        };
        let worker = host(&mut state, "w1", "worker-1", 1);
        let director = host(&mut state, "dir", DIRECTOR_TOKEN, 1);
        // The Worker is first in the stack, and so is the one a position-based rule
        // would have picked.
        state.stage = Stage::Brigade {
            id: 1,
            director: Some(director.clone()),
            panes: vec![worker.clone(), director.clone()],
            focused: 0,
        };
        assert_eq!(
            state.director_progress(&director).map(|g| g.updated_at_ms),
            Some(7)
        );
        assert_eq!(state.director_progress(&worker), None);
        assert_eq!(
            state.director_progress(&SessionKey::from_id("stranger")),
            None
        );
        // A brigade with no Progress has nothing to show.
        state.brigade_names.get_mut(&1).unwrap().progress = None;
        assert_eq!(state.director_progress(&director), None);
    }

    #[test]
    fn the_new_event_fields_round_trip_and_older_captures_still_parse() {
        let loaded = Event::SidebarWidthLoaded { width: Some(44) };
        let json = serde_json::to_string(&loaded).unwrap();
        assert_eq!(serde_json::from_str::<Event>(&json).unwrap(), loaded);

        let resolved = Event::MembershipResolved {
            session_id: "dir".to_string(),
            membership: Some((1, "director".to_string(), BrigadeRole::Director)),
            members: Some(vec![]),
            layout: Some(stored_arrangement()),
            names: Vec::new(),
        };
        let json = serde_json::to_string(&resolved).unwrap();
        assert_eq!(serde_json::from_str::<Event>(&json).unwrap(), resolved);

        // A capture from before `layout` existed.
        let old = r#"{"MembershipResolved":{"session_id":"dir","membership":null,"members":null}}"#;
        let Event::MembershipResolved { layout, .. } = serde_json::from_str::<Event>(old).unwrap()
        else {
            panic!("expected MembershipResolved");
        };
        assert_eq!(layout, None);

        // The intents round trip too (they sit in recorded Cmd histories).
        let intent = StoreIntent::SaveBrigadeLayout {
            brigade_id: 2,
            layout: stored_arrangement(),
        };
        let json = serde_json::to_string(&intent).unwrap();
        assert_eq!(serde_json::from_str::<StoreIntent>(&json).unwrap(), intent);
    }

    #[test]
    fn the_keys_m_z_and_capital_m_refuse_with_a_reason_where_they_make_no_sense() {
        // The sidebar.
        let (mut state, mut app, brigade, now) = drag_fixture(3);
        state.focus = Focus::Sidebar;
        for (key, mods, expected) in [
            ('m', Modifiers::NONE, "prefix: focus a tile to collapse it"),
            ('z', Modifiers::NONE, "prefix: focus a tile to solo it"),
        ] {
            prefix_key(
                &mut state,
                &mut app,
                &brigade,
                KeyCode::Char(key),
                mods,
                now,
            );
            assert_eq!(state.status.as_deref(), Some(expected));
        }
        // The master.
        focus_stack_slot(&mut state, 0);
        prefix_key(
            &mut state,
            &mut app,
            &brigade,
            KeyCode::Char('m'),
            Modifiers::NONE,
            now,
        );
        assert_eq!(
            state.status.as_deref(),
            Some("prefix: the master tile can't be collapsed")
        );
        // The master takes a solo (and turns it off again): it has a member.
        prefix_key(
            &mut state,
            &mut app,
            &brigade,
            KeyCode::Char('z'),
            Modifiers::NONE,
            now,
        );
        assert_eq!(layout_of(&state).solo_member.as_deref(), Some("director"));
        assert!(layout_of(&state).minimized.is_empty());
        prefix_key(
            &mut state,
            &mut app,
            &brigade,
            KeyCode::Char('z'),
            Modifiers::NONE,
            now,
        );
        assert_eq!(layout_of(&state).solo_member, None);

        // A master with no member token has nothing to key a solo by.
        state.member_tokens.remove(&key_of("dir"));
        prefix_key(
            &mut state,
            &mut app,
            &brigade,
            KeyCode::Char('z'),
            Modifiers::NONE,
            now,
        );
        assert_eq!(
            state.status.as_deref(),
            Some("prefix: this tile has no member to solo")
        );
        assert_eq!(layout_of(&state).solo_member, None);

        // A solo (single-session) stage.
        let (mut state, mut app, brigade, now) = drag_fixture(0);
        state.stage = Stage::Solo(key_of("dir"));
        for key in ['m', 'z'] {
            prefix_key(
                &mut state,
                &mut app,
                &brigade,
                KeyCode::Char(key),
                Modifiers::NONE,
                now,
            );
            assert!(state.status.is_some(), "{key}");
        }
        prefix_key(
            &mut state,
            &mut app,
            &brigade,
            KeyCode::Char('M'),
            Modifiers::SHIFT,
            now,
        );
        assert_eq!(state.status.as_deref(), Some("prefix: no stack to restore"));
    }

