    fn press_enter(
        state: &mut EmporiumState,
        app: &mut App,
        brigade: &BrigadeConfig,
        now: Instant,
    ) -> Vec<Cmd> {
        update(
            state,
            app,
            brigade,
            Event::Input(InputEvent::Key(KeyEvent::new(
                KeyCode::Enter,
                Modifiers::NONE,
            ))),
            now,
        )
    }

